      {isComment ? (
        <svg viewBox="0 0 24 24" className="h-full w-full" fill="none" aria-hidden="true">
          <path d="M20 11.5a8 8 0 0 1-8 8 9 9 0 0 1-3.5-.7L4 20l1.2-4.5a8 8 0 1 1 14.8-4Z" fill="white" />
          <circle cx="8" cy="11.5" r="1" fill="#2563eb" />
          <circle cx="12" cy="11.5" r="1" fill="#2563eb" />
          <circle cx="16" cy="11.5" r="1" fill="#2563eb" />
        </svg>
      ) : !pngFailed ? (
        <img
          src={pngSrc}
          alt=""
          className="h-full w-full scale-[1.24] rounded-full object-cover"
          onError={() =>
            setPngFailed(true)
          }
        />
      ) : platform === "telegram" ? (
        <TelegramSourceIcon className="h-full w-full" />
      ) : (
        <MessengerSourceIcon className="h-full w-full" />
      )}
    </span>
  );
}

function isPersonalConversation(
  conversation: InboxConversation,
  channelDirectory: ChannelDirectory,
) {
  const accountId = conversation.social_account?.id;
  const extended = conversation as InboxConversation & {
    social_account?: (InboxConversation["social_account"] & { platform?: string | null }) | null;
  };
  return (
    (accountId ? channelDirectory[accountId]?.platform === "telegram_personal" : false) ||
    extended.social_account?.platform === "telegram_personal"
  );
}

function getConversationPlatform(
  conversation: InboxConversation,
  channelDirectory: ChannelDirectory,
  channelDirectoryLoaded: boolean,
): ConversationPlatform | null {
  const socialAccountId =
    conversation.social_account
      ?.id;

  const registeredChannel =
    socialAccountId
      ? channelDirectory[
          socialAccountId
        ]
      : null;

  if (
    registeredChannel?.platform ===
      "telegram" ||
    registeredChannel?.platform ===
      "telegram_personal"
  ) {
    return "telegram";
  }

  if (
    registeredChannel?.platform ===
    "facebook"
  ) {
    return "messenger";
  }

  const extended =
    conversation as InboxConversation & {
      platform?: string | null;
      source_type?: string | null;
      social_account?:
        | (InboxConversation["social_account"] & {
            platform?: string | null;
          })
        | null;
    };

  const explicitPlatform =
    extended.platform
      ?.trim()
      .toLowerCase() ||
    extended.social_account
      ?.platform
      ?.trim()
      .toLowerCase() ||
    "";

  if (
    explicitPlatform ===
      "telegram" ||
    explicitPlatform ===
      "telegram_personal"
  ) {
    return "telegram";
  }

  if (
    explicitPlatform ===
      "facebook" ||
    explicitPlatform ===
      "messenger"
  ) {
    return "messenger";
  }

  /*
   * Do not guess Messenger while /api/inbox/channels is still loading.
   * Telegram rows whose server payload does not include platform metadata
   * used to flash a Messenger badge during navigation/loading.
   */
  if (!channelDirectoryLoaded) {
    return null;
  }

  /*
   * Legacy TENH rows without platform metadata are historical Messenger
   * conversations. Use that fallback only after channel lookup finishes.
   */
  return "messenger";
}

function getConversationChannel(
  conversation: InboxConversation,
  channelDirectory?: ChannelDirectory,
) {
  const extended =
    conversation as InboxConversation & {
      platform?: string | null;
      source_type?: string | null;
      social_account?:
        | (InboxConversation["social_account"] & {
            platform?: string | null;
          })
        | null;
    };

  const sourceType =
    extended.source_type
      ?.trim()
      .toLowerCase() || "";

  if (sourceType === "comment") {
    return "comment" as const;
  }

  const socialAccountId =
    conversation.social_account?.id;
  const registeredPlatform =
    socialAccountId && channelDirectory
      ? channelDirectory[socialAccountId]?.platform
      : null;

  if (registeredPlatform === "telegram" || registeredPlatform === "telegram_personal") {
    return "telegram" as const;
  }

  const explicitPlatform =
    extended.platform
      ?.trim()
      .toLowerCase() ||
    extended.social_account
      ?.platform
      ?.trim()
      .toLowerCase() ||
    "";

  if (
    sourceType === "telegram" ||
    explicitPlatform === "telegram" ||
    explicitPlatform === "telegram_personal"
  ) {
    return "telegram" as const;
  }

  return "messenger" as const;
}

function isConversationPinned(
  conversation:
    InboxConversation,
) {
  return Boolean(
    (
      conversation as
        InboxConversation & {
          is_pinned?:
            boolean;
        }
    ).is_pinned,
  );
}

function getSavedViewFromKey(
  key: string,
  savedViews:
    SavedView[],
) {
  if (
    !key.startsWith(
      "saved:",
    )
  ) {
    return null;
  }

  const id =
    key.slice(
      "saved:".length,
    );

  return (
    savedViews.find(
      (view) =>
        view.id === id,
    ) ?? null
  );
}

function matchesSavedView({
  conversation,
  view,
  memberId,
  memberIdByBusiness,
  workspaceContextId,
  channelDirectory,
}: {
  conversation:
    InboxConversation;
  view:
    SavedView;
  memberId:
    | string
    | null;
  memberIdByBusiness?: Record<string, string>;
  workspaceContextId?: string | null;
  channelDirectory?: ChannelDirectory;
}) {
  const filters =
    normalizeSavedViewFilters(
      view.filters,
    );

  if (
    filters.workspaceScope === "current"
  ) {
    if (
      !workspaceContextId ||
      conversation.business_id !== workspaceContextId
    ) {
      return false;
    }
  } else if (
    filters.workspaceScope === "selected"
  ) {
    if (
      filters.workspaceIds.length === 0 ||
      !filters.workspaceIds.includes(
        conversation.business_id,
      )
    ) {
      return false;
    }
  }

  if (
    filters.status !==
      "any" &&
    conversation.status !==
      filters.status
  ) {
    return false;
  }

  if (
    filters.unreadOnly &&
    conversation.unread_count <=
      0
  ) {
    return false;
  }

  if (
    filters.pinnedOnly &&
    !isConversationPinned(
      conversation,
    )
  ) {
    return false;
  }

  if (
    filters.channel !==
      "any" &&
    getConversationChannel(
      conversation,
      channelDirectory,
    ) !== filters.channel
  ) {
    return false;
  }

  if (
    filters.assignment ===
    "me"
  ) {
    const workspaceMemberId =
      memberIdByBusiness?.[
        conversation.business_id
      ] ?? memberId;

    if (
      !workspaceMemberId ||
      conversation.assigned_to !==
        workspaceMemberId
    ) {
      return false;
    }
  } else if (
    filters.assignment ===
    "assigned"
  ) {
    if (
      !conversation.assigned_to
    ) {
      return false;
    }
  } else if (
    filters.assignment ===
    "unassigned"
  ) {
    if (
      conversation.assigned_to
    ) {
      return false;
    }
  }

  if (
    filters.tagIds.length >
    0
  ) {
    const conversationTags =
      conversation.contact
        ?.tags ?? [];

    const conversationTagIds =
      new Set(
        conversationTags.map(
          (tag) => tag.id,
        ),
      );

    const conversationTagNames =
      new Set(
        conversationTags.map(
          (tag) =>
            tag.name
              .trim()
              .toLowerCase(),
        ),
      );

    const allowLegacyNameFallback =
      filters.workspaceScope === "current" ||
      (filters.workspaceScope === "selected" &&
        filters.workspaceIds.length === 1);

    /*
     * New references are workspace-scoped (`businessId::tagId`) so identical
     * tag names across subscriptions can never collide. Plain UUID/tag IDs
     * from older TENH Smart Views remain valid. The historical tag-name
     * fallback is intentionally limited to a single workspace because a
     * label like "VIP" is ambiguous across multiple businesses.
     */
    const hasSelectedTag =
      filters.tagIds.some(
        (tagReference) => {
          const scopedReference =
            parseSmartViewTagReference(
              tagReference,
            );

          if (scopedReference) {
            return (
              conversation.business_id ===
                scopedReference.workspaceId &&
              conversationTagIds.has(
                scopedReference.tagId,
              )
            );
          }

          if (
            conversationTagIds.has(
              tagReference,
            )
          ) {
            return true;
          }

          return (
            allowLegacyNameFallback &&
            conversationTagNames.has(
              tagReference
                .trim()
                .toLowerCase(),
            )
          );
        },
      );

    if (!hasSelectedTag) {
      return false;
    }
  }

  return true;
}

function matchesView({
  conversation,
  key,
  savedViews,
  memberId,
  memberIdByBusiness,
  workspaceContextId,
  channelDirectory,
}: {
  conversation:
    InboxConversation;
  key: string;
  savedViews:
    SavedView[];
  memberId:
    | string
    | null;
  memberIdByBusiness?: Record<string, string>;
  workspaceContextId?: string | null;
  channelDirectory?: ChannelDirectory;
}) {
  if (
    key === "all"
  ) {
    return true;
  }

  if (
    key === "unread"
  ) {
    return (
      conversation.unread_count >
      0
    );
  }

  if (
    key === "my"
  ) {
    const workspaceMemberId =
      memberIdByBusiness?.[
        conversation.business_id
      ] ?? memberId;

    return Boolean(
      workspaceMemberId &&
        conversation.assigned_to ===
          workspaceMemberId,
    );
  }

  if (
    key ===
    "unassigned"
  ) {
    return !conversation.assigned_to;
  }

  if (
    key === "comment"
  ) {
    return (
      getConversationChannel(
        conversation,
        channelDirectory,
      ) === "comment"
    );
  }

  if (
    key === "open"
  ) {
    return conversation.status === "open";
  }

  if (
    key === "pinned"
  ) {
    return isConversationPinned(
      conversation,
    );
  }

  const savedView =
    getSavedViewFromKey(
      key,
      savedViews,
    );

  if (!savedView) {
    return true;
  }

  return matchesSavedView({
    conversation,
    view:
      savedView,
    memberId,
    memberIdByBusiness,
    workspaceContextId,
    channelDirectory,
  });
}

function viewKeyFromUrl(
  value:
    | string
    | null,
) {
  if (
    value === "unread" ||
    value === "my" ||
    value ===
      "unassigned" ||
    value === "comment" ||
    value === "open" ||
    value === "pinned"
  ) {
    return value;
  }

  if (
    value?.startsWith(
      "saved:",
    )
  ) {
    return value;
  }

  return "all";
}

/*
 * Placeholder rows shown while the list changes filter.
 *
 * Shaped like a real row -- avatar circle, name line, shorter preview line --
 * so the list keeps its rhythm and nothing jumps when the real rows arrive.
 */
function ConversationListSkeleton() {
  return (
    <div
      aria-busy="true"
      aria-live="polite"
      className="animate-pulse"
    >
      <span className="sr-only">
        Loading conversations…
      </span>

      {[0, 1, 2, 3, 4, 5].map((row) => (
        <div
          key={row}
          className="flex items-start gap-2.5 border-b border-slate-100/70 dark:border-slate-800/50 py-2.5 pl-3 pr-3"
        >
          <div className="mt-0.5 h-10 w-10 shrink-0 rounded-full bg-slate-200/80" />

          <div className="min-w-0 flex-1 pt-1">
            <div className="h-3 w-2/5 rounded bg-slate-200/80" />
            <div className="mt-2 h-2.5 w-3/4 rounded bg-slate-200/60" />
          </div>
        </div>
      ))}
    </div>
  );
}

/*
 * One conversation row, memoized.
 *
 * Measured before this existed: opening a conversation blocked the main
 * thread for 439ms, changing a status for 439ms, and narrowing the search
 * from 473 rows to 3 for 459ms. Typing cost nothing. The difference is that
 * the first three all rebuild the conversations array, and rebuilding it
 * re-rendered all 473 rows -- every avatar, badge, tag chip and preview --
 * to show a change that touched one of them.
 *
 * memo makes that a per-row decision. A status change now re-renders the row
 * whose object actually changed; selecting a conversation re-renders two, the
 * one leaving and the one arriving.
 *
 * isActive is a prop rather than something derived here from
 * activeConversationId, and that is the whole trick: if the row compared the
 * selected id itself, every row would see a changed prop on every selection
 * and memo would buy nothing.
 *
 * The two callbacks must keep their identity across renders for any of this
 * to hold -- see the stable wrappers in ConversationListView.
 */
type ConversationRowProps = {
  conversation: InboxConversation;
  searchMatch?: InboxSearchMatch;
  searchQuery: string;
  searchPending: boolean;
  isActive: boolean;
  isKhmer: boolean;
  channelDirectory: ChannelDirectory;
  channelDirectoryLoaded: boolean;
  /*
   * False until the client has mounted, so the row renders no timestamp on
   * the server pass and cannot produce a hydration mismatch. It flips once
   * and then never changes, so it costs the memo nothing.
   */
  hydrated: boolean;
  onSelectConversation: (
    conversationId: string,
    match?: InboxSearchMatch,
  ) => void;
  onPrefetchConversation?: (
    conversationId: string,
    match?: InboxSearchMatch,
  ) => void;
};

const ConversationRow = memo(function ConversationRow({
  conversation,
  searchMatch,
  searchQuery,
  searchPending,
  isActive,
  isKhmer,
  channelDirectory,
  channelDirectoryLoaded,
  hydrated,
  onSelectConversation,
  onPrefetchConversation,
}: ConversationRowProps) {
                const customerName =
                  conversation.contact
                    ?.full_name ??
                  "Customer";

                const customerAvatarUrl =
                  conversation.contact
                    ?.profile_picture_url
                    ?.trim() ||
                  null;


                const isUnread =
                  (conversation.unread_count ?? 0) > 0;

                const conversationPlatform =
                  getConversationPlatform(
                    conversation,
                    channelDirectory,
                    channelDirectoryLoaded,
                  );

                return (
                  <button
                    key={
                      conversation.id
                    }
                    type="button"
                    disabled={searchPending}
                    onClick={() => {
                      onSelectConversation(
                        conversation.id,
                        searchMatch,
                      );
                    }}
                    onMouseEnter={() =>
                      onPrefetchConversation?.(
                        conversation.id,
                      )
                    }
                    onFocus={() =>
                      onPrefetchConversation?.(
                        conversation.id,
                      )
                    }
                    /*
                     * Full-bleed rows separated by a hairline, so the
                     * selected and hovered states fill the whole width
                     * instead of floating as inset cards.
                     */
                    /*
                     * Selected, hovered and unread each get their own signal
                     * so two of them can never look like the same thing:
                     * selected is a blue outline plus a blue wash, hover is a
                     * plain grey wash, and unread is carried by weight and
                     * contrast in the text rather than another background.
                     */
                    /*
                     * content-visibility keeps the list cheap however long it
                     * gets.
                     *
                     * There is no virtualisation here: every conversation in
                     * the workspace is a real row, and the busiest workspace
                     * in this database has 474 of them. Each row carries an
                     * avatar, channel icon, unread badge, tag chips, status
                     * and a message preview, so the browser was laying out
                     * and painting all of it -- including the ~460 rows
                     * nobody can see -- on first paint and again on every
                     * re-render that got through.
                     *
                     * content-visibility:auto lets the browser skip style,
                     * layout and paint for a row while it is off screen, and
                     * do the work when it scrolls near. contain-intrinsic-size
                     * gives it a height to reserve in the meantime so the
                     * scrollbar is the right length; the auto keyword means
                     * "remember what this row actually measured last time",
                     * which is what stops the scroll position jumping once a
                     * row has been seen.
                     *
                     * Filtering and search are unaffected -- they run over the
                     * full array before any of this, and a row the browser has
                     * skipped is still in the DOM and still found by Ctrl+F.
                     */
                    aria-current={isActive ? "true" : undefined}
                    className={`relative flex w-full items-start gap-2.5 border-b border-b-slate-100/70 dark:border-b-slate-800/50 py-2.5 pl-3 pr-3 text-left transition [contain-intrinsic-size:auto_72px] [content-visibility:auto] ${
                      isActive
                        ? "bg-blue-50"
                        : "hover:bg-slate-100/70"
                    }`}
                  >
                    <div className="relative mt-0.5 h-10 w-10 shrink-0">
                      <CustomerAvatar src={customerAvatarUrl} name={customerName}
                        contactId={conversation.contact?.id} platform={conversationPlatform}
                        className="h-10 w-10 text-sm" />

                      {conversationPlatform ? (
                        <ChannelAvatarBadge
                          sourceType={conversation.source_type}
                          platform={
                            conversationPlatform
                          }
                          personal={isPersonalConversation(conversation, channelDirectory)}
                        />
                      ) : null}
                    </div>

                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-1.5">
                        <p
                          className={`min-w-0 flex-1 truncate text-[13.5px] ${
                            isUnread
                              ? "font-bold text-slate-950"
                              : "font-medium text-slate-700"
                          }`}
                          style={{
                            fontFamily: CONVERSATION_TEXT_FONT_STACK,
                          }}
                        >
                          {
                            customerName
                          }
                        </p>

                        {/* Pin sits with the time so a row with no tags
                            still has somewhere stable to show it. */}
                        {isConversationPinned(
                          conversation,
                        ) ? (
                          <span
                            className="inline-flex shrink-0 scale-75 items-center justify-center text-[#E8A317]"
                            title={isKhmer ? "បានខ្ទាស់" : "Pinned"}
                            aria-label={isKhmer ? "បានខ្ទាស់" : "Pinned"}
                          >
                            <PinIcon />
                          </span>
                        ) : null}

                        <span
                          className={`shrink-0 text-[11px] ${
                            isUnread
                              ? "font-semibold text-blue-600"
                              : "text-slate-400"
                          }`}
                        >
                          {hydrated
                            ? formatMessageTime(
                                conversation.last_message_at,
                              )
                            : ""}
                        </span>
                      </div>

                      <div className="mt-0.5 flex items-center gap-2">
                        <p
                          className={`min-w-0 flex-1 truncate text-[12.5px] ${
                            isUnread
                              ? "font-medium text-slate-700"
                              : "text-slate-400"
                          }`}
                          style={{
                            fontFamily: CONVERSATION_TEXT_FONT_STACK,
                          }}
                        >
                          {normalizeLegacyConversationPreview(
                            searchRowSubtitle(searchQuery, searchMatch, conversation.contact?.phone, conversation.last_message_text),
                          )}
                        </p>

                        {conversation.unread_count >
                        0 ? (
                          <span className="flex h-[18px] min-w-[18px] shrink-0 items-center justify-center rounded-full bg-blue-600 px-1.5 text-[11px] font-semibold text-white">
                            {
                              conversation.unread_count
                            }
                          </span>
                        ) : null}
                      </div>

                      {(conversation.contact?.tags?.length ?? 0) > 0 ? (
                      <div className="mt-1.5 flex flex-wrap items-center gap-1">
                        {(conversation.contact
                          ?.tags ??
                          [])
                          .slice(
                            0,
                            4,
                          )
                          .map(
                            (
                              tag,
                            ) => (
                              <ConversationTag key={tag.id} name={tag.name} color={tag.color} />
                            ),
                          )}

                        {(conversation.contact
                          ?.tags?.length ??
                          0) >
                        4 ? (
                          <span className="rounded-full bg-slate-100 px-1.5 py-[1px] text-[10.5px] font-semibold text-slate-500">
                            +
                            {(conversation
                              .contact
                              ?.tags
                              ?.length ??
                              0) -
                              4}
                          </span>
                        ) : null}
                      </div>
                      ) : null}
                    </div>
                  </button>
                );
});

/*
 * Memoized, because typing must not redraw the list.
 *
 * The reply draft lives in InboxView -- the whole 9,000-line component -- so
 * every character typed into the composer sets state up there and re-renders
 * its children. This list is 4,600 lines of rows, filters, saved views and
 * channel groups, and none of it changes while somebody types a message.
 *
 * Its seven props survive a keystroke unchanged: the arrays and counts come
 * from server props or realtime state, and the three callbacks are
 * useCallback values whose dependencies do not include the draft. So memo
 * turns the per-character re-render into a reference check.
 *
 * Anything added here later must keep that true -- an inline arrow passed
 * from InboxView would be a new reference on every render and would quietly
 * turn this back off.
 */
function ConversationListView({
  pagination,
  onPageRows,
  onMarkAllRead,
  markingAllRead = false,
  conversations,
  activeConversationId,
  activeStatus,
  statusCounts,
  onSelectConversation,
  onPrefetchConversation,
  onClearConversationSelection,
}: ConversationListProps) {
  const router =
    useRouter();

  const searchParams =
    useSearchParams();

  const isKhmer = useWorkspaceLanguageId() === "km";
  const listContainerRef = useRef<HTMLDivElement | null>(null);
  const [bulkReadNotice, setBulkReadNotice] = useState<string | null>(null);

  /*
   * Handlers that never change identity, so memo on the row actually holds.
   *
   * onSelectConversation and onPrefetchConversation arrive from InboxView as
   * useCallback values, but their dependency lists include liveMessages -- so
   * they get a new identity every time a message arrives, which would hand
   * every row a changed prop and defeat the memo exactly when the inbox is
   * busiest.
   *
   * The ref always holds the current handler, and the wrapper around it is
   * created once. These are event handlers: they want the latest version at
   * the moment they are called, never the one captured at render.
   */
  const selectConversationRef = useRef(
    onSelectConversation,
  );
  const prefetchConversationRef = useRef(
    onPrefetchConversation,
  );

  /*
   * Assigned after the render rather than during it. A ref written while
   * rendering is impure and the React Compiler rejects it, and nothing needs
   * the new handler earlier than this: the only caller is a click, which
   * cannot happen before the effect has run, and useRef already seeded both
   * refs with the first render's handlers.
   */
  useEffect(() => {
    selectConversationRef.current =
      onSelectConversation;
    prefetchConversationRef.current =
      onPrefetchConversation;
  });

  const stableSelectConversation = useCallback(
    (conversationId: string, match?: InboxSearchMatch) => {
      selectConversationRef.current(
        conversationId,
        match,
      );
    },
    [],
  );

  const stablePrefetchConversation = useCallback(
    (conversationId: string) => {
      prefetchConversationRef.current?.(
        conversationId,
      );
    },
    [],
  );

  /*
   * Generic V3.11.4 channel key.
   * `page` remains a read-only compatibility alias
   * for older Facebook Page Inbox links.
   */
  const selectedChannelId =
    searchParams.get("channel") ??
    searchParams.get("page");

  const selectedWorkspaceId =
    searchParams.get("workspace");

  const [search, setSearch] =
    useState("");

  /*
   * V3.11.24.4 — restore the existing left-rail Follow-up / Reminder
   * workspace without touching the newer Smart Views/search implementation.
   */
  const [remindersOpen, setRemindersOpen] =
    useState(false);
  const [reminderCount, setReminderCount] =
    useState(0);
  const [reminderRefreshKey, setReminderRefreshKey] =
    useState(0);
  // Keep the reminder workflow active, but do not show its old left-rail icon.
  const showReminderRailShortcut = false;


  /*
   * V3.11.19 — fast Inbox search.
   * Keep typing responsive while filtering large conversation lists.
   * Search intentionally includes ONLY customer name, phone, and
   * Telegram username/identity. Email, message preview, and Messenger
   * platform identity are excluded by product decision.
   */
  const [settledSearch, setSettledSearch] = useState(search);
  useEffect(() => {
    const timer = setTimeout(() => setSettledSearch(search), 150);
    return () => clearTimeout(timer);
  }, [search]);
  const deferredSearch = useDeferredValue(settledSearch);

  // Hydration-safe localized timestamps.
  // The server and browser can resolve locale/timezone differently,
