          (await response.json()) as
            ChannelsApiResponse;

        if (
          !response.ok ||
          !result.success ||
          cancelled
        ) {
          return;
        }

        const next:
          ChannelDirectory = {};

        for (
          const channel of
          result.channels ?? []
