  /*
   * The status filter, applied before the server answers.
   *
   * activeStatus is a prop: choosing a status is a Link, so the list could
   * not change until /dashboard/inbox?status=... came back. Measured in the
   * running app, that round trip took 1,781ms during which nothing moved --
   * no jank, just a wait, which is the kind of slow that reads as broken.
   *
   * scopedConversations already does this filtering on the client; it simply
   * did not know the new status yet. Every conversation carries its status,
   * so the answer was in the browser the whole time.
   *
   * The navigation still happens, because the URL should stay shareable and
   * the server still owns statusCounts. This only stops the list waiting for
   * it. The effect below re-syncs from the prop, so a back button, a shared
   * link or a server correction all win over the optimistic value.
   */
  const [localStatus, setOptimisticStatus] =
    useState<StatusFilter>(activeStatus);

  /*
   * Paging mode: the destination of a status link that is still navigating.
   * Title, highlight, banner and the page request all read one scope -- this
   * destination until the URL has it, then the URL -- so the list never shows
   * a new title above the previous filter's rows. Cleared when the URL
   * reaches it, or on Back/Forward, where the URL is authoritative.
   */
  const [pendingDestination, setPendingDestination] =
    useState<StatusDestination | null>(null);

  const [
    lastServerStatus,
    setLastServerStatus,
  ] = useState<StatusFilter>(activeStatus);

  // Paint the loading feedback once, then show the already-filtered rows.
  // A fixed timer adds latency even when all conversation data is in memory.
  const [statusSwitching, setStatusSwitching] = useState(false);
  const [channelSwitching, setChannelSwitching] = useState(false);
  const statusFrameRef = useRef<number | null>(null);

  const beginStatusSwitch = useCallback(() => {
    // Paging mode shows the pager's real request state instead of a timer.
    if (pagination) return;
    if (statusFrameRef.current !== null) {
      window.cancelAnimationFrame(statusFrameRef.current);
    }
    setStatusSwitching(true);
    statusFrameRef.current = window.requestAnimationFrame(() => {
      statusFrameRef.current = window.requestAnimationFrame(() => {
        statusFrameRef.current = null;
        setStatusSwitching(false);
      });
    });
  }, [pagination]);

  useEffect(() => () => {
    if (statusFrameRef.current !== null) {
      window.cancelAnimationFrame(statusFrameRef.current);
    }
  }, []);

  /*
   * Adjusted during render rather than in an effect.
   *
   * An effect would render once with the old value and correct it on the
   * next pass, so a back button would flash the previous filter's rows. This
   * is React's documented way to reset state when a prop changes: the extra
   * state remembers what the server last said, and when that moves, the
   * optimistic value is discarded in the same render. React re-runs the
   * component immediately without committing anything in between.
   */
  if (activeStatus !== lastServerStatus) {
    setLastServerStatus(activeStatus);
    setOptimisticStatus(activeStatus);
  }

  const [
    localSelectedViewKey,
    setSelectedViewKey,
  ] =
    useState(
      () =>
        viewKeyFromUrl(
          searchParams.get(
            "view",
          ),
        ),
    );

  // Paging reads use one atomic URL scope. An optimistic view combined with
  // the previous channel/workspace would start an unnecessary wrong-scope read.
  const urlDestination = destinationFromParams(searchParams);
  if (pendingDestination && sameDestination(pendingDestination, urlDestination)) {
    setPendingDestination(null);
  }
  const pagingScope = pendingDestination ?? urlDestination;
  const selectedViewKey = pagination ? viewKeyFromUrl(pagingScope.view) : localSelectedViewKey;
  const pageStatus: StatusFilter = pagination ? pagingScope.status : localStatus;
  const optimisticStatus = pageStatus;
  const requestChannelId = pagination ? pagingScope.channel : selectedChannelId;
  const requestWorkspaceId = pagination ? pagingScope.workspace : selectedWorkspaceId;

  useEffect(() => {
    if (!pagination) return;
    const onHistory = () => setPendingDestination(null);
    window.addEventListener("popstate", onHistory);
    return () => window.removeEventListener("popstate", onHistory);
  }, [pagination]);

  useEffect(() => {
    setSelectedViewKey(
      viewKeyFromUrl(
        searchParams.get(
          "view",
        ),
      ),
    );
    if (pagination) {
      const status = searchParams.get("status");
      setOptimisticStatus(status && ["open", "pending", "resolved", "closed", "spam"].includes(status)
        ? status as StatusFilter : "all");
    }
  }, [searchParams, pagination]);

  useEffect(() => {
    let cancelled = false;

    async function loadSmartViewOptions() {
      try {
        const response = await fetch(
          "/api/inbox/smart-view-options",
          { cache: "no-store" },
        );

        const result =
          (await response.json()) as SmartViewOptionsResponse;

        if (
          cancelled ||
          !response.ok ||
          !result.success
        ) {
          return;
        }

        setCurrentBusinessId(
          result.currentBusinessId ?? null,
        );
        setSmartViewWorkspaces(
          result.workspaces ?? [],
        );
        setSmartViewTags(
          result.tags ?? [],
        );
      } catch {
        /*
         * Smart View filtering still works from the conversations already in
         * the Inbox. This lookup only supplies the complete cross-workspace
         * workspace/tag directory for the editor.
         */
      }
    }

    void loadSmartViewOptions();

    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    let cancelled =
      false;

    async function loadViews() {
      setViewsLoading(
        true,
      );
      setViewsError(null);

      try {
        const response =
          await fetch(
            "/api/inbox/views",
            {
              cache:
                "no-store",
            },
          );

        const result =
          (await response.json()) as
            ViewsResponse;

        if (
          !response.ok ||
          !result.success
        ) {
          throw new Error(
            result.error ??
              "Unable to load Smart Views.",
          );
        }

        if (cancelled) {
          return;
        }

        setMemberId(
          result.memberId ??
            null,
        );

        setCurrentBusinessId((current) =>
          current ?? result.businessId ?? null,
        );

        setSavedViews(
          (result.views ?? []).map(
            normalizeSavedView,
          ),
        );
      } catch (
        error
      ) {
        if (cancelled) {
          return;
        }

        setViewsError(
          error instanceof
            Error
            ? error.message
            : "Unable to load Smart Views.",
        );
      } finally {
        if (!cancelled) {
          setViewsLoading(
            false,
          );
        }
      }
    }

    void loadViews();

    return () => {
      cancelled =
        true;
    };
  }, []);

  const availableSmartViewOrderIds =
    useMemo(
      () => [
        ...DEFAULT_SMART_VIEW_ORDER_IDS,
        ...savedViews.map(
          (view) => `saved:${view.id}`,
        ),
      ],
      [savedViews],
    );

  const smartViewOrderIdentity =
    useMemo(() => {
      const memberIds = smartViewWorkspaces
        .map((workspace) => workspace.memberId)
        .filter(Boolean)
        .sort();

      return memberIds.length > 0
        ? memberIds.join("|")
        : memberId;
    }, [
      memberId,
      smartViewWorkspaces,
    ]);

  const smartViewOrderStorageKey =
    useMemo(
      () =>
        smartViewOrderIdentity
          ? `tenh:smart-view-order:v2:${smartViewOrderIdentity}`
          : null,
      [smartViewOrderIdentity],
    );

  useEffect(() => {
    if (!smartViewOrderStorageKey) {
      const next = normalizeSmartViewOrder(
        null,
        availableSmartViewOrderIds,
      );
      smartViewOrderRef.current = next;
      setSmartViewOrder(next);
      return;
    }

    let stored: unknown = null;

    try {
      const raw = window.localStorage.getItem(
        smartViewOrderStorageKey,
      );

      if (raw) {
        stored = JSON.parse(raw);
      } else if (memberId) {
        // Migrate the existing per-workspace order from the previous build.
        const legacyKeys = [
          `tenh:smart-view-order:${memberId}:${selectedWorkspaceId ?? "current"}`,
          `tenh:smart-view-order:${memberId}:current`,
        ];

        for (const legacyKey of legacyKeys) {
          const legacyRaw = window.localStorage.getItem(legacyKey);
          if (!legacyRaw) {
            continue;
          }

          stored = JSON.parse(legacyRaw);
          break;
        }
      }
    } catch {
      stored = null;
    }

    const next = normalizeSmartViewOrder(
      stored,
      availableSmartViewOrderIds,
    );

    smartViewOrderRef.current = next;
    setSmartViewOrder(next);

    try {
      window.localStorage.setItem(
        smartViewOrderStorageKey,
        JSON.stringify(next),
      );
    } catch {
      // Ordering is a convenience only; Smart Views still work without storage.
    }
  }, [
    availableSmartViewOrderIds,
    memberId,
    selectedWorkspaceId,
    smartViewOrderStorageKey,
  ]);

  function persistSmartViewOrder(
    next: string[],
  ) {
    smartViewOrderRef.current = next;
    setSmartViewOrder(next);

    if (!smartViewOrderStorageKey) {
      return;
    }

    try {
      window.localStorage.setItem(
        smartViewOrderStorageKey,
        JSON.stringify(next),
      );
    } catch {
      // Keep the in-memory order if browser storage is unavailable.
    }
  }

  function moveSmartView(
    draggedId: string,
    targetId: string,
  ) {
    if (draggedId === targetId) {
      return;
    }

    const current =
      normalizeSmartViewOrder(
        smartViewOrderRef.current,
        availableSmartViewOrderIds,
      );
    const fromIndex = current.indexOf(draggedId);
    const targetIndex = current.indexOf(targetId);

    if (fromIndex < 0 || targetIndex < 0) {
      return;
    }

    const next = [...current];
    next.splice(fromIndex, 1);
    next.splice(targetIndex, 0, draggedId);
    persistSmartViewOrder(next);
  }

  function beginSmartViewPointerDrag(
    orderId: string,
  ) {
    draggingSmartViewIdRef.current = orderId;
    setDraggingSmartViewId(orderId);
  }

  function endSmartViewPointerDrag() {
    draggingSmartViewIdRef.current = null;
    setDraggingSmartViewId(null);
  }

  function moveSmartViewFromPointer(
    clientX: number,
    clientY: number,
  ) {
    const draggedId = draggingSmartViewIdRef.current;
    if (!draggedId) {
      return;
    }

    const pointedElement = document.elementFromPoint(
      clientX,
      clientY,
    ) as HTMLElement | null;
    const targetRow = pointedElement?.closest<HTMLElement>(
      "[data-smart-view-order-id]",
    );
    const targetId = targetRow?.dataset.smartViewOrderId;

    if (targetId && targetId !== draggedId) {
      moveSmartView(draggedId, targetId);
    }
  }

  function moveSmartViewByKeyboard(
    orderId: string,
    direction: -1 | 1,
  ) {
    const current = normalizeSmartViewOrder(
      smartViewOrderRef.current,
      availableSmartViewOrderIds,
    );
    const index = current.indexOf(orderId);
    const targetIndex = index + direction;

    if (
      index < 0 ||
      targetIndex < 0 ||
      targetIndex >= current.length
    ) {
      return;
    }

    moveSmartView(orderId, current[targetIndex]);
  }

  /*
   * V3.11.25 — InboxView may keep one selected conversation locally so the
   * center panel survives left-panel navigation. Scope list rows/counts back
   * to the active server filters before applying Smart Views/search.
   */
  const scopedConversations =
    useMemo(
      () =>
        conversations.filter((conversation) => {
          if (
            optimisticStatus !== "all" &&
            conversation.status !== optimisticStatus
          ) {
            return false;
          }

          if (selectedChannelId) {
            return (
              conversation.social_account?.id ===
              selectedChannelId
            );
          }

          return true;
        }),
      [
        conversations,
        optimisticStatus,
        selectedChannelId,
      ],
    );

  const workspaceContextId =
    requestWorkspaceId ?? currentBusinessId;

  const pageRequest = useMemo(() => ({ status: pageStatus, view: selectedViewKey,
    search: deferredSearch.trim(), channelId: requestChannelId, workspaceId: requestWorkspaceId,
    workspaceContextId: workspaceContextId ?? null, cursor: null }),
    [pageStatus, selectedViewKey, deferredSearch, requestChannelId, requestWorkspaceId, workspaceContextId]);
  const pager = useConversationPages(pagination, pageRequest, conversations, onPageRows);
  const { enabled: pagingEnabled, loading: pagingLoading, error: pagingError, more: loadNextPage } = pager;
  const [snapshotLoading, setSnapshotLoading] = useState(false);

  const fallbackWorkspaceOptions =
    useMemo(() => {
      const businessIds = Array.from(
        new Set(
          conversations
            .map((conversation) => conversation.business_id)
            .filter(Boolean),
        ),
      );

      return businessIds.map((businessId) => ({
        businessId,
        businessName: `Workspace ${businessId.slice(0, 8)}`,
        memberId:
          businessId === currentBusinessId
            ? memberId ?? ""
            : "",
      }));
    }, [
      conversations,
      currentBusinessId,
      memberId,
    ]);

  const availableSmartViewWorkspaces =
    smartViewWorkspaces.length > 0
      ? smartViewWorkspaces
      : fallbackWorkspaceOptions;

  const memberIdByBusiness =
    useMemo(() => {
      const map: Record<string, string> = {};

      for (const workspace of smartViewWorkspaces) {
        if (workspace.memberId) {
          map[workspace.businessId] = workspace.memberId;
        }
      }

      if (
        currentBusinessId &&
        memberId &&
        !map[currentBusinessId]
      ) {
        map[currentBusinessId] = memberId;
      }

      return map;
    }, [
      currentBusinessId,
      memberId,
      smartViewWorkspaces,
    ]);

  const fallbackSmartViewTags =
    useMemo(() => {
      const map = new Map<string, SmartViewTagOption>();

      for (const conversation of conversations) {
        for (const tag of conversation.contact?.tags ?? []) {
          const businessId =
            tag.business_id || conversation.business_id;
          const key = makeSmartViewTagReference(
            businessId,
            tag.id,
          );
          const existing = map.get(key);

          if (existing) {
            existing.count += 1;
          } else {
            map.set(key, {
              id: tag.id,
              businessId,
              name: tag.name,
              color: tag.color,
              count: 1,
            });
          }
        }
      }

      return Array.from(map.values()).sort((first, second) =>
        first.name.localeCompare(second.name),
      );
    }, [conversations]);

  const availableSmartViewTags =
    smartViewTags.length > 0
      ? smartViewTags
      : fallbackSmartViewTags;

  const editorWorkspaceIds =
    useMemo(() => {
      if (!editor) {
        return [] as string[];
      }

      if (editor.filters.workspaceScope === "all") {
        return availableSmartViewWorkspaces.map(
          (workspace) => workspace.businessId,
        );
      }

      if (editor.filters.workspaceScope === "current") {
        return workspaceContextId
          ? [workspaceContextId]
          : [];
      }

      return editor.filters.workspaceIds;
    }, [
      editor,
      availableSmartViewWorkspaces,
      workspaceContextId,
    ]);

  const editorTagGroups =
    useMemo(() => {
      if (!editor) {
        return [] as Array<{
          businessId: string;
          businessName: string;
          tags: SmartViewTagOption[];
        }>;
      }

      const allowed = new Set(editorWorkspaceIds);
      const restrictByWorkspace =
        editor.filters.workspaceScope !== "all" ||
        allowed.size > 0;
      const workspaceNameById = new Map(
        availableSmartViewWorkspaces.map((workspace) => [
          workspace.businessId,
          workspace.businessName,
        ]),
      );
      const groups = new Map<
        string,
        {
          businessId: string;
          businessName: string;
          tags: SmartViewTagOption[];
        }
      >();

      for (const tag of availableSmartViewTags) {
        if (
          restrictByWorkspace &&
          !allowed.has(tag.businessId)
        ) {
          continue;
        }

        let group = groups.get(tag.businessId);
        if (!group) {
          group = {
            businessId: tag.businessId,
            businessName:
              workspaceNameById.get(tag.businessId) ??
              `Workspace ${tag.businessId.slice(0, 8)}`,
            tags: [],
          };
          groups.set(tag.businessId, group);
        }

        group.tags.push(tag);
      }

      return Array.from(groups.values())
        .map((group) => ({
          ...group,
          tags: [...group.tags].sort((first, second) =>
            first.name.localeCompare(second.name),
          ),
        }))
        .sort((first, second) =>
          first.businessName.localeCompare(second.businessName),
        );
    }, [
      editor,
      editorWorkspaceIds,
      availableSmartViewTags,
      availableSmartViewWorkspaces,
    ]);

  const legacyTotalUnreadCount =
    useMemo(
      () =>
        scopedConversations.reduce(
          (
            total,
            conversation,
          ) =>
            total +
            Math.max(
              0,
              conversation.unread_count ??
                0,
            ),
          0,
        ),
      [scopedConversations],
    );

  const legacyUnreadConversationCount =
    useMemo(
      () =>
        scopedConversations.filter(
          (conversation) =>
            conversation.unread_count >
            0,
        ).length,
      [scopedConversations],
    );

  const totalUnreadCount = pager.enabled ? pager.page?.counts.totalUnreadCount ?? 0 : legacyTotalUnreadCount;
  const unreadConversationCount = pager.enabled ? pager.page?.counts.unreadConversationCount ?? 0 : legacyUnreadConversationCount;
  const baseViewConversations =
    useMemo(
      () =>
        scopedConversations.filter(
          (conversation) =>
            matchesView({
              conversation,
              key:
                selectedViewKey,
              savedViews,
              memberId,
              memberIdByBusiness,
              workspaceContextId,
              channelDirectory,
            }),
        ),
      [
        scopedConversations,
        memberId,
        memberIdByBusiness,
        workspaceContextId,
        savedViews,
        selectedViewKey,
        channelDirectory,
      ],
    );

  const conversationSearchIndex =
    useMemo(() => {
      const index = new Map<
        string,
        string
      >();

      for (
        const conversation of
          baseViewConversations
      ) {
        const name =
          conversation.contact
            ?.full_name
            ?.trim()
            .toLowerCase() ??
          "";

        const phone =
          conversation.contact
            ?.phone
            ?.trim()
            .toLowerCase() ??
          "";

        const platform =
          getConversationPlatform(
            conversation,
            channelDirectory,
            channelDirectoryLoaded,
          );

        const telegramIdentity =
          getTelegramSearchIdentity(
            conversation,
            platform,
          );

        /*
         * The preview line is searchable too.
         *
         * The box says it searches "conversations, contacts or messages", and
         * the index held only the contact's name, phone and Telegram handle.
         * So typing a phrase an agent could read in the row in front of them
         * -- the last message preview is on every row -- returned nothing,
         * which reads as the search being broken rather than as the search
         * being narrower than its own placeholder.
         *
         * This covers the last message of each conversation, which is what
         * the list already knows. Searching further back through a thread is
         * a different thing: the client does not hold those messages, so it
         * needs the server. See the note on the search box.
         */
        const lastMessage =
          conversation.last_message_text
            ?.trim()
            .toLowerCase() ?? "";

        index.set(
          conversation.id,
          `${name} ${phone} ${telegramIdentity} ${lastMessage}`.trim(),
        );
      }

      return index;
    }, [
      baseViewConversations,
      channelDirectory,
      channelDirectoryLoaded,
    ]);

  /*
   * How many rows are actually built.
   *
   * Measured in the running app: returning to All conversations cost a 388ms
   * blocking task, because React had to create all 473 rows at once.
   * content-visibility stops the browser painting the ones off screen, but
   * React still builds every element and every DOM node before the browser
   * gets the chance to skip them.
   *
   * Thirty is several screens deep, and the window grows before the reader
   * reaches the end of it, so scrolling stays continuous. It never shrinks:
   * somebody who has scrolled a long way and then searches and clears the
   * search finds their place still there, and re-slicing on every filter
   * change would cost more than it saves.
   *
   * Filtering and search are untouched -- both run over the whole array, and
   * only the last step, building the rows, is windowed.
   */
  const ROWS_PER_WINDOW = CONVERSATION_PAGE_SIZE;

  const [visibleRowCount, setVisibleRowCount] =
    useState(ROWS_PER_WINDOW);

  const loadMoreRowsRef =
    useRef<HTMLDivElement | null>(null);

  /*
   * Conversations whose history contains the search text, answered by the
   * server.
   *
   * The index above only knows what the list holds: each conversation's name,
   * phone, handle and last message. A phrase from the middle of a thread is
   * not in the browser at all, so it has to be asked for. The result is a set
   * of conversation ids, unioned with the local matches below -- the rows are
   * still drawn from conversations the client already has, so nothing new is
   * trusted from this response beyond which ones to show.
   *
   * deferredSearch rather than the raw box, so this follows React's own
   * debouncing rather than adding a second timer, and the request is aborted
   * when the query moves on: a fast typist would otherwise have several
   * searches in flight and the slowest could land last.
   */
  const [historyMatches, setHistoryMatches] = useState<{ query: string; matches: Record<string, InboxSearchMatch> }>({ query: "", matches: {} });
  const [messageMatchIds, setMessageMatchIds] =
    useState<Set<string>>(
      () => new Set(),
    );

  useEffect(() => {
    const keyword = deferredSearch
      .trim()
      .replace(/^@/, "");

    if (pagination) return;
    const controller = new AbortController();

    async function searchMessageHistory() {
      /*
       * Inside the async function rather than in the effect body: a setState
       * run synchronously while an effect is executing cascades an extra
       * render, and the React Compiler rejects it. A microtask later is the
       * same result without the cascade.
       *
       * Below three characters there is nothing to ask the server, and the
       * identity check keeps an already-empty set from causing a render at
       * all -- which is every keystroke of a short query.
       */
      if (keyword.length < 3) {
        setMessageMatchIds((current) =>
          current.size === 0
            ? current
            : new Set(),
        );

        return;
      }

      try {
        const response = await fetch(
          `/api/inbox/search-messages?q=${encodeURIComponent(
            keyword,
          )}`,
          {
            cache: "no-store",
            signal: controller.signal,
          },
        );

        if (!response.ok) {
          return;
        }

        const result = (await response.json()) as {
          success?: boolean;
          conversationIds?: string[];
          matches?: Record<string, InboxSearchMatch>;
        };

        if (!result.success) {
          return;
        }

        if (controller.signal.aborted) return;
        setHistoryMatches({ query: keyword, matches: result.matches ?? {} });
        setMessageMatchIds(
          new Set(result.conversationIds ?? []),
        );
      } catch {
        /*
         * An aborted request is the normal case here, and a failed one must
         * not empty the results the agent can already see: name and preview
         * matches stand on their own.
         */
      }
    }

    void searchMessageHistory();

    return () => {
      controller.abort();
    };
  }, [deferredSearch, pagination]);

  const legacyFilteredConversations =
    useMemo(() => {
      const keyword =
        deferredSearch
          .trim()
          .toLowerCase()
          .replace(/^@/, "");

      if (!keyword) {
        return baseViewConversations;
      }

      return baseViewConversations.filter(
        (conversation) =>
          (conversationSearchIndex
            .get(
              conversation.id,
            )
            ?.includes(
              keyword,
            ) ??
            false) ||
          (historyMatches.query.toLowerCase() === keyword && messageMatchIds.has(conversation.id)),
      );
    }, [
      baseViewConversations,
      conversationSearchIndex,
      deferredSearch,
      messageMatchIds,
      historyMatches.query,
    ]);

  // Server paging owns complete search/view qualification. Apply the known
  // unread predicate immediately, rather than waiting for its debounced refresh.
  const filteredConversations = pager.enabled
    ? pager.rows.filter(row => !["unread", "pinned", "comment"].includes(selectedViewKey) || matchesView({
      conversation: row, key: selectedViewKey, savedViews, memberId, memberIdByBusiness,
      workspaceContextId, channelDirectory,
    }))
    : legacyFilteredConversations;
  const visibleConversations =
    useMemo(
      () =>
        pager.enabled || filteredConversations.length <=
        visibleRowCount
          ? filteredConversations
          : filteredConversations.slice(
              0,
              visibleRowCount,
            ),
      [filteredConversations, visibleRowCount, pager.enabled],
    );
  useConversationListAnchor(listContainerRef, JSON.stringify(pageRequest),
    JSON.stringify(visibleConversations.map(row => [row.id, row.last_message_at, row.last_message_text, row.unread_count])));

  useEffect(() => {
    const marker = loadMoreRowsRef.current;

    if (!marker || typeof IntersectionObserver === "undefined") {
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (!entries[0]?.isIntersecting) {
          return;
        }

        if (pagingEnabled) { if (!pagingLoading && !pagingError) loadNextPage(); return; }
        setVisibleRowCount(
          (current) =>
            current + ROWS_PER_WINDOW,
        );
      },
      // Grow before the marker is actually reached, so the next rows are
      // already there by the time the reader scrolls to where they go.
      { rootMargin: "600px" },
    );

    observer.observe(marker);

    return () => {
      observer.disconnect();
    };
  }, [
    visibleRowCount,
    filteredConversations.length,
    pagingEnabled, pagingLoading, pagingError, loadNextPage,
    ROWS_PER_WINDOW,
  ]);

  const legacyBuiltInCounts =
    useMemo(
      () => ({
        all:
          scopedConversations.length,

        unread:
          scopedConversations.filter(
            (conversation) =>
              matchesView({
                conversation,
                key:
                  "unread",
                savedViews,
                memberId,
                memberIdByBusiness,
                workspaceContextId,
                channelDirectory,
              }),
          ).length,

        my:
          scopedConversations.filter(
            (conversation) =>
              matchesView({
                conversation,
                key:
                  "my",
                savedViews,
                memberId,
                memberIdByBusiness,
                workspaceContextId,
                channelDirectory,
              }),
          ).length,

        unassigned:
          scopedConversations.filter(
            (conversation) =>
              matchesView({
                conversation,
                key:
                  "unassigned",
                savedViews,
                memberId,
                memberIdByBusiness,
                workspaceContextId,
                channelDirectory,
              }),
          ).length,

        comment:
          scopedConversations.filter(
            (conversation) =>
              matchesView({
                conversation,
                key:
                  "comment",
                savedViews,
                memberId,
                memberIdByBusiness,
                workspaceContextId,
                channelDirectory,
              }),
          ).length,

        open:
          scopedConversations.filter(
            (conversation) =>
              matchesView({
                conversation,
                key: "open",
                savedViews,
                memberId,
                memberIdByBusiness,
                workspaceContextId,
                channelDirectory,
              }),
          ).length,

        pinned:
          scopedConversations.filter(
            (conversation) =>
              matchesView({
                conversation,
                key:
                  "pinned",
                savedViews,
                memberId,
                memberIdByBusiness,
                workspaceContextId,
                channelDirectory,
              }),
          ).length,
      }),
      [
        scopedConversations,
        memberId,
        memberIdByBusiness,
        workspaceContextId,
        savedViews,
        channelDirectory,
      ],
    );

  const builtInCounts = pager.enabled ? pager.page?.counts.views ?? legacyBuiltInCounts : legacyBuiltInCounts;
  const effectiveStatusCounts = pager.enabled ? pager.page?.counts.statusCounts ?? statusCounts : statusCounts;
  const defaultSmartViews =
    useMemo(
      () => [
        {
          orderId: "default:my",
          key: "my" as BuiltInViewKey,
          name: isKhmer ? "ចាត់តាំងឱ្យខ្ញុំ" : "Assign to me",
          count: builtInCounts.my,
        },
        {
          orderId: "default:unassigned",
          key: "unassigned" as BuiltInViewKey,
          name: isKhmer ? "មិនទាន់ចាត់តាំង" : "Unassigned",
          count: builtInCounts.unassigned,
        },
        {
          orderId: "default:open",
          key: "open" as BuiltInViewKey,
          name: isKhmer ? "ការសន្ទនាបើក" : "Open conversation",
          count: builtInCounts.open,
        },
      ],
      [
        builtInCounts.my,
        builtInCounts.open,
        builtInCounts.unassigned,
        isKhmer,
      ],
    );

  const orderedSmartViewItems =
    useMemo(() => {
      const byId = new Map<
        string,
        | {
            kind: "default";
            orderId: string;
            key: BuiltInViewKey;
            name: string;
            count: number;
          }
        | {
            kind: "saved";
            orderId: string;
            view: SavedView;
          }
      >();

      for (const item of defaultSmartViews) {
        byId.set(item.orderId, {
          kind: "default",
          ...item,
        });
      }

      for (const view of savedViews) {
        const orderId = `saved:${view.id}`;
        byId.set(orderId, {
          kind: "saved",
          orderId,
          view,
        });
      }

      const order = normalizeSmartViewOrder(
        smartViewOrder,
        Array.from(byId.keys()),
      );

      return order
        .map((id) => byId.get(id))
        .filter(
          (item): item is NonNullable<typeof item> =>
            Boolean(item),
        );
    }, [
      defaultSmartViews,
      savedViews,
      smartViewOrder,
    ]);

  const activeViewLabel =
    useMemo(() => {
      if (
        selectedViewKey ===
        "all"
      ) {
        return null;
      }

      const builtInLabels:
        Record<
          Exclude<
            BuiltInViewKey,
            "all"
          >,
          string
        > = {
          unread:
            isKhmer ? "មិនទាន់អាន" : "Unread",
          my:
            isKhmer ? "ចាត់តាំងឱ្យខ្ញុំ" : "Assign to me",
          unassigned:
            isKhmer ? "មិនទាន់ចាត់តាំង" : "Unassigned",
          comment:
            isKhmer ? "មតិយោបល់ Facebook" : "Facebook Comment",
          open:
            isKhmer ? "ការសន្ទនាបើក" : "Open conversation",
          pinned:
            isKhmer ? "Pin" : "Pinned",
        };

      if (
        selectedViewKey in
        builtInLabels
      ) {
        return (
          builtInLabels[
            selectedViewKey as
              Exclude<
                BuiltInViewKey,
                "all"
              >
          ]
        );
      }

      return (
        getSavedViewFromKey(
          selectedViewKey,
          savedViews,
        )?.name ??
        "Smart View"
      );
    }, [
      savedViews,
      selectedViewKey,
      isKhmer,
    ]);

  function selectView(
    key: string,
    viewOverride?: SavedView,
  ) {
    setRemindersOpen(false);
    setSearch("");
    setViewsOpen(
      false,
    );
    setEditor(null);
    setViewActionMenuId(
      null,
    );
    setSelectedViewKey(
      key,
    );

    const query =
      new URLSearchParams(
        searchParams.toString(),
      );

    query.delete("conversation");
    query.delete("status");
    query.delete("view");

    const savedView =
      viewOverride ??
      getSavedViewFromKey(
        key,
        savedViews,
      );

    const isDefaultSmartView =
      ["my", "unassigned", "comment", "open"].includes(key);

    /*
     * Smart Views own their workspace/channel scope. Default Smart Views are
     * intentionally global across every accessible subscription. Personal
     * Smart Views may target all, the current workspace, or selected
     * workspaces. Clear URL-level channel/workspace filters when needed so a
     * previous Inbox selection cannot silently hide valid Smart View matches.
     */
    if (savedView) {
      const filters = normalizeSavedViewFilters(
        savedView.filters,
      );

      query.delete("channel");
      query.delete("page");

      if (filters.workspaceScope === "current") {
        if (workspaceContextId) {
          query.set("workspace", workspaceContextId);
        } else {
          query.delete("workspace");
        }
      } else if (
        filters.workspaceScope === "selected" &&
        filters.workspaceIds.length === 1
      ) {
        query.set("workspace", filters.workspaceIds[0]);
      } else {
        query.delete("workspace");
      }
    } else if (isDefaultSmartView) {
      query.delete("workspace");
      query.delete("channel");
      query.delete("page");
    }

    if (
      key !== "all"
    ) {
      query.set(
        "view",
        key,
      );
    }

    const queryString =
      query.toString();

    const href = queryString ? `/dashboard/inbox?${queryString}` : "/dashboard/inbox";
    if (pager.enabled) {
      // The page API owns paging-mode view qualification; avoid a second RSC
      // request for the same view and preserve the selected chat/draft tree.
      setOptimisticStatus("all");
      window.history.pushState(null, "", href);
    } else {
      router.push(href);
    }
  }

  function openCreateView() {
    setViewActionMenuId(
      null,
    );

    setEditor({
      id: null,
      name: "",
      filters: {
        ...EMPTY_FILTERS,
        tagIds: [],
      },
    });
  }

  function openEditView(
    view: SavedView,
  ) {
    if (savingView || deletingViewId) {
      return;
    }

    const currentView =
      savedViews.find(
        (item) => item.id === view.id,
      );

    if (!currentView) {
      setViewActionMenuId(null);
      setViewsError(
        "This Smart View is no longer available. Refresh and try again.",
      );
      return;
    }

    const normalizedFilters =
      normalizeSavedViewFilters(
        currentView.filters,
      );

    setViewActionMenuId(null);
    setViewsError(null);

    setEditor({
      id:
        currentView.id,
      name:
        currentView.name,
      filters: {
        ...normalizedFilters,
        workspaceIds: [
          ...normalizedFilters.workspaceIds,
        ],
        tagIds: [
          ...normalizedFilters.tagIds,
        ],
      },
    });
  }

  async function saveView() {
    if (!editor || savingView) {
      return;
    }

    const editingViewId = editor.id;

    if (
      editingViewId &&
      !savedViews.some(
        (view) => view.id === editingViewId,
      )
    ) {
      setViewsError(
        "This Smart View is no longer available. Refresh and try again.",
      );
      setEditor(null);
      return;
    }

    const name =
      editor.name
        .trim()
        .replace(
          /\s+/g,
          " ",
        );

    if (!name) {
      setViewsError(
        "Enter a Smart View name.",
      );
      return;
    }

    if (
      editor.filters.workspaceScope === "selected" &&
      editor.filters.workspaceIds.length === 0
    ) {
      setViewsError(
        "Select at least one workspace for this Smart View.",
      );
      return;
    }

    setSavingView(
      true,
    );
    setViewsError(null);

    try {
      const isEditing =
        Boolean(
          editor.id,
        );

      const endpoint =
        isEditing
          ? `/api/inbox/views/${encodeURIComponent(
              editor.id as string,
            )}`
          : "/api/inbox/views";

      const response =
        await fetch(
          endpoint,
          {
            method:
              isEditing
                ? "PATCH"
                : "POST",
            headers: {
              "Content-Type":
                "application/json",
            },
            body:
              JSON.stringify(
                {
                  name,
                  filters:
                    editor.filters,
                },
              ),
          },
        );

      const result =
        (await response.json()) as {
          success?: boolean;
          error?: string;
          view?:
            SavedView;
        };

      if (
        !response.ok ||
        !result.success ||
        !result.view
      ) {
        throw new Error(
          result.error ??
            "Unable to save Smart View.",
        );
      }

      if (
        isEditing &&
        editingViewId &&
        result.view.id !== editingViewId
      ) {
        throw new Error(
          "Smart View update returned an unexpected result. Nothing was switched.",
        );
      }

      setSavedViews(
        (current) => {
          const normalizedResultView =
            normalizeSavedView(
              result.view as SavedView,
            );

          if (isEditing) {
            return current.map(
              (view) =>
                view.id === normalizedResultView.id
                  ? normalizedResultView
                  : view,
            );
          }

          return [
            ...current,
            normalizedResultView,
          ];
        },
      );

      if (pager.enabled) window.dispatchEvent(new CustomEvent(INBOX_PAGE_CHANGED_EVENT, { detail: { viewConfigurationChanged: true } }));
      const nextKey =
        `saved:${result.view.id}`;

      setEditor(null);

      if (!isEditing) {
        selectView(
          nextKey,
          normalizeSavedView(result.view),
        );
      }
    } catch (
      error
    ) {
      setViewsError(
        error instanceof
          Error
          ? error.message
          : "Unable to save Smart View.",
      );
    } finally {
      setSavingView(
        false,
      );
    }
  }

  async function deleteView(
    view: SavedView,
  ) {
    setDeletingViewId(
      view.id,
    );
    setViewsError(null);

    try {
      const response =
        await fetch(
          `/api/inbox/views/${encodeURIComponent(
            view.id,
          )}`,
          {
            method:
              "DELETE",
          },
        );

      const result =
        (await response.json()) as {
          success?: boolean;
          error?: string;
        };

      if (
        !response.ok ||
        !result.success
      ) {
        throw new Error(
          result.error ??
            "Unable to delete Smart View.",
        );
      }

      setSavedViews(
        (current) =>
          current.filter(
            (item) =>
              item.id !==
              view.id,
          ),
      );

      persistSmartViewOrder(
        smartViewOrder.filter(
          (itemId) =>
            itemId !== `saved:${view.id}`,
        ),
      );

      setViewActionMenuId(
        null,
      );

      if (
        selectedViewKey ===
        `saved:${view.id}`
      ) {
        selectView(
          "all",
        );
      }

      if (pager.enabled) window.dispatchEvent(new CustomEvent(INBOX_PAGE_CHANGED_EVENT, { detail: { viewConfigurationChanged: true } }));
      setDeleteViewTarget(
        null,
      );
    } catch (
      error
    ) {
      setViewsError(
        error instanceof
          Error
          ? error.message
          : "Unable to delete Smart View.",
      );
    } finally {
      setDeletingViewId(
        null,
      );
    }
  }

  const railViews: Array<{
    value:
      BuiltInViewKey;
    label: string;
    count: number;
    icon:
      React.ReactNode;
  }> = [
    {
      value: "all",
      label:
        isKhmer ? "ការសន្ទនាទាំងអស់" : "All conversations",
      count:
        builtInCounts.all,
      icon:
        <AllConversationIcon />,
    },
    {
      value:
        "unread",
      label:
        isKhmer ? "មិនទាន់អាន" : "Unread",
      count:
        builtInCounts.unread,
      icon:
        <UnreadIcon />,
    },
    {
      value:
        "comment",
      label:
        isKhmer ? "មតិយោបល់ Facebook" : "Facebook Comment",
      count:
        builtInCounts.comment,
      icon:
        <CommentIcon />,
    },
    {
      value:
        "pinned",
      label:
        isKhmer ? "Pin" : "Pinned",
      count:
        builtInCounts.pinned,
      icon:
        <ConversationBookmark />,
    },
  ];

  const isSmartViewSelected =
    selectedViewKey.startsWith("saved:") ||
    ["my", "unassigned", "open"].includes(
      selectedViewKey,
    );

  return (
    <section data-inbox-surface className="relative flex h-full min-h-0 w-full min-w-0 rounded-r-2xl overflow-hidden border-r border-slate-200/70 dark:border-slate-800/60 bg-white">
      <ConversationRail>
        {/*
         * Channel picker and status filter sit above the Smart Views. The
         * channel panel floats to the right of the rail the same way Smart
         * Views do; the filter panel opens beside the list.
         */}
        <div className="px-2 pb-1.5">
          <InboxChannelSelector variant="rail" onSwitchingChange={setChannelSwitching} pagingEnabled={pager.enabled} pageLoading={pager.initialLoading} />
        </div>

        <div className="mx-3 mb-2 mt-0.5 border-t border-slate-100 dark:border-slate-800/60" />

        {railViews.map(
          (view) => {
            const isActive =
              selectedViewKey ===
              view.value &&
              optimisticStatus ===
                "all";

            return (
              <button
                key={
                  view.value
                }
                type="button"
                onClick={() =>
                  selectView(
                    view.value,
                  )
                }
                className={`group relative mx-2 mb-1 flex h-12 shrink-0 items-center justify-center rounded-xl transition focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-500 ${
                  isActive
                    ? "bg-blue-50 text-blue-600 after:pointer-events-none after:absolute after:-left-2 after:top-1/2 after:h-6 after:w-[3px] after:-translate-y-1/2 after:rounded-full after:bg-blue-600"
                    : "text-slate-600 hover:bg-white hover:text-slate-900"
                }`}
                aria-pressed={isActive}
                aria-label={
                  view.label
                }
              >
                <span data-inbox-view-label>{view.value === "all" ? (isKhmer ? "ទាំងអស់" : "All") : view.value === "comment" ? (isKhmer ? "មតិយោបល់" : "Comments") : view.label}</span>
                <span className="flex h-5 w-5 items-center justify-center">
                  {
                    view.icon
                  }
                </span>

                {/*
                 * Counts conversations, not messages: this badge sits on a
                 * filter that opens a list of chats, so the number should
                 * match the rows behind it. One customer sending 30 rapid
                 * messages is still one person to reply to. The per-chat
                 * badge further down still shows the message count, and the
                 * tooltip below spells out both numbers.
                 */}
                {view.value ===
                  "unread" &&
                unreadConversationCount >
                  0 ? (
                  <span className="absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full border-2 border-slate-50 bg-blue-600 px-1 text-[10px] font-bold leading-none text-white">
                    {unreadConversationCount >
                    99
                      ? "99+"
                      : unreadConversationCount}
                  </span>
                ) : null}

                {view.value ===
                  "pinned" &&
                view.count >
                  0 ? (
                  <span className="absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full border-2 border-slate-50 bg-blue-600 px-1 text-[10px] font-bold leading-none text-white">
                    {view.count >
                    99
                      ? "99+"
                      : view.count}
                  </span>
                ) : null}

                <span className="pointer-events-none absolute left-[58px] top-1/2 z-[100] hidden -translate-y-1/2 whitespace-nowrap rounded-lg bg-slate-950 px-3 py-2 text-xs font-medium text-white shadow-xl group-hover:block">
                  {
                    view.label
                  }
                  {view.value ===
                    "unread" &&
                  totalUnreadCount >
