}

export const ConversationList = memo(ConversationListView);

"use client";

import {
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import type {
  CustomerTag,
} from "@/types/inbox";
import { getReadableTagTextColor } from "@/lib/display/tag-contrast";
import { createQuickPickerCache } from "@/lib/inbox/quick-picker-cache";
import { QuickPickerLoading } from "./quick-picker-loading";

const tagCatalogCache = createQuickPickerCache<{ tags: CustomerTag[]; loadedAt: number }>();

type CustomerTagSelectorProps = {
  contactId: string;
  businessId: string;
  conversationId?: string;
  initialTags:
    CustomerTag[];
  onTagsChange?: (
    tags:
      CustomerTag[],
  ) => void;
};

type TagsResponse = {
  success?: boolean;
  error?: string;
  tags?: CustomerTag[];
};

type TagMutationResponse = {
  success?: boolean;
  error?: string;
  tag?: CustomerTag;
  tags?: CustomerTag[];
};

async function readJsonResponse<T>(
  response: Response,
): Promise<T | null> {
  const text =
    await response.text();

  if (!text.trim()) {
    return null;
  }

  try {
    return JSON.parse(
      text,
    ) as T;
  } catch {
    return null;
  }
}

