// Must match lib/inbox/get-messages: the client pages older messages in
// the same size the server first sends.
const MESSAGE_PAGE_SIZE = 25;
const MESSAGE_CACHE_MAX_CONVERSATIONS = 25;
const PROFILE_CACHE_MAX_CONVERSATIONS = 50;

type OptimisticSendStatus =
  | "sending"
  | "sent"
  | "failed";

type OptimisticInboxMessage =
  InboxMessage & {
    __optimistic_status?:
      OptimisticSendStatus;
    __optimistic_created_at?:
      number;
    __optimistic_requires_review?: boolean;
    __render_key?: string;
  };

type PendingOptimisticSend = {
  requiresDeliveryReview?: boolean;
  tempId: string;
  conversationId: string;
  message: string;
  endpoint: string;
  requestBody:
    Record<string, unknown>;
  isCommentConversation:
    boolean;
  commentId:
    | string
    | null;
};

type PendingOptimisticAttachmentSend = {
  replyToMessageId?: string;
  albumFiles?: File[];
  albumPreviewUrls?: string[];
  albumGroupId?: string;
  albumPosition?: number;
  tempId: string;
  conversationId: string;
  recipientId: string;
  file: File;
  kind: ReplyAttachmentKind;
  previewUrl: string;
  messageText: string;
  endpoint: string;
};


type InboxConversationPlatform =
  | "facebook"
  | "telegram";

type PlatformAwareConversation =
  InboxConversation & {
    platform?: string | null;
    social_account:
      | (InboxConversation["social_account"] & {
          platform?: string | null;
        })
      | null;
  };

type BusinessAwareConversation =
  InboxConversation & {
    business_id?: string | null;
  };

function getConversationBusinessId(
  conversation: InboxConversation,
): string | null {
  const businessAware =
    conversation as BusinessAwareConversation;

  return (
    businessAware.business_id ??
    conversation.contact?.business_id ??
    null
  );
}

function isAbortError(
  error: unknown,
): boolean {
  return (
    error instanceof Error &&
    error.name === "AbortError"
  );
}

function getLoadedConversationPlatform(
  conversation: InboxConversation,
): InboxConversationPlatform | null {
  const platformAware =
    conversation as
      PlatformAwareConversation;

  const platform =
    platformAware.platform ??
    platformAware.social_account
      ?.platform ??
    null;

  // Telegram Personal uses the Telegram chat screen (edit, delete, typing);
  // its sends are routed separately in handleSendMessage/handleSendAttachments.
  if (platform === "telegram" || platform === "telegram_personal") {
    return "telegram";
  }

  if (platform === "facebook") {
    return "facebook";
  }

  return null;
}


/*
 * V2.9 — multi-agent action toast.
 *
 * conversation_activity already contains the actor, action type,
 * description and metadata. We convert those rows into compact,
 * human-readable team updates without adding another realtime channel.
 */
type MultiAgentToast = {
  id: string;
  activityType: string;
  message: string;
  actorName: string | null;
};

function isRecord(
  value: unknown,
): value is Record<string, unknown> {
  return (
    Boolean(value) &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

function capitalizeFirst(
  value: string,
) {
  if (!value) {
    return value;
  }

  return (
    value.charAt(0).toUpperCase() +
    value.slice(1)
  );
}

function buildMultiAgentToast(
  row: Record<string, unknown>,
): MultiAgentToast | null {
  const activityType =
    typeof row.activity_type === "string"
      ? row.activity_type
      : "";

  const actorName =
    typeof row.actor_name === "string" &&
    row.actor_name.trim()
      ? row.actor_name.trim()
      : "A teammate";

  const description =
    typeof row.description === "string"
      ? row.description.trim()
      : "";

  const title =
    typeof row.title === "string"
      ? row.title.trim()
      : "";

  const metadata = isRecord(row.metadata)
    ? row.metadata
    : {};

  let message = description;

  if (
    activityType === "status_changed" &&
    typeof metadata.newStatus === "string"
  ) {
    message = `${actorName} changed status to ${capitalizeFirst(
      metadata.newStatus,
    )}`;
  } else if (activityType === "assigned") {
    const newAssignee = isRecord(metadata.newAssignee)
      ? metadata.newAssignee
      : isRecord(metadata.assignedTo)
        ? metadata.assignedTo
        : null;
    const assigneeName =
      newAssignee &&
      typeof newAssignee.name === "string" &&
      newAssignee.name.trim()
        ? newAssignee.name.trim()
        : null;

    if (assigneeName) {
      message = `${actorName} assigned this conversation to ${assigneeName}`;
    }
  } else if (activityType === "unassigned") {
    message = `${actorName} unassigned this conversation`;
  } else if (activityType === "pinned") {
    message = `${actorName} pinned this conversation`;
  } else if (activityType === "unpinned") {
    message = `${actorName} unpinned this conversation`;
  } else if (
    activityType === "tag_added" ||
    activityType === "tag_removed"
  ) {
    const tag = isRecord(metadata.tag)
      ? metadata.tag
      : null;

    const tagName =
      tag &&
      typeof tag.name === "string" &&
      tag.name.trim()
        ? tag.name.trim()
        : null;

    if (tagName) {
      message =
        activityType === "tag_added"
          ? `${actorName} added ${tagName} tag`
          : `${actorName} removed ${tagName} tag`;
    }
  } else if (
    activityType === "customer_updated" ||
    activityType === "customer_profile_updated"
  ) {
    message =
      `${actorName} updated customer information`;
  } else if (
    activityType === "note_added" ||
    activityType === "internal_note_added"
  ) {
    message =
      `${actorName} added a customer note`;
  } else if (
    activityType === "note_updated" ||
    activityType === "internal_note_updated"
  ) {
    message =
      `${actorName} updated a customer note`;
  } else if (
    activityType === "note_deleted" ||
    activityType === "internal_note_deleted"
  ) {
    message =
      `${actorName} deleted a customer note`;
  }

  if (!message && title) {
    const normalizedTitle =
      title.toLowerCase().startsWith(
        actorName.toLowerCase(),
      )
        ? title
        : `${actorName} ${title}`;

    message = normalizedTitle;
  }

  if (!message) {
    return null;
  }

  return {
    id:
      typeof row.id === "string" &&
      row.id
        ? row.id
        : `${activityType}-${Date.now()}`,
    activityType,
    message,
    actorName,
  };
}

function sortLiveConversations(conversations: InboxConversation[]) {
  // The state setter orders latest activity within the pinned groups.
  return conversations;
}

/*
 * When a message belongs in the thread, as opposed to when TENH wrote the row.
 *
 * The server orders by platform_created_at, but the client re-sorted every
 * merged list by created_at and quietly overrode it. Those agree for a message
 * that arrived by webhook and disagree for every message the recovery pass
 * pulls in, which writes them whenever it happens to fetch them. A message
 * sent at 11:12 PM yesterday and recovered this morning sorted to the very end
 * of the thread -- which is why the "Yesterday" divider appeared underneath
 * today's messages instead of above them.
 *
 * Falling back to created_at keeps this safe for anything without a platform
 * timestamp.
 */
function messageOrderMs(message: {
  created_at: string;
  platform_created_at?: string | null;
}) {
  const sentAt = message.platform_created_at;

  if (typeof sentAt === "string" && sentAt) {
    const parsed = new Date(sentAt).getTime();

    if (Number.isFinite(parsed)) {
      return parsed;
    }
  }

  return new Date(message.created_at).getTime();
}

function getRealtimeMessagePreview(
  row: Record<string, unknown>,
) {
  /*
   * Facebook comment deletion is a state change on the existing message row,
   * not a new chat message. Prefer the deletion state over the old comment
   * text so the left conversation preview immediately reflects what happened.
   */
  if (row.comment_is_deleted === true) {
    const deletedBy =
      row.comment_deleted_by === "page"
        ? "page"
        : row.comment_deleted_by === "customer"
          ? "customer"
          : null;

    const direction =
      row.direction === "incoming" ||
      row.direction === "outgoing"
        ? row.direction
        : null;

    return deletedBy === "page" ||
      (deletedBy === null && direction === "outgoing")
      ? "Message deleted by Page"
      : "Message deleted by Commenter";
  }

  const rawPayload = isRecord(row.raw_payload)
    ? row.raw_payload
    : null;

  /*
   * A deleted Telegram message keeps its type and its old payload, so without
   * this the preview falls through and reports "You sent an image" for a photo
   * that is gone. Two code paths then disagreed about the same row and the
   * left list flickered between the two as each update landed. The deletion is
   * the newest fact about the row, so it wins over every branch below.
   */
  if (rawPayload?.tenh_deleted) {
    return `🗑 ${getDeletedMessageText({ raw_payload: rawPayload, message_text: typeof row.message_text === "string" ? row.message_text : null })}`;
  }

  const rawMessageType =
    typeof row.message_type === "string"
      ? row.message_type
      : "unknown";

  const knownMessageType =
    rawMessageType === "text" ||
    rawMessageType === "image" ||
    rawMessageType === "video" ||
    rawMessageType === "audio" ||
    rawMessageType === "voice" ||
    rawMessageType === "file" ||
    rawMessageType === "document" ||
    rawMessageType === "sticker" ||
    rawMessageType === "unknown"
      ? rawMessageType
      : "unknown";

  /*
   * Location and GIF are recognised from the payload rather than the type --
   * Telegram files both under a generic type -- so they are translated into a
   * type the shared preview understands instead of being answered here.
   *
   * This used to return "Sent a location", "Sent a GIF" and "Sent a sticker"
   * directly, which reads as something the agent did. Every other path builds
   * the preview through getConversationMessagePreview, which knows the
   * difference: an incoming sticker is "Sent you a sticker". The two disagreed
   * about the same row, so the left list flickered between them as each update
   * landed -- the same fault the deleted-message branch above was written to
   * fix, in three more places.
   */
  const messageType = rawPayload?.tenh_location
    ? "location"
    : rawPayload?.tenh_animation
      ? "animation"
      : knownMessageType;

  const direction =
    row.direction === "incoming" ||
    row.direction === "outgoing"
      ? row.direction
      : null;

  return getConversationMessagePreview({
    direction,
    messageType,
    messageText: row.message_text,
  });
}

