   * do not require router.refresh().
   */
  const [
    liveConversations,
    setRawLiveConversations,
  ] = useState(conversations);

  // Every update path goes through one ordering policy, including server prop
  // refreshes and optimistic sends. Previews/unread counts still update live.
  const setLiveConversations = useCallback((update: InboxConversation[] | ((current: InboxConversation[]) => InboxConversation[])) => {
    setRawLiveConversations(current => {
      const next = typeof update === "function" ? update(current) : update;
      if (next === current) return current;
      const ordered = stableConversationOrder(current, next);
      return ordered.length === current.length && ordered.every((row, index) => row === current[index])
        ? current : ordered;
    });
  }, []);

  const [
    liveMessages,
    setRawLiveMessages,
  ] = useState(() => normalizeMessages(messages));
  const setLiveMessages = useCallback((update: InboxMessage[] | ((current: InboxMessage[]) => InboxMessage[])) => {
    setRawLiveMessages((current) => normalizeMessages(
      typeof update === "function" ? update(current) : update,
      current,
    ));
  }, []);

  /*
   * Keep current live data available to long-running fallback timers without
   * restarting those timers on every message/conversation state update.
   */
  const liveMessagesRef = useRef(liveMessages);
  const liveConversationsRef = useRef(liveConversations);

  useEffect(() => {
