    useCallback(
      (conversationId: string | null) => {
        for (
          const [id, controller] of
          Object.entries(
            conversationMessageAbortRef
              .current,
          )
        ) {
          if (
            id !== conversationId &&
            controller
          ) {
            controller.abort();
            delete conversationMessageAbortRef
              .current[id];
            delete conversationMessageRequestRef
              .current[id];
          }
