const customerProfileConversationCacheRef =
  useRef<
    Map<string, InboxConversation>
  >(new Map());

useEffect(() => {
  for (
    const conversation of
      liveConversations
  ) {
    if (!conversation.contact) {
      continue;
    }

    customerProfileConversationCacheRef
      .current.delete(
        conversation.id,
      );
    customerProfileConversationCacheRef
      .current.set(
        conversation.id,
        conversation,
      );
  }

  while (
    customerProfileConversationCacheRef
      .current.size >
    PROFILE_CACHE_MAX_CONVERSATIONS
  ) {
    const oldestId =
      customerProfileConversationCacheRef
        .current.keys()
        .next().value;

    if (!oldestId) {
