/*
 * V3.11.15 — TENH agent typing -> Telegram customer.
 * Telegram Bot API does not provide customer typing updates back to bots.
 */
useEffect(() => {
  const conversation =
    activeConversation;

  if (
    !conversation ||
    conversation.source_type ===
      "comment" ||
    !reply.trim()
  ) {
    return;
  }

  let disposed = false;

  const timer =
    window.setTimeout(
      async () => {
        let platform:
          InboxConversationPlatform;

        try {
          platform =
            await resolveConversationPlatform(
              conversation,
            );
        } catch {
          return;
        }

        if (
          disposed ||
          platform !==
            "telegram"
        ) {
          return;
        }

        const now =
          Date.now();

        const lastSent =
          telegramTypingLastSentRef
            .current[
              conversation.id
            ] ?? 0;

        if (
          now - lastSent <
          3500
        ) {
          return;
        }

        telegramTypingLastSentRef
          .current[
            conversation.id
          ] = now;

        try {
          await fetch(
            "/api/telegram/typing",
            {
              method: "POST",
              headers: {
                "Content-Type":
                  "application/json",
              },
              body:
                JSON.stringify({
                  conversationId:
                    conversation.id,
                }),
            },
          );
        } catch {
          // Best effort only.
        }
      },
      450,
    );

  return () => {
    disposed = true;
    window.clearTimeout(
      timer,
    );
  };
}, [
  reply,
  activeConversation?.id,
]);

async function markConversationReadRealtime(
  conversationId: string,
) {
  if (
    document.visibilityState !== "visible" ||
    !document.hasFocus() ||
    manualUnreadConversationIdsRef.current.has(
      conversationId,
    ) ||
    readInFlightRef.current.has(
      conversationId,
    )
  ) {
    return;
  }

  const readConversation =
    liveConversations.find(
      (conversation) =>
        conversation.id ===
        conversationId,
    );

  const unreadBeforeRead = pendingReadCountsRef.current.get(conversationId) ?? readConversation?.unread_count ?? 0;

  const readMessageTime =
    readConversation?.last_message_at
      ? new Date(
          readConversation.last_message_at,
        ).getTime()
      : 0;

  if (
    Number.isFinite(readMessageTime) &&
    readMessageTime > 0
  ) {
    readBarrierMessageTimeRef.current.set(
      conversationId,
      Math.max(
        readBarrierMessageTimeRef.current.get(
          conversationId,
        ) ?? 0,
        readMessageTime,
      ),
    );
  }

  readInFlightRef.current.add(
    conversationId,
  );
  let settleRead: () => void = () => {};
  readPromisesRef.current.set(
    conversationId,
    new Promise<void>((resolve) => {
      settleRead = resolve;
    }),
  );

  /*
   * Keep the active conversation visually at zero unread
   * while the server PATCH is completing.
   */
  setLiveConversations(
    (current) =>
      current.map(
        (conversation) =>
          conversation.id ===
          conversationId
            ? {
                ...conversation,
                unread_count: 0,
              }
            : conversation,
      ),
  );

  try {
    const response =
      await fetch(
        `/api/conversations/${conversationId}/read`,
        {
          method: "PATCH",
        },
      );

    const responseText =
      await response.text();

    const result =
      responseText.trim()
        ? (JSON.parse(
            responseText,
          ) as {
            success?: boolean;
            error?: string;
            conversation?: {
              updated_at?: string | null;
            } | null;
          })
        : {
            success:
              response.ok,
            conversation: null,
          };

    if (
      !response.ok ||
      !result.success
    ) {
      throw new Error(
        result.error ??
          "Unable to mark conversation read.",
      );
    }

    /*
     * Remember the row version this read produced. Conversation rows at or
     * behind it describe state this read already superseded.
     */
    const readRowVersion =
      typeof result.conversation?.updated_at === "string"
        ? new Date(
            result.conversation.updated_at,
          ).getTime()
        : Number.NaN;

    if (Number.isFinite(readRowVersion)) {
      readRowVersionRef.current.set(
        conversationId,
        Math.max(
          readRowVersionRef.current.get(
            conversationId,
          ) ?? 0,
          readRowVersion,
        ),
      );
    }
  } catch (error) {
    readBarrierMessageTimeRef.current.delete(
      conversationId,
    );

    readRowVersionRef.current.delete(
      conversationId,
    );

    // Restore only this failed read's optimistic badge. A newer incoming
    // message or an explicit manual-unread update wins without moving selection.
    setLiveConversations(current => current.map(row =>
      row.id === conversationId && row.unread_count === 0 &&
      rowTime(row.last_message_at) <= readMessageTime
        ? { ...row, unread_count: Math.max(0, unreadBeforeRead) } : row));

    console.error(
      "Unable to mark realtime conversation read:",
      error,
    );

    /*
     * Re-sync if the optimistic zero could not be saved.
     */
    router.refresh();
  } finally {
    readInFlightRef.current.delete(
      conversationId,
    );
    readPromisesRef.current.delete(conversationId);
    settleRead();
    pendingReadIdsRef.current.delete(
      conversationId,
    );
    pendingReadCountsRef.current.delete(conversationId);
  }
}

