function normalizeCustomerTags(
  tags: CustomerTag[],
) {
  const unique = new Map<string, CustomerTag>();

  for (const tag of tags) {
    if (tag?.id) {
      unique.set(tag.id, tag);
    }
  }

  return Array.from(unique.values());
}

