function updateContactTagsLive(
  contactId: string,
  tags: CustomerTag[],
  remember = true,
) {
  const normalizedTags = normalizeCustomerTags(tags);

  if (remember) {
    contactTagsOverrideRef.current.set(
      contactId,
      {
        tags: normalizedTags,
        expiresAt: Date.now() + 6_000,
      },
    );
  }

  setLiveConversations((current) =>
    current.map((conversation) => {
      if (conversation.contact?.id !== contactId) {
        return conversation;
      }

      return {
        ...conversation,
        contact: {
          ...conversation.contact,
          tags: normalizedTags,
        },
      };
    }),
  );
}

function applyRealtimeTagActivity(
  row: Record<string, unknown>,
) {
  const activityType =
    typeof row.activity_type === "string"
      ? row.activity_type
      : "";

  if (
    activityType !== "tag_added" &&
    activityType !== "tag_removed"
  ) {
    return;
  }

  const contactId =
    typeof row.contact_id === "string"
      ? row.contact_id
      : null;

  if (!contactId) {
    return;
  }

  const metadata =
    row.metadata && typeof row.metadata === "object"
      ? (row.metadata as Record<string, unknown>)
      : null;
  const rawTag =
    metadata?.tag && typeof metadata.tag === "object"
      ? (metadata.tag as Record<string, unknown>)
      : null;
  const tagId =
    typeof rawTag?.id === "string"
      ? rawTag.id
      : null;

  if (!tagId) {
    return;
  }

  const override =
    contactTagsOverrideRef.current.get(contactId);
  const currentTags =
    override?.tags ??
    liveConversations.find(
      (conversation) => conversation.contact?.id === contactId,
    )?.contact?.tags ??
    [];

  if (activityType === "tag_removed") {
    updateContactTagsLive(
      contactId,
      currentTags.filter((tag) => tag.id !== tagId),
    );
    return;
  }

  const existingTag = currentTags.find(
    (tag) => tag.id === tagId,
  );
  const now = new Date().toISOString();
  const incomingTag: CustomerTag =
    existingTag ?? {
      id: tagId,
      business_id:
        typeof row.business_id === "string"
          ? row.business_id
          : activeBusinessId,
      name:
        typeof rawTag?.name === "string"
          ? rawTag.name
          : "Tag",
      color:
        typeof rawTag?.color === "string"
          ? rawTag.color
          : "#64748b",
      sort_index: 0,
      description: null,
      is_active: true,
      created_at: now,
      updated_at: now,
    };

  updateContactTagsLive(
    contactId,
    [
      ...currentTags.filter((tag) => tag.id !== tagId),
      incomingTag,
    ],
  );
}

const realtimeHealthyRef = useRef(false);
useInboxRealtime({
  onConnectionState: (healthy) => {
    const recovered = healthy && !realtimeHealthyRef.current;
    realtimeHealthyRef.current = healthy;
    if (recovered) window.dispatchEvent(new Event(INBOX_PAGE_CHANGED_EVENT));
  },
  businessIds:
    realtimeBusinessIds,

  onRealtimeEvent: (
    event,
  ) => {
    const eventBusinessId = (event.eventType === "DELETE" ? event.oldRow : event.newRow).business_id;
    if (typeof eventBusinessId === "string" && !realtimeBusinessIds.includes(eventBusinessId)) return;
    if (pagination) window.dispatchEvent(new CustomEvent(INBOX_PAGE_CHANGED_EVENT, { detail: {
      conversationId: event.table === "conversations" ? event.newRow.id ?? event.oldRow.id : event.newRow.conversation_id ?? event.oldRow.conversation_id,
    } }));
    if (event.table === "conversations" && typeof event.newRow.id === "string") {
      const id = event.newRow.id;
      const latestLoaded = liveMessagesRef.current.filter(message => message.conversation_id === id)
        .reduce((time, message) => Math.max(time, messageOrderMs(message)), 0);
      if (id === desiredConversationIdRef.current && rowTime(event.newRow.last_message_at) > latestLoaded) {
        window.dispatchEvent(new CustomEvent(INBOX_SYNC_EVENT, { detail: { conversationId: id, activeOnly: true } }));
      }
    }
    /*
     * V2.8 — customer/tag/note changes are stored in
     * conversation_activity by the existing APIs.
     *
     * These changes affect nested server-enriched data, so another
     * agent's browser refreshes the server props automatically.
     * V2.7 merges the refreshed newest-message page into local state,
     * therefore already-loaded older pages are preserved.
     */
    if (
      event.table ===
      "conversation_activity"
    ) {
      if (
        event.eventType !==
        "INSERT"
      ) {
        return;
      }

      const activityType =
        typeof event.newRow
          .activity_type ===
          "string"
          ? event.newRow
              .activity_type
          : "";

      const activityConversationId =
        typeof event.newRow
          .conversation_id ===
          "string"
          ? event.newRow
              .conversation_id
          : null;

      /*
       * V2.9 — show an action toast only when the activity belongs
       * to the conversation currently open in this browser.
       */
      if (
        activityConversationId &&
        activityConversationId ===
          resolvedActiveConversationId &&
        // This browser's own action already announced its success.
        actionLedgerRef.current.claimRealtime(event.newRow) === "show"
      ) {
        showMultiAgentToast(
          event.newRow,
        );
      }

      if (
        activityType === "tag_added" ||
        activityType === "tag_removed"
      ) {
        applyRealtimeTagActivity(event.newRow);
      }

      const needsEnrichedRefresh =
        activityType ===
          "tag_added" ||
        activityType ===
          "tag_removed" ||
        activityType ===
          "customer_updated" ||
        activityType ===
          "note_added" ||
        activityType ===
          "note_updated" ||
        activityType ===
          "note_deleted";

      if (
        needsEnrichedRefresh
      ) {
        scheduleMultiAgentRefresh();
      }

      return;
    }

    if (
      event.table ===
      "messages"
    ) {
      const row =
        event.eventType ===
        "DELETE"
          ? event.oldRow
          : event.newRow;

      const messageId =
        typeof row.id ===
        "string"
          ? row.id
          : null;

      const conversationId =
        typeof row.conversation_id ===
        "string"
          ? row.conversation_id
          : null;

      if (
        !messageId ||
        !conversationId
      ) {
        return;
      }

      if (!liveConversationsRef.current.some(conversation => conversation.id === conversationId)) {
        window.dispatchEvent(new Event(INBOX_SYNC_EVENT));
      }

      // Fan out the existing stream to the pin header, including older rows.
      window.dispatchEvent(new CustomEvent(MESSAGE_ROW_CHANGED_EVENT, { detail: { row, eventType: event.eventType } }));

      const messageDirection =
        typeof row.direction ===
        "string"
          ? row.direction
          : null;

      const isIncomingInsert =
        event.eventType ===
          "INSERT" &&
        messageDirection ===
          "incoming";

      /*
       * V2.5.1 — update the conversation list immediately
       * from the incoming message INSERT. The later
       * conversations UPDATE remains the authoritative
       * database value and will reconcile the count.
       */
      if (
        isIncomingInsert &&
        !handledIncomingMessageIdsRef.current.has(
          messageId,
        )
      ) {
        handledIncomingMessageIdsRef.current.add(
          messageId,
        );

        recentIncomingConversationAtRef.current.set(
          conversationId,
          Date.now(),
        );

        if (
          recentIncomingConversationAtRef.current.size >
          500
        ) {
          const cutoff = Date.now() - 30_000;
          for (const [id, receivedAt] of recentIncomingConversationAtRef.current) {
            if (receivedAt < cutoff) {
              recentIncomingConversationAtRef.current.delete(id);
            }
          }
        }

        if (
          handledIncomingMessageIdsRef.current.size >
          1000
        ) {
          handledIncomingMessageIdsRef.current.clear();
          handledIncomingMessageIdsRef.current.add(
            messageId,
          );
        }

        const isActiveIncoming =
          document.visibilityState === "visible" &&
          document.hasFocus() &&
          conversationId ===
          resolvedActiveConversationId;
        const keepActiveUnread =
          isActiveIncoming &&
          manualUnreadConversationIdsRef.current.has(
            conversationId,
          );

        const preview =
          getRealtimeMessagePreview(
            row,
          );

        /*
         * V2.5.2 — show a native browser notification only
         * when Tenh Chat is hidden/unfocused. The hook also
         * guarantees this only runs after the agent explicitly
         * enables notifications.
         */
        const notificationConversation =
          liveConversationsRef.current.find(
            (conversation) =>
              conversation.id ===
              conversationId,
          );

        const lastMessageAt =
          typeof row.platform_created_at ===
          "string"
            ? row.platform_created_at
            : typeof row.created_at ===
                "string"
              ? row.created_at
              : new Date().toISOString();

        const incomingMessageTime =
          new Date(lastMessageAt).getTime();
        const lastSoundedIncomingTime =
          lastSoundedIncomingMessageTimeRef.current.get(
            conversationId,
          ) ?? 0;
        const alreadySoundedThisIncoming =
          Number.isFinite(incomingMessageTime) &&
          incomingMessageTime > 0 &&
          lastSoundedIncomingTime > 0 &&
          Math.abs(
            incomingMessageTime - lastSoundedIncomingTime,
          ) <= 100;

        if (!alreadySoundedThisIncoming) {
          notifyIncomingMessage({
            messageId,
            conversationId,
            customerName:
              getIncomingNotificationCustomerName(
                conversationId,
                notificationConversation,
              ),
            body: preview,
          });

          if (
            Number.isFinite(incomingMessageTime) &&
            incomingMessageTime > 0
          ) {
            lastSoundedIncomingMessageTimeRef.current.set(
              conversationId,
              incomingMessageTime,
            );
          }
        }
        const existingReadBarrier =
          readBarrierMessageTimeRef.current.get(
            conversationId,
          ) ?? 0;

        const incomingCoveredByRead = messageCoveredByRead(lastMessageAt, row.created_at,
          existingReadBarrier, readRowVersionRef.current.get(conversationId) ?? 0);
        if (existingReadBarrier > 0 && !incomingCoveredByRead) {
          readBarrierMessageTimeRef.current.delete(
            conversationId,
          );
        }

        setLiveConversations(
          (current) =>
            sortLiveConversations(
              current.map(
                (conversation) => {
                  if (
                    conversation.id !==
                    conversationId
                  ) {
                    return conversation;
                  }

                  const advancesPreview = rowTime(lastMessageAt) >= rowTime(conversation.last_message_at);
                  const alreadyRead = incomingCoveredByRead;
                  return {
                    ...conversation,
                    ...(advancesPreview ? { last_message_text: preview, last_message_at: lastMessageAt,
                      latest_message_type: liveMessageType(row.message_type) ?? conversation.latest_message_type,
                      latest_message_direction: "incoming" as const } : {}),
                    unread_count:
                      alreadyRead ? conversation.unread_count : isActiveIncoming &&
                      !keepActiveUnread
                        ? 0
                        : Math.max(
                            keepActiveUnread ? 1 : 0,
                            (conversation.unread_count ??
                              0) + 1,
                          ),
                  };
                },
              ),
            ),
        );
      }

      /*
       * V3.11.18 — keep the left list preview/time correct for both platforms.
       * INSERT updates outgoing previews too; UPDATE covers Telegram edits;
       * DELETE shows a deterministic deleted preview. Older realtime events
       * are not allowed to overwrite a newer message preview.
       */
      {
        const eventTimestampValue =
          typeof row.platform_created_at === "string"
            ? row.platform_created_at
            : typeof row.created_at === "string"
              ? row.created_at
              : null;
        const eventTimestamp = eventTimestampValue
          ? new Date(eventTimestampValue).getTime()
          : Date.now();
        let eventPreview =
          event.eventType === "DELETE"
            ? "Message deleted"
            : getRealtimeMessagePreview(row);

        const commentWasDeleted =
          row.comment_is_deleted === true;
        const existingConversationForPreview =
          liveConversationsRef.current.find(
            (conversation) => conversation.id === conversationId,
          ) ?? null;
        const existingPreviewTime =
          existingConversationForPreview?.last_message_at
            ? new Date(
                existingConversationForPreview.last_message_at,
              ).getTime()
            : 0;
        const deletionAffectsLatestPreview =
          commentWasDeleted &&
          Number.isFinite(eventTimestamp) &&
          eventTimestamp > 0 &&
          (
            !Number.isFinite(existingPreviewTime) ||
            existingPreviewTime === 0 ||
            eventTimestamp + 1000 >= existingPreviewTime
          );

        if (deletionAffectsLatestPreview) {
          deletedPreviewOverrideRef.current.set(
            conversationId,
            {
              text: eventPreview,
              lastMessageTime: eventTimestamp,
              expiresAt: Date.now() + 20_000,
            },
          );
        } else {
          const previewOverride =
            deletedPreviewOverrideRef.current.get(conversationId);

          if (previewOverride) {
            if (previewOverride.expiresAt <= Date.now()) {
              deletedPreviewOverrideRef.current.delete(conversationId);
            } else if (
              Number.isFinite(eventTimestamp) &&
              eventTimestamp > previewOverride.lastMessageTime + 1000
            ) {
              deletedPreviewOverrideRef.current.delete(conversationId);
            } else if (
              eventTimestamp <= previewOverride.lastMessageTime + 1000
            ) {
              eventPreview = previewOverride.text;
            }
          }
        }

        setLiveConversations((current) =>
          sortLiveConversations(
            current.map((conversation) => {
              if (conversation.id !== conversationId) {
                return conversation;
              }

              const currentTimestamp =
                conversation.last_message_at
                  ? new Date(conversation.last_message_at).getTime()
                  : 0;

              if (
                Number.isFinite(currentTimestamp) &&
                currentTimestamp > 0 &&
                eventTimestamp < currentTimestamp
              ) {
                return conversation;
              }

              return {
                ...conversation,
                last_message_text: eventPreview,
                latest_message_type: liveMessageType(row.message_type) ?? conversation.latest_message_type,
                latest_message_direction: row.direction === "incoming" || row.direction === "outgoing" ? row.direction as InboxConversation["latest_message_direction"] : conversation.latest_message_direction,
                last_message_at:
                  eventTimestampValue ??
                  conversation.last_message_at ??
                  new Date().toISOString(),
              };
            }),
          ),
        );
      }

      /*
       * V3.11.17 — keep an already-cached inactive thread fresh.
       * Realtime messages should not force us to throw away a warm cache.
       * Merge INSERT/UPDATE/DELETE directly into that cached page, then the
       * next conversation switch can render immediately with current data.
       */
      if (
        conversationId !==
        resolvedActiveConversationId
      ) {
        const cached =
          getCachedConversationPage(
            conversationId,
          );

        if (cached) {
          let nextMessages =
            cached.messages;
          let shouldSort = true;

          if (
            event.eventType ===
            "DELETE"
          ) {
            nextMessages =
              cached.messages.filter(
                (message) =>
                  message.id !==
                  messageId,
              );
          } else {
            const incoming =
              row as unknown as InboxMessage;

            const existingIndex =
              cached.messages.findIndex(
                (message) =>
                  message.id ===
                  messageId,
              );

            if (existingIndex >= 0) {
              nextMessages =
                cached.messages.map(
                  (message) =>
                    message.id ===
                    messageId
                      ? ({
                          ...message,
                          ...incoming,
                          attachment_url:
                            incoming.attachment_url ??
                            message.attachment_url,
                        } as InboxMessage)
                      : message,
                );
            } else {
              const optimisticIndex = cached.messages.findIndex((message) => {
                const optimistic = message as OptimisticInboxMessage;
                return Boolean(optimistic.__optimistic_status) && matchesOptimisticMessage(message, row);
              });

              if (optimisticIndex >= 0) {
                const optimistic = cached.messages[optimisticIndex];
                nextMessages = cached.messages.map(
                  (message, index) => index === optimisticIndex
                    ? retainLocalImagePreview(withOptimisticRenderKey(incoming, optimistic), optimistic)
                    : message,
                );
                delete pendingSendsRef.current[optimistic.id];
                delete pendingAttachmentSendsRef.current[optimistic.id];
                shouldSort = false;
              } else {
                nextMessages = [
                  ...cached.messages,
                  incoming,
                ];
              }
            }

            if (shouldSort) nextMessages =
              [...nextMessages].sort(
                (first, second) => {
                  const timeDifference =
                    messageOrderMs(first) -
              messageOrderMs(second);

                  return timeDifference !== 0
                    ? timeDifference
                    : first.id.localeCompare(
                        second.id,
                      );
                },
              );
          }

          setCachedConversationPage(
            conversationId,
            {
              messages:
                nextMessages,
              hasMore:
                cached.hasMore,
              fetchedAt:
                Date.now(),
            },
          );
        }

        return;
      }

      if (
        event.eventType ===
        "DELETE"
      ) {
        setLiveMessages(
          (current) =>
            current.filter(
              (message) =>
                message.id !==
                messageId,
            ),
        );

        return;
      }

      setLiveMessages(
        (current) => {
          const existingIndex =
            current.findIndex(
              (message) =>
                message.id ===
                messageId,
            );

          if (
            existingIndex === -1
          ) {
            const optimisticIndex = current.findIndex(message => {
              const optimistic = message as OptimisticInboxMessage;
              return Boolean(optimistic.__optimistic_status) && matchesOptimisticMessage(message, row);
            });

            if (
              optimisticIndex >= 0
            ) {
              const optimisticMessage =
                current[
                  optimisticIndex
                ];

              const optimisticId =
                optimisticMessage.id;

              delete pendingSendsRef
                .current[
                  optimisticId
                ];

              delete pendingAttachmentSendsRef
                .current[
                  optimisticId
                ];

              const localAttachmentUrl =
                optimisticMessage.attachment_url
                  ?.startsWith("blob:")
                  ? optimisticMessage.attachment_url
                  : null;

              const replacement = retainLocalImagePreview(withOptimisticRenderKey({
                ...row,
                attachment_url:
                  row.attachment_url ??
                  localAttachmentUrl,
              } as unknown as typeof current[number], optimisticMessage), optimisticMessage);

              return current.map((message, index) =>
                index === optimisticIndex ? replacement : message,
              );
            }

            return [
              ...current,
              row as unknown as typeof current[number],
            ].sort(
              (first, second) =>
                messageOrderMs(first) -
              messageOrderMs(second),
            );
          }

          return current.map(
            (message) => {
              if (
                message.id !==
                messageId
              ) {
                return message;
              }

              const localAttachmentUrl =
                message.attachment_url
                  ?.startsWith("blob:")
                  ? message.attachment_url
                  : null;

              return {
                ...message,
                ...row,
                attachment_url:
                  row.attachment_url ??
                  localAttachmentUrl,
              } as unknown as typeof message;
            },
          );
        },
      );

      return;
    }

    if (
      event.table ===
      "conversations"
    ) {
      const row =
        event.eventType ===
        "DELETE"
          ? event.oldRow
          : event.newRow;

      const conversationId =
        typeof row.id ===
        "string"
          ? row.id
          : null;

      if (!conversationId) {
        return;
      }

      if (
        event.eventType ===
        "DELETE"
      ) {
        setLiveConversations(
          (current) =>
            current.filter(
              (conversation) =>
                conversation.id !==
                conversationId,
            ),
        );

        return;
      }

      const realtimeMergeRow = {
        ...row,
      } as Record<string, unknown>;

      const pinOverride =
        pinOverrideRef.current.get(conversationId);
      const rowPinned =
        typeof row.is_pinned === "boolean"
          ? row.is_pinned
          : null;

      if (rowPinned !== null && pinOverride) {
        if (
          pinOverride.expiresAt > Date.now() &&
          rowPinned !== pinOverride.isPinned
        ) {
          delete realtimeMergeRow.is_pinned;
          delete realtimeMergeRow.pinned_at;
          delete realtimeMergeRow.pinned_by;
        } else {
          pinOverrideRef.current.delete(conversationId);
        }
      }

      const assignmentOverride =
        assignmentOverrideRef.current.get(conversationId);
      const rowHasAssignment =
        Object.prototype.hasOwnProperty.call(row, "assigned_to");
      const rowAssignedTo =
        typeof row.assigned_to === "string"
          ? row.assigned_to
          : null;
      let protectAssignedMember = false;

      if (rowHasAssignment && assignmentOverride) {
        if (
          assignmentOverride.expiresAt > Date.now() &&
          rowAssignedTo !== assignmentOverride.assignedTo
        ) {
          delete realtimeMergeRow.assigned_to;
          delete realtimeMergeRow.assigned_at;
          protectAssignedMember = true;
        } else {
          assignmentOverrideRef.current.delete(conversationId);
        }
      }

      const statusOverride =
        statusOverrideRef.current.get(conversationId);
      const rowStatus =
        typeof row.status === "string"
          ? (row.status as ConversationStatus)
          : null;

      if (rowStatus && statusOverride) {
        if (
          statusOverride.expiresAt > Date.now() &&
          rowStatus !== statusOverride.status
        ) {
          delete realtimeMergeRow.status;
          delete realtimeMergeRow.status_updated_at;
        } else {
          statusOverrideRef.current.delete(conversationId);
        }
      }

      if (
        rowPinned !== null &&
        activeConversation?.id === conversationId &&
        Boolean(activeConversation?.is_pinned) !== rowPinned &&
        !(pinOverride && pinOverride.isPinned === rowPinned)
      ) {
        const actorMemberId =
          typeof row.pinned_by === "string"
            ? row.pinned_by
            : null;
        const actorName =
          (actorMemberId
            ? teamMembers.find((member) => member.id === actorMemberId)
                ?.full_name
            : null) ?? "A teammate";
        const changedAt =
          typeof row.updated_at === "string"
            ? row.updated_at
            : Date.now().toString();

        showMultiAgentToast({
          id: `pin-live-${conversationId}-${changedAt}`,
          activity_type: rowPinned ? "pin_live" : "unpin_live",
          actor_name: actorName,
          description: rowPinned
            ? `${actorName} pinned this conversation`
            : `${actorName} unpinned this conversation`,
        });
      }

      const existingConversation =
        liveConversationsRef.current.find(
          (conversation) =>
            conversation.id === conversationId,
        ) ?? null;

      if (existingConversation && isOlderConversationState(existingConversation, row)) return;

      const rowUnreadCount =
        typeof row.unread_count === "number"
          ? row.unread_count
          : null;
      const existingUnreadCount = Math.max(
        0,
        existingConversation?.unread_count ?? 0,
      );
      const existingLastMessageTime =
        existingConversation?.last_message_at
          ? new Date(existingConversation.last_message_at).getTime()
          : 0;
      const rowLastMessageValue =
        typeof row.last_message_at === "string"
          ? row.last_message_at
          : null;
      const rowLastMessageTime = rowLastMessageValue
        ? new Date(rowLastMessageValue).getTime()
        : 0;

      // A source-only update must not turn an existing unread badge into a
      // teammate's manual "Mark unread" action if updated_at has a DB trigger.
      const referralContextOnlyUpdate =
        Array.isArray(row.facebook_messenger_sources) &&
        JSON.stringify(row.facebook_messenger_sources) !==
          JSON.stringify(existingConversation?.facebook_messenger_sources ?? []) &&
        rowLastMessageTime === existingLastMessageTime &&
        rowUnreadCount === existingUnreadCount;

      const deletedPreviewOverride =
        deletedPreviewOverrideRef.current.get(conversationId) ?? null;
      let activeDeletedPreviewOverride = deletedPreviewOverride;

      if (activeDeletedPreviewOverride) {
        if (activeDeletedPreviewOverride.expiresAt <= Date.now()) {
          deletedPreviewOverrideRef.current.delete(conversationId);
          activeDeletedPreviewOverride = null;
        } else if (
          Number.isFinite(rowLastMessageTime) &&
          rowLastMessageTime >
            activeDeletedPreviewOverride.lastMessageTime + 1000
        ) {
          // A real newer message must replace the deleted preview immediately.
          deletedPreviewOverrideRef.current.delete(conversationId);
          activeDeletedPreviewOverride = null;
        }
      }

      const recentIncomingAt =
        recentIncomingConversationAtRef.current.get(conversationId) ?? 0;
      const hasRecentIncomingSignal =
        recentIncomingAt > 0 &&
        Date.now() - recentIncomingAt < 5_000;
      const rowAdvancesMessage =
        Number.isFinite(rowLastMessageTime) &&
        Number.isFinite(existingLastMessageTime) &&
        rowLastMessageTime > 0 &&
        (existingLastMessageTime === 0 ||
          rowLastMessageTime > existingLastMessageTime);
      const unreadComesFromNewMessage =
        rowUnreadCount !== null &&
        rowUnreadCount > 0 &&
        (
          hasRecentIncomingSignal ||
          (
            rowAdvancesMessage &&
            rowUnreadCount > existingUnreadCount
          )
        );
      /*
       * A row is only evidence of a teammate's Mark unread if it is strictly
       * newer than the read this browser last committed. Without this the
       * check below is a catch-all — every unread row that could not be
       * attributed to a new message was treated as a manual unread, so a
       * stale echo of our own pre-read count resurrected the badge, pinned
       * the conversation into manualUnreadConversationIds (which makes
       * markConversationReadRealtime bail out), and dropped the read barrier
       * that would otherwise have corrected it. That is the "badge comes back
       * until I switch conversations twice" bug.
       */
      const readRowVersion =
        readRowVersionRef.current.get(conversationId) ?? 0;
      const rowUpdatedTime =
        typeof row.updated_at === "string"
          ? new Date(row.updated_at).getTime()
          : Number.NaN;
      const rowSupersedesRead =
        readRowVersion === 0 ||
        !Number.isFinite(rowUpdatedTime) ||
        rowUpdatedTime > readRowVersion;

      const isSharedManualUnreadUpdate =
        !referralContextOnlyUpdate &&
        rowUnreadCount !== null &&
        rowUnreadCount > existingUnreadCount &&
        !unreadComesFromNewMessage &&
        rowSupersedesRead;

      /*
       * Supabase can occasionally deliver the conversations UPDATE while the
       * messages INSERT is delayed/missed in this browser. That used to update
       * the unread badge without playing the Inbox sound for an unselected
       * customer. When the latest message advances and unread rises without a
       * recent message signal, use this authoritative conversation row as a
       * safe sound fallback. Outgoing messages do not increase unread_count,
       * and manual Mark as unread does not advance last_message_at.
       */
      if (
        unreadComesFromNewMessage &&
        !hasRecentIncomingSignal &&
        rowLastMessageValue
      ) {
        const lastSoundedIncomingTime =
          lastSoundedIncomingMessageTimeRef.current.get(
            conversationId,
          ) ?? 0;
        const alreadySoundedThisIncoming =
          rowLastMessageTime > 0 &&
          lastSoundedIncomingTime > 0 &&
          Math.abs(
            rowLastMessageTime - lastSoundedIncomingTime,
          ) <= 100;

        if (!alreadySoundedThisIncoming) {
          notifyIncomingMessage({
            messageId: `conversation-${conversationId}-${rowLastMessageValue}`,
            conversationId,
            customerName:
              getIncomingNotificationCustomerName(
                conversationId,
                existingConversation,
              ),
            body:
              typeof row.last_message_text === "string" &&
              row.last_message_text.trim()
                ? row.last_message_text.trim()
                : "New message",
          });

          if (rowLastMessageTime > 0) {
            lastSoundedIncomingMessageTimeRef.current.set(
              conversationId,
              rowLastMessageTime,
            );
          }
        }
      }

      if (unreadComesFromNewMessage && hasRecentIncomingSignal) {
        recentIncomingConversationAtRef.current.delete(conversationId);
      }

      /*
       * V3.11.32 — unread is shared team state. A teammate's manual Mark as
       * unread changes only unread_count, not the latest message. Keep that
       * unread marker even when this browser already has the thread open.
       */
      if (isSharedManualUnreadUpdate) {
        manualUnreadConversationIdsRef.current.add(conversationId);
        persistedManualUnreadCountsRef.current.set(
          conversationId,
          Math.max(1, rowUnreadCount ?? 1),
        );
        readBarrierMessageTimeRef.current.delete(conversationId);
        /* Our read is genuinely superseded here, so retire its row version. */
        readRowVersionRef.current.delete(conversationId);
      }

      /*
       * A read=0 written by another teammate must also win immediately. The
       * only exception is while this browser is in the middle of its own
       * Mark as unread PATCH, where the later local write is intentional.
       */
      if (
        rowUnreadCount === 0 &&
        !unreadWriteInFlightRef.current.has(conversationId)
      ) {
        manualUnreadConversationIdsRef.current.delete(conversationId);
        persistedManualUnreadCountsRef.current.delete(conversationId);
      }

      setLiveConversations(
        (current) => {
          const exists =
            current.some(
              (conversation) =>
                conversation.id ===
                conversationId,
            );

          /*
           * INSERT is enriched by the fallback router refresh.
           * Do not add the raw row because it has no contact join.
           */
          if (!exists) {
            return current;
          }

          const isActiveConversation =
            document.visibilityState === "visible" &&
            document.hasFocus() &&
            conversationId ===
            resolvedActiveConversationId;

          /*
           * Only a real incoming-message unread should be auto-acknowledged
           * while the thread is open. A teammate's manual Mark as unread must
           * stay visible live to everyone.
           */
          const shouldAcknowledgeRead =
            isActiveConversation &&
            unreadComesFromNewMessage &&
            !manualUnreadConversationIdsRef.current.has(
              conversationId,
            );

          const normalizedRow =
            shouldAcknowledgeRead
              ? {
                  ...realtimeMergeRow,
                  unread_count: 0,
                }
              : realtimeMergeRow;

          const persistedManualUnreadCount =
            persistedManualUnreadCountsRef.current.get(
              conversationId,
            ) ?? 0;

          const keepManuallyUnread =
            manualUnreadConversationIdsRef.current.has(
              conversationId,
            ) ||
            persistedManualUnreadCount > 0;

          const next =
            current.map(
              (conversation) => {
                if (
                  conversation.id !==
                  conversationId
                ) {
                  return conversation;
                }

                const currentLastMessageTime =
                  conversation.last_message_at
                    ? new Date(
                        conversation.last_message_at,
                      ).getTime()
                    : 0;
                const rowLastMessageValue =
                  typeof row.last_message_at ===
                  "string"
                    ? row.last_message_at
                    : null;
                const rowLastMessageTime =
                  rowLastMessageValue
                    ? new Date(
                        rowLastMessageValue,
                      ).getTime()
                    : 0;
                const rowIsOlderThanLocal =
                  Number.isFinite(
                    currentLastMessageTime,
                  ) &&
                  Number.isFinite(
                    rowLastMessageTime,
                  ) &&
                  currentLastMessageTime > 0 &&
                  rowLastMessageTime > 0 &&
                  rowLastMessageTime + 1000 <
                    currentLastMessageTime;

                let merged = {
                  ...conversation,
                  ...normalizedRow,
                  ...(rowIsOlderThanLocal
                    ? {
                        last_message_at:
                          conversation.last_message_at,
                        last_message_text:
                          conversation.last_message_text,
                        unread_count:
                          conversation.unread_count,
                      }
                    : {}),
                } as unknown as typeof conversation;

                if (activeDeletedPreviewOverride) {
                  merged = {
                    ...merged,
                    last_message_text:
                      activeDeletedPreviewOverride.text,
                    last_message_at:
                      conversation.last_message_at ??
                      rowLastMessageValue ??
                      merged.last_message_at,
                  };
                }

                if (rowHasAssignment && !protectAssignedMember) {
                  merged = {
                    ...merged,
                    assigned_member: rowAssignedTo
                      ? teamMembers.find(
                          (member) => member.id === rowAssignedTo,
                        ) ?? null
                      : null,
                  };
                }

                if (keepManuallyUnread) {
                  return {
                    ...merged,
                    unread_count: Math.max(
                      1,
                      persistedManualUnreadCount,
                      typeof merged.unread_count === "number"
                        ? merged.unread_count
                        : conversation.unread_count ?? 0,
                    ),
                  };
                }

                const readBarrier =
                  readBarrierMessageTimeRef.current.get(
                    conversationId,
                  ) ?? 0;
                const mergedMessageTime =
                  merged.last_message_at
                    ? new Date(
                        merged.last_message_at,
                      ).getTime()
                    : 0;

                if (
                  readBarrier > 0 &&
                  Number.isFinite(mergedMessageTime)
                ) {
                  if (
                    mergedMessageTime <= readBarrier &&
                    (readInFlightRef.current.has(conversationId) ||
                      rowTime(row.updated_at) <= (readRowVersionRef.current.get(conversationId) ?? 0))
                  ) {
                    return {
                      ...merged,
                      unread_count: 0,
                    };
                  }

                  readBarrierMessageTimeRef.current.delete(
                    conversationId,
                  );
                }

                return merged;
              },
            );

          return sortLiveConversations(
            next,
          );
        },
      );

      if (
        conversationId ===
          resolvedActiveConversationId &&
        unreadComesFromNewMessage &&
        !manualUnreadConversationIdsRef.current.has(
          conversationId,
        )
      ) {
        void markConversationReadRealtime(
          conversationId,
        );
      }
    }
  },

  /*
   * Only brand-new conversations need joined server data.
   * Normal messages/updates stay completely local.
   */
  onFallbackRefresh: () => {
    window.dispatchEvent(new Event(INBOX_SYNC_EVENT));
  },
  onScopeChanged: () => { scheduleMultiAgentRefresh(); },
});

/*
 * Realtime is the fast path. This lightweight server-authoritative sync is the
 * safety net for deployments where a Supabase Realtime publication/policy is
 * delayed or unavailable. It keeps pin, assignment and customer tags aligned
 * for Owners and teammates without refreshing the page or replacing messages.
 */
const collaborationChannelId = searchParams.get("channel") ?? searchParams.get("page") ?? "";
const collaborationWorkspaceId = searchParams.get("workspace") ?? "";
const collaborationScopeKey = `${realtimeBusinessIds.join("|")}:${collaborationChannelId}:${collaborationWorkspaceId}`;

useEffect(() => {
  // Run even for an empty inbox: missed INSERTs must still be discoverable.
  let cursor: InboxSyncCursor | undefined;
  let batchOffset = 0;
  let hasMore = false;
  let failures = 0;
  let requestController: AbortController | null = null;
  let resyncTimer: number | null = null;
  let cancelled = false;
  let timer: number | null = null;

  async function syncCollaborativeState() {
    if (
      cancelled ||
      collaborationSyncInFlightRef.current ||
      document.visibilityState === "hidden" ||
      !navigator.onLine
    ) {
      return;
    }

    collaborationSyncInFlightRef.current = true;
    const controller = new AbortController();
    requestController = controller;
    const timeout = window.setTimeout(() => controller.abort(), SYNC_TIMEOUT_MS);
    const batch = takeSyncBatch(liveConversationsRef.current, batchOffset);
    const conversationIds = batch.rows.map(conversation => conversation.id);

    try {
      const response = await fetch(
        "/api/inbox/live-state",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          cache: "no-store",
          signal: controller.signal,
          body: JSON.stringify({
            conversationIds,
            cursor,
            channelId: collaborationChannelId || undefined,
            workspaceId: collaborationWorkspaceId || undefined,
          }),
        },
      );

      const text = await response.text();
      const contentType =
        response.headers.get("content-type") ?? "";

      if (response.status === 404) {
        throw new Error("Inbox sync route is unavailable. Restart Next.js after installing the patch.");
      }

      if (!contentType.toLowerCase().includes("application/json")) {
        throw new Error(
          `Collaborative Inbox fallback returned ${response.status} ${response.statusText || ""} with a non-JSON response.`,
        );
      }

      let result: CollaborativeInboxStateResponse | null = null;

      if (text.trim()) {
        try {
          result = JSON.parse(text) as CollaborativeInboxStateResponse;
        } catch {
          throw new Error(
            "Collaborative Inbox fallback returned invalid JSON.",
          );
        }
      }

      if (
        !response.ok ||
        !result?.success ||
        !Array.isArray(result.conversations)
      ) {
        throw new Error(
          result?.error ??
            "Unable to synchronize Inbox state.",
        );
      }

      if (cancelled) {
        return;
      }

      failures = 0;
      cursor = result.cursor ?? cursor;
      batchOffset = batch.nextOffset;
      hasMore = result.hasMore === true;
      const hydrated = result.hydratedConversations ?? [];
      const hydratedById = new Map(hydrated.map(row => [row.id, row]));
      const allowedBusinesses = result.accessibleBusinessIds ? new Set(result.accessibleBusinessIds) : null;
      const allowedChannels = result.activeChannelIds ? new Set(result.activeChannelIds) : null;
      const stateByConversationId = new Map(
        result.conversations.map((state) => [state.id, state]),
      );

      /*
       * V3.11.33 — global incoming-message alert safety net.
       *
       * The active thread already has a message-page poll, but inactive
       * conversations previously relied only on the messages Realtime INSERT
       * for their sound. If that INSERT was delayed/missed while the
       * conversations row still advanced, the left list updated but TENH was
       * silent. Compare the server-authoritative preview/unread state with the
       * current local snapshot and alert only when BOTH the message timestamp
       * and unread count advance. That excludes outgoing replies and manual
       * Mark as unread changes. Realtime remains the fast path; this is only a
       * deduplicated safety net for every customer conversation.
       */
      const currentConversationById = new Map(
        liveConversationsRef.current.map((conversation) => [
          conversation.id,
          conversation,
        ]),
      );

      for (const state of result.conversations) {
        const currentConversation =
          currentConversationById.get(state.id);

        if (!currentConversation || !state.last_message_at) {
          continue;
        }

        const localUnreadCount = Math.max(
          0,
          currentConversation.unread_count ?? 0,
        );
        const serverUnreadCount = Math.max(
          0,
          state.unread_count ?? 0,
        );
        const localLastMessageTime = currentConversation.last_message_at
          ? new Date(currentConversation.last_message_at).getTime()
          : 0;
        const serverLastMessageTime = new Date(
          state.last_message_at,
        ).getTime();
        const isNewIncomingFallback =
          serverUnreadCount > localUnreadCount &&
          Number.isFinite(serverLastMessageTime) &&
          serverLastMessageTime > 0 &&
          Number.isFinite(localLastMessageTime) &&
          localLastMessageTime > 0 &&
          serverLastMessageTime > localLastMessageTime;

        if (!isNewIncomingFallback) {
          continue;
        }

        const lastSoundedIncomingTime =
          lastSoundedIncomingMessageTimeRef.current.get(state.id) ?? 0;
        const alreadySoundedThisIncoming =
          lastSoundedIncomingTime > 0 &&
          Math.abs(
            serverLastMessageTime - lastSoundedIncomingTime,
          ) <= 100;

        if (alreadySoundedThisIncoming) {
          continue;
        }

        notifyIncomingMessage({
          messageId: `fallback-${state.id}-${state.last_message_at}`,
          conversationId: state.id,
          customerName:
            currentConversation.contact?.full_name?.trim() ||
            "Facebook customer",
          body:
            state.last_message_text?.trim() ||
            "New message",
        });

        lastSoundedIncomingMessageTimeRef.current.set(
          state.id,
          serverLastMessageTime,
        );
      }

      setLiveConversations((current) => {
        const currentIds = new Set(current.map(row => row.id));
        const additions = hydrated.filter(row => !currentIds.has(row.id));
        for (const row of additions) liveDiscoveredIdsRef.current.add(row.id);
        const combined = [...current, ...additions].filter(row =>
          (!allowedBusinesses || allowedBusinesses.has(row.business_id)) &&
          (!allowedChannels || !!row.social_account?.id && allowedChannels.has(row.social_account.id)));
        return sortLiveConversations(
          combined.map((conversation) => {
            const state = stateByConversationId.get(conversation.id);

            if (!state || isOlderConversationState(conversation, state)) return conversation;

            let nextConversation: InboxConversation = {
              ...conversation,
              ...hydratedById.get(conversation.id),
              updated_at: state.updated_at,
            };

            /*
             * Realtime is the fast path, but this server-authoritative fallback
             * must also advance the conversation preview/time when a message
             * INSERT event is missed. Without this, the left list appears stale
             * until a manual browser refresh. Never roll a newer local preview
             * backwards.
             */
            const localPreviewTime = conversation.last_message_at
              ? new Date(conversation.last_message_at).getTime()
              : 0;
            const serverPreviewTime = state.last_message_at
              ? new Date(state.last_message_at).getTime()
              : 0;

            let deletedPreviewOverride =
              deletedPreviewOverrideRef.current.get(conversation.id) ?? null;

            if (deletedPreviewOverride) {
              if (deletedPreviewOverride.expiresAt <= Date.now()) {
                deletedPreviewOverrideRef.current.delete(conversation.id);
                deletedPreviewOverride = null;
              } else if (
                Number.isFinite(serverPreviewTime) &&
                serverPreviewTime >
                  deletedPreviewOverride.lastMessageTime + 1000
              ) {
                deletedPreviewOverrideRef.current.delete(conversation.id);
                deletedPreviewOverride = null;
              }
            }

            if (deletedPreviewOverride) {
              nextConversation = {
                ...nextConversation,
                last_message_text: deletedPreviewOverride.text,
              };
            } else if (
              Number.isFinite(serverPreviewTime) &&
              serverPreviewTime > 0 &&
              (!Number.isFinite(localPreviewTime) ||
                localPreviewTime === 0 ||
                serverPreviewTime >= localPreviewTime)
            ) {
              nextConversation = {
                ...nextConversation,
                last_message_text:
                  state.last_message_text ??
                  nextConversation.last_message_text,
                last_message_at: state.last_message_at,
              };
            }

            /*
             * V3.11.32 fallback for shared read/unread state. Realtime remains
             * the fast path, while this 3-second authoritative sync guarantees
             * that every teammate still converges if a realtime UPDATE is lost.
             */
            const localUnreadCount = Math.max(
              0,
              conversation.unread_count ?? 0,
            );
            const serverUnreadCount = Math.max(
              0,
              typeof state.unread_count === "number"
                ? state.unread_count
                : localUnreadCount,
            );
            const localLastMessageTime = conversation.last_message_at
              ? new Date(conversation.last_message_at).getTime()
              : 0;
            const serverLastMessageTime = state.last_message_at
              ? new Date(state.last_message_at).getTime()
              : 0;
            const recentIncomingAt =
              recentIncomingConversationAtRef.current.get(conversation.id) ?? 0;
            const fallbackHasRecentIncoming =
              recentIncomingAt > 0 &&
              Date.now() - recentIncomingAt < 5_000;
            const fallbackMessageAdvanced =
              Number.isFinite(serverLastMessageTime) &&
              Number.isFinite(localLastMessageTime) &&
              serverLastMessageTime > 0 &&
              (localLastMessageTime === 0 ||
                serverLastMessageTime > localLastMessageTime);
            const fallbackUnreadFromMessage =
              serverUnreadCount > 0 &&
              (
                fallbackHasRecentIncoming ||
                (
                  fallbackMessageAdvanced &&
                  serverUnreadCount > localUnreadCount
                )
              );
            const readBarrier = readBarrierMessageTimeRef.current.get(conversation.id) ?? 0;
            const readVersion = readRowVersionRef.current.get(conversation.id) ?? 0;
            const remoteVersion = rowTime(state.updated_at);
            const readStillWins = readBarrier > 0 && serverLastMessageTime <= readBarrier &&
              (readInFlightRef.current.has(conversation.id) || remoteVersion <= readVersion);
            const fallbackManualUnread = serverUnreadCount > localUnreadCount &&
              !fallbackUnreadFromMessage && !fallbackMessageAdvanced && !readStillWins &&
              remoteVersion > Math.max(readVersion, rowTime(conversation.updated_at));

            if (readStillWins) {
              nextConversation.unread_count = 0;
            } else if (fallbackManualUnread) {
              manualUnreadConversationIdsRef.current.add(conversation.id);
              persistedManualUnreadCountsRef.current.set(conversation.id, serverUnreadCount);
              readBarrierMessageTimeRef.current.delete(conversation.id);
              nextConversation.unread_count = serverUnreadCount;
            } else if (!unreadWriteInFlightRef.current.has(conversation.id)) {
              if (serverUnreadCount === 0 || fallbackMessageAdvanced) {
                manualUnreadConversationIdsRef.current.delete(conversation.id);
                persistedManualUnreadCountsRef.current.delete(conversation.id);
              }
              if (fallbackMessageAdvanced) readBarrierMessageTimeRef.current.delete(conversation.id);
              nextConversation.unread_count = serverUnreadCount;
            }

            const pinOverride =
              pinOverrideRef.current.get(conversation.id);

            if (
              pinOverride &&
              pinOverride.expiresAt > Date.now() &&
              state.is_pinned !== pinOverride.isPinned
            ) {
              nextConversation = {
                ...nextConversation,
                is_pinned: pinOverride.isPinned,
                pinned_at: pinOverride.isPinned
                  ? nextConversation.pinned_at ?? new Date().toISOString()
                  : null,
                pinned_by: pinOverride.isPinned
                  ? nextConversation.pinned_by
                  : null,
              };
            } else {
              pinOverrideRef.current.delete(conversation.id);
              nextConversation = {
                ...nextConversation,
                is_pinned: state.is_pinned,
                pinned_at: state.pinned_at,
                pinned_by: state.pinned_by,
              };
            }

            const assignmentOverride =
              assignmentOverrideRef.current.get(conversation.id);

            if (
              assignmentOverride &&
              assignmentOverride.expiresAt > Date.now() &&
              state.assigned_to !== assignmentOverride.assignedTo
            ) {
              // Keep the in-flight local assignment until its API request settles.
            } else {
              assignmentOverrideRef.current.delete(conversation.id);
              nextConversation = {
                ...nextConversation,
                assigned_to: state.assigned_to,
                assigned_at: state.assigned_at,
                assigned_member: state.assigned_member,
              };
            }

            const statusOverride =
              statusOverrideRef.current.get(conversation.id);

            if (
              statusOverride &&
              statusOverride.expiresAt > Date.now() &&
              state.status !== statusOverride.status
            ) {
              // Keep the in-flight local status until its API request settles.
            } else {
              statusOverrideRef.current.delete(conversation.id);
              nextConversation = {
                ...nextConversation,
                status: state.status,
              };
            }

            if (
              state.contact_id &&
              nextConversation.contact?.id === state.contact_id
            ) {
              const tagOverride =
                contactTagsOverrideRef.current.get(state.contact_id);

              if (
                tagOverride &&
                tagOverride.expiresAt > Date.now()
              ) {
                const serverTagIds = new Set(
                  state.tags.map((tag) => tag.id),
                );
                const overrideTagIds = new Set(
                  tagOverride.tags.map((tag) => tag.id),
                );
                const serverMatchesOverride =
                  serverTagIds.size === overrideTagIds.size &&
                  Array.from(overrideTagIds).every((tagId) =>
                    serverTagIds.has(tagId),
                  );

                if (serverMatchesOverride) {
                  contactTagsOverrideRef.current.delete(state.contact_id);
                  nextConversation = {
                    ...nextConversation,
                    contact: {
                      ...nextConversation.contact,
                      tags: normalizeCustomerTags(state.tags),
                    },
                  };
                } else {
                  nextConversation = {
                    ...nextConversation,
                    contact: {
                      ...nextConversation.contact,
                      tags: tagOverride.tags,
                    },
                  };
                }
              } else {
                contactTagsOverrideRef.current.delete(state.contact_id);
                nextConversation = {
                  ...nextConversation,
                  contact: {
                    ...nextConversation.contact,
                    tags: normalizeCustomerTags(state.tags),
                  },
                };
              }
            }

            return nextConversation;
          }),
        );
      });
    } catch (error) {
      if (cancelled) return;
      failures += 1;
      // Realtime remains active; a temporary sync failure must never break Inbox.
      console.warn(
        "Unable to run collaborative Inbox fallback sync:",
        error,
      );
    } finally {
      window.clearTimeout(timeout);
      requestController = null;
      collaborationSyncInFlightRef.current = false;
    }
  }

  function scheduleNext() {
    if (cancelled) {
      return;
    }

    timer = window.setTimeout(async () => {
      await syncCollaborativeState();
      scheduleNext();
    }, failures ? Math.min(30_000, 5_000 * 2 ** Math.min(failures, 3)) : hasMore ? 250 : realtimeHealthyRef.current ? 60_000 : 5_000);
  }

  function handleVisibilityOrFocus() {
    if (document.visibilityState === "visible") {
      void syncCollaborativeState();
    }
  }

  function requestResync(event: Event) {
    if ((event as CustomEvent<{ activeOnly?: boolean }>).detail?.activeOnly || resyncTimer !== null) return;
    resyncTimer = window.setTimeout(() => { resyncTimer = null; void syncCollaborativeState(); }, 200);
  }
  window.addEventListener(INBOX_SYNC_EVENT, requestResync);
  void syncCollaborativeState();
  scheduleNext();

  window.addEventListener("focus", handleVisibilityOrFocus);
  window.addEventListener("online", handleVisibilityOrFocus);
  document.addEventListener("visibilitychange", handleVisibilityOrFocus);

  return () => {
    cancelled = true;
    requestController?.abort();
    window.removeEventListener(INBOX_SYNC_EVENT, requestResync);
    if (resyncTimer !== null) window.clearTimeout(resyncTimer);

    if (timer !== null) {
      window.clearTimeout(timer);
    }

    window.removeEventListener("focus", handleVisibilityOrFocus);
    window.removeEventListener("online", handleVisibilityOrFocus);
    document.removeEventListener("visibilitychange", handleVisibilityOrFocus);
  };
}, [
  collaborationScopeKey,
  notifyIncomingMessage,
]);

useEffect(() => {
  setLiveConversations((current) => {
    const currentById = new Map(
      current.map((conversation) => [conversation.id, conversation]),
    );

    const next = conversations.map((conversation) => {
      const previous =
        currentById.get(
          conversation.id,
        );
      const persistedManualUnreadCount =
        persistedManualUnreadCountsRef.current.get(
          conversation.id,
        ) ?? 0;

      const serverLastMessageTime =
        conversation.last_message_at
          ? new Date(
              conversation.last_message_at,
            ).getTime()
          : 0;
      const localLastMessageTime =
        previous?.last_message_at
          ? new Date(
              previous.last_message_at,
            ).getTime()
          : 0;
      const serverIsOlderThanLocal = previous
        ? isOlderConversationState(previous, conversation) : false;

      let mergedConversation =
        serverIsOlderThanLocal && previous
          ? {
              ...conversation,
              ...previous,
            }
          : conversation;

      const pinOverride =
        pinOverrideRef.current.get(conversation.id);

      if (pinOverride) {
        if (pinOverride.expiresAt <= Date.now()) {
          pinOverrideRef.current.delete(conversation.id);
        } else if (conversation.is_pinned === pinOverride.isPinned) {
          pinOverrideRef.current.delete(conversation.id);
        } else {
          mergedConversation = {
            ...mergedConversation,
            is_pinned: pinOverride.isPinned,
            pinned_at: pinOverride.isPinned
              ? previous?.pinned_at ??
                mergedConversation.pinned_at ??
                new Date().toISOString()
              : null,
            pinned_by: pinOverride.isPinned
              ? previous?.pinned_by ?? mergedConversation.pinned_by
              : null,
          };
        }
      }

      const assignmentOverride =
        assignmentOverrideRef.current.get(conversation.id);

      if (assignmentOverride) {
        if (assignmentOverride.expiresAt <= Date.now()) {
          assignmentOverrideRef.current.delete(conversation.id);
        } else if (
          conversation.assigned_to === assignmentOverride.assignedTo
        ) {
          assignmentOverrideRef.current.delete(conversation.id);
        } else {
          const optimisticMember = assignmentOverride.assignedTo
            ? teamMembers.find(
                (member) => member.id === assignmentOverride.assignedTo,
              ) ?? mergedConversation.assigned_member
            : null;

          mergedConversation = {
            ...mergedConversation,
            assigned_to: assignmentOverride.assignedTo,
            assigned_at: assignmentOverride.assignedTo
              ? previous?.assigned_at ??
                mergedConversation.assigned_at ??
                new Date().toISOString()
              : null,
            assigned_member: optimisticMember,
          };
        }
      }

      const statusOverride =
        statusOverrideRef.current.get(conversation.id);

      if (statusOverride) {
        if (statusOverride.expiresAt <= Date.now()) {
          statusOverrideRef.current.delete(conversation.id);
        } else if (conversation.status === statusOverride.status) {
          statusOverrideRef.current.delete(conversation.id);
        } else {
          mergedConversation = {
            ...mergedConversation,
            status: statusOverride.status,
          };
        }
      }

      const contactId = mergedConversation.contact?.id ?? null;
      if (contactId) {
        const tagOverride =
          contactTagsOverrideRef.current.get(contactId);

        if (tagOverride) {
          if (tagOverride.expiresAt <= Date.now()) {
            contactTagsOverrideRef.current.delete(contactId);
          } else {
            const serverTagIds = new Set(
              (conversation.contact?.tags ?? []).map((tag) => tag.id),
            );
            const overrideTagIds = new Set(
              tagOverride.tags.map((tag) => tag.id),
            );
            const serverMatchesOverride =
              serverTagIds.size === overrideTagIds.size &&
              Array.from(overrideTagIds).every((tagId) =>
                serverTagIds.has(tagId),
              );

            if (serverMatchesOverride) {
              contactTagsOverrideRef.current.delete(contactId);
            } else if (mergedConversation.contact) {
              mergedConversation = {
                ...mergedConversation,
                contact: {
                  ...mergedConversation.contact,
                  tags: tagOverride.tags,
                },
              };
            }
          }
        }
      }

      if (
        manualUnreadConversationIdsRef.current.has(
          conversation.id,
        ) ||
        persistedManualUnreadCount > 0
      ) {
        return {
          ...mergedConversation,
          unread_count: Math.max(
            1,
            persistedManualUnreadCount,
            previous?.unread_count ?? 0,
            mergedConversation.unread_count ?? 0,
          ),
        };
      }

      const readBarrier =
        readBarrierMessageTimeRef.current.get(
          conversation.id,
        ) ?? 0;
      const mergedMessageTime =
        mergedConversation.last_message_at
          ? new Date(
              mergedConversation.last_message_at,
            ).getTime()
          : 0;

      if (
        readBarrier > 0 &&
        Number.isFinite(mergedMessageTime)
      ) {
        if (
          mergedMessageTime <= readBarrier &&
          (readInFlightRef.current.has(conversation.id) ||
            rowTime(mergedConversation.updated_at) <= (readRowVersionRef.current.get(conversation.id) ?? 0))
        ) {
          mergedConversation = {
            ...mergedConversation,
            unread_count: 0,
          };
        } else {
          readBarrierMessageTimeRef.current.delete(
            conversation.id,
          );
        }
      }

      return mergedConversation;
    });

    const retained = retainKnownConversationRows(current, next, accessibleBusinessIds, collaborationChannelId, collaborationWorkspaceId);
    next.splice(0, next.length, ...retained);

    /*
     * Status/channel/view navigation can legitimately omit the currently
     * selected row from fresh server props. Keep that selected row in
     * local state so MessagePanel remains mounted; ConversationList applies
     * the active left-panel scope before rendering rows.
     */
    const selectedId =
      desiredConversationIdRef.current;

    if (
      selectedId &&
      !next.some((conversation) => conversation.id === selectedId)
    ) {
      const selectedPrevious = currentById.get(selectedId);

      if (selectedPrevious && accessibleBusinessIds.includes(selectedPrevious.business_id)) {
        const persistedManualUnreadCount =
          persistedManualUnreadCountsRef.current.get(selectedId) ?? 0;

        next.push({
          ...selectedPrevious,
          unread_count: Math.max(
            selectedPrevious.unread_count ?? 0,
            persistedManualUnreadCount,
          ),
        });
      }
    }

    return sortLiveConversations(next);
  });
}, [
  conversations,
]);

useEffect(() => {
  /*
   * Merge the newest server page into local state instead of
   * replacing it. This preserves older pages that V2.7 already
   * loaded when another action triggers router.refresh().
   */
  setLiveMessages(
    (current) => {
      if (
        !resolvedActiveConversationId
      ) {
        return [];
      }

      const merged =
        new Map<
          string,
          InboxMessage
        >();

      for (
        const message of current
      ) {
        if (
          message.conversation_id ===
          resolvedActiveConversationId
        ) {
          merged.set(
            message.id,
            message,
          );
        }
      }

      for (
        const message of messages
      ) {
        if (
          message.conversation_id !==
          resolvedActiveConversationId
        ) {
          continue;
        }

        const existing =
          merged.get(
            message.id,
          );

        const localAttachmentUrl =
          existing
            ?.attachment_url
            ?.startsWith(
              "blob:",
            )
            ? existing
                .attachment_url
            : null;

        merged.set(
          message.id,
          {
            ...existing,
            ...message,
            attachment_url:
              message.attachment_url ??
              localAttachmentUrl,
          } as InboxMessage,
        );
      }

      return Array.from(
        merged.values(),
      ).sort(
        (first, second) => {
          const timeDifference =
            messageOrderMs(first) -
              messageOrderMs(second);

          if (
            timeDifference !== 0
          ) {
            return timeDifference;
          }

          return first.id.localeCompare(
            second.id,
          );
        },
      );
    },
  );
}, [
  messages,
  resolvedActiveConversationId,
]);

/*
 * V3.11.16.8 — latest-page cache + prefetch.
 * Conversation rows can warm the next thread on hover/focus, then selection
 * swaps local state immediately while the URL is updated with History API.
 */
const loadConversationMessagePage =
  useCallback(
    async (
      conversationId: string,
      options?: {
        forceRefresh?: boolean;
      },
    ): Promise<ConversationMessagePage> => {
      const forceRefresh =
        options?.forceRefresh ??
        false;

      const cached =
        getCachedConversationPage(
          conversationId,
        );

      if (
        cached &&
        !forceRefresh
      ) {
        return cached;
      }

      const pending =
        conversationMessageRequestRef
          .current[conversationId];

      if (pending) {
        return pending;
      }

      const controller =
        new AbortController();

      conversationMessageAbortRef
        .current[conversationId] =
        controller;

      const request = (async () => {
        const params =
          new URLSearchParams({
            limit:
              String(
                MESSAGE_PAGE_SIZE,
              ),
          });

        const response = await fetch(
          `/api/conversations/${conversationId}/messages?${params.toString()}`,
          {
            method: "GET",
            cache: "no-store",
            headers: { Accept: "application/json" },
            signal:
              AbortSignal.any([controller.signal, AbortSignal.timeout(SYNC_TIMEOUT_MS)]),
          },
        );

        const result = await readMessagePageResponse(response);

        // An ignored abort must not repopulate a retired thread's page cache.
        controller.signal.throwIfAborted();

        const nextMessages =
          (Array.isArray(
            result.messages,
          )
            ? result.messages
            : []
          )
            .filter(
              (message) =>
                message.conversation_id ===
                conversationId,
            )
            .sort(
              (first, second) => {
                const timeDifference =
                  messageOrderMs(first) -
              messageOrderMs(second);

                if (
                  timeDifference !== 0
                ) {
                  return timeDifference;
                }

                return first.id.localeCompare(
                  second.id,
                );
              },
            );

        const now = Date.now();
        const page: ConversationMessagePage = {
          messages:
            nextMessages,
          hasMore:
            typeof result.hasMore ===
              "boolean"
              ? result.hasMore
              : nextMessages.length >=
                MESSAGE_PAGE_SIZE,
          fetchedAt:
            now,
          lastAccessedAt:
            now,
        };

        setCachedConversationPage(
          conversationId,
          page,
        );

        return page;
      })();

      conversationMessageRequestRef
        .current[conversationId] =
        request;

      try {
        return await request;
      } finally {
        if (
          conversationMessageAbortRef
            .current[conversationId] ===
          controller
        ) {
          delete conversationMessageAbortRef
            .current[conversationId];
        }

        if (
          conversationMessageRequestRef
            .current[conversationId] ===
          request
        ) {
          delete conversationMessageRequestRef
            .current[conversationId];
        }
      }
    },
    [
      getCachedConversationPage,
      setCachedConversationPage,
    ],
  );

const prefetchConversation =
  useCallback(
    (
      conversationId: string,
    ) => {
      if (
        conversationId ===
          resolvedActiveConversationId ||
        getCachedConversationPage(
          conversationId,
        )
      ) {
        return;
      }

      void loadConversationMessagePage(
        conversationId,
      ).catch((error) => {
        if (
          isAbortError(error)
        ) {
          return;
        }

        // Prefetch is best-effort. A click will retry and surface loading.
      });
    },
    [
      getCachedConversationPage,
      loadConversationMessagePage,
      resolvedActiveConversationId,
    ],
  );

const [searchJump, setSearchJump] = useState<{ conversationId: string; messageId: string; nonce: number } | null>(null);

const selectConversationSmoothly =
  useCallback(
    async (
      conversationId: string,
      updateHistory = false,
    ) => {
      const targetConversation =
        liveConversations.find(
          (conversation) =>
            conversation.id ===
            conversationId,
        );

      if (!targetConversation) {
        return;
      }

      // Keep the global workspace selection unchanged. The selected thread's
      // own business id is resolved and authorized by Inbox APIs.

      if (
        conversationId ===
          desiredConversationIdRef.current &&
        conversationId ===
          resolvedActiveConversationId
      ) {
        return;
      }

      const currentConversationId =
        resolvedActiveConversationId;

      setReplyingToCommentId(null);

      /*
       * Reopening a conversation that was manually marked unread is the
       * deliberate acknowledgement point. Clear only the destination's
       * persisted marker so the normal automatic /read flow can run.
       */
      if (
        currentConversationId !== conversationId
      ) {
        manualUnreadConversationIdsRef.current.delete(
          conversationId,
        );
        persistedManualUnreadCountsRef.current.delete(
          conversationId,
        );
      }

      if (
        currentConversationId &&
        currentConversationId !== conversationId
      ) {
        manualUnreadConversationIdsRef.current.delete(
          currentConversationId,
        );
      }

      if (
        currentConversationId &&
        !loadingConversationMessages
      ) {
        const scopedCurrentMessages =
          liveMessages.filter(
            (message) =>
              message.conversation_id ===
              currentConversationId,
          );

        if (
          scopedCurrentMessages.length ===
            liveMessages.length
        ) {
          const existing =
            getCachedConversationPage(
              currentConversationId,
            );

          setCachedConversationPage(
            currentConversationId,
            {
              messages:
                scopedCurrentMessages,
              hasMore:
                hasMoreOlderMessages,
              fetchedAt:
                existing?.fetchedAt ??
                Date.now(),
            },
          );
        }
      }

      /*
       * V3.11.17 — a rapid A -> B -> C switch should not leave old selected
       * message requests consuming bandwidth or racing the new selection.
       * Keep a request for the destination conversation if it was prefetched.
       */
      abortConversationRequestsExcept(
        conversationId,
      );

      retireComposerSubmissionScope();
      desiredConversationIdRef.current =
        conversationId;
      setClientSelectedConversationId(
        conversationId,
      );

      /*
       * Drop the badge here rather than waiting for the auto-read effect. That
       * effect only runs on the render after the selection lands, so on a busy
       * inbox the badge visibly lingered for a beat after the click. The server
       * PATCH still happens there; this is only the optimistic paint.
       */
      if (
        !manualUnreadConversationIdsRef.current.has(
          conversationId,
        ) &&
        (targetConversation.unread_count ?? 0) > 0
      ) {
        pendingReadCountsRef.current.set(conversationId, targetConversation.unread_count);
        pendingReadIdsRef.current.add(conversationId);

        setLiveConversations((current) =>
          current.map((conversation) =>
            conversation.id === conversationId
              ? { ...conversation, unread_count: 0 }
              : conversation,
          ),
        );
      }
      setOlderMessagesError(null);
      setConversationMessagesError(
        null,
      );
      setLoadingOlderMessages(false);

      const cached =
        getCachedConversationPage(
          conversationId,
        );

      if (cached) {
        setLiveMessages(
          cached.messages,
        );
        setHasMoreOlderMessages(
          cached.hasMore,
        );
        setLoadingConversationMessages(
          false,
        );

        /*
         * Show warm cache immediately, but always verify the newest server
         * page on an explicit conversation click. Realtime can be briefly
         * disconnected and a 15-second cache is long enough to hide the true
         * latest message on the first open. The refresh is quiet and keeps
         * optimistic local attachments/messages intact.
         */
        void loadConversationMessagePage(
          conversationId,
          {
            forceRefresh: true,
          },
        )
          .then((page) => {
            if (
              desiredConversationIdRef
                .current !==
              conversationId
            ) {
              return;
            }

            setLiveMessages(
              (current) => {
                const currentById =
                  new Map(
                    current.map(
                      (message) => [
                        message.id,
                        message,
                      ],
                    ),
                  );

                const merged =
                  page.messages.map(
                    (message) => {
                      const existing =
                        currentById.get(
                          message.id,
                        );

                      const localAttachmentUrl =
                        existing?.attachment_url?.startsWith(
                          "blob:",
                        )
                          ? existing.attachment_url
                          : null;

                      return {
                        ...existing,
                        ...message,
                        attachment_url:
                          message.attachment_url ??
                          localAttachmentUrl,
                      } as InboxMessage;
                    },
                  );

                for (
                  const message of current
                ) {
                  if (
                    message.id.startsWith(
                      "optimistic:",
                    ) &&
                    !merged.some(
                      (candidate) =>
                        candidate.id ===
                        message.id,
                    )
                  ) {
                    merged.push(message);
                  }
                }

                return merged.sort(
                  (first, second) => {
                    const timeDifference =
                      messageOrderMs(first) -
              messageOrderMs(second);

                    return timeDifference !== 0
                      ? timeDifference
                      : first.id.localeCompare(
                          second.id,
                        );
                  },
                );
              },
            );

            setHasMoreOlderMessages(
              page.hasMore,
            );
          })
          .catch((error) => {
            if (
              isAbortError(error)
            ) {
              return;
            }

            // Cached data remains usable if the quiet refresh fails.
            console.warn(
              "Unable to refresh cached conversation messages:",
              error,
            );
          });
      } else {
        setLiveMessages([]);
        setHasMoreOlderMessages(
          false,
        );
        setLoadingConversationMessages(
          true,
        );

        void loadConversationMessagePage(
          conversationId,
        )
          .then((page) => {
            if (
              desiredConversationIdRef
                .current !==
              conversationId
            ) {
              return;
            }

            setLiveMessages(
              page.messages,
            );
            setHasMoreOlderMessages(
              page.hasMore,
            );
          })
          .catch((error) => {
            if (
              isAbortError(error)
            ) {
              return;
            }

            if (
              desiredConversationIdRef
                .current !==
              conversationId
            ) {
              return;
            }

            setConversationMessagesError(
              error instanceof Error
                ? error.message
                : "Unable to load conversation messages.",
            );
          })
          .finally(() => {
            if (
              desiredConversationIdRef
                .current ===
              conversationId
            ) {
              setLoadingConversationMessages(
                false,
              );
            }
          });
      }

      if (
        updateHistory &&
        typeof window !==
          "undefined"
      ) {
        const params =
          new URLSearchParams(
            window.location.search,
          );

        params.set(
          "conversation",
          conversationId,
        );

        const query =
          params.toString();

        ownConversationUrlPushesRef.current.push(
          conversationId,
        );

        window.history.pushState(
          null,
          "",
          query
            ? `/dashboard/inbox?${query}`
            : "/dashboard/inbox",
        );
      }
    },
    [
      abortConversationRequestsExcept,
      getCachedConversationPage,
      hasMoreOlderMessages,
      liveConversations,
      liveMessages,
      loadConversationMessagePage,
      loadingConversationMessages,
      resolvedActiveConversationId,
      setCachedConversationPage,
      activeBusinessId,
      searchParams,
      retireComposerSubmissionScope,
    ],
  );

const clearConversationSelection =
  useCallback(() => {
    setReplyingToCommentId(null);
    const currentConversationId =
      resolvedActiveConversationId;

    if (currentConversationId) {
      manualUnreadConversationIdsRef.current.delete(
        currentConversationId,
      );
    }

    if (
      currentConversationId &&
      !loadingConversationMessages
    ) {
      const scopedMessages = liveMessages.filter(
        (message) =>
          message.conversation_id === currentConversationId,
      );

      if (scopedMessages.length === liveMessages.length) {
        const existing = getCachedConversationPage(
          currentConversationId,
        );
        setCachedConversationPage(
          currentConversationId,
          {
            messages: scopedMessages,
            hasMore: hasMoreOlderMessages,
            fetchedAt: existing?.fetchedAt ?? Date.now(),
          },
        );
      }
    }

    abortConversationRequestsExcept(null);
    retireComposerSubmissionScope();
    desiredConversationIdRef.current = null;
    setClientSelectedConversationId(null);
  if (compactWeb) setCustomerPanelVisible(false);
    setLiveMessages([]);
    setHasMoreOlderMessages(false);
    setLoadingConversationMessages(false);
    setConversationMessagesError(null);
    setOlderMessagesError(null);

    if (typeof window !== "undefined") {
      const params = new URLSearchParams(window.location.search);
      params.delete("conversation");
      const query = params.toString();
      window.history.replaceState(
        null,
        "",
        query ? `/dashboard/inbox?${query}` : "/dashboard/inbox",
      );
    }
  }, [
    abortConversationRequestsExcept,
    getCachedConversationPage,
    hasMoreOlderMessages,
    liveMessages,
    loadingConversationMessages,
    resolvedActiveConversationId,
    setCachedConversationPage,
    retireComposerSubmissionScope,
    compactWeb,
  ]);

const selectSearchConversation = useCallback((conversationId: string, match?: InboxSearchMatch) => {
  setSearchJump(match ? { conversationId, messageId: match.messageId, nonce: Date.now() } : null);
  // An explicit click owns the URL too, so URL, row, header and messages agree.
  void selectConversationSmoothly(conversationId, true);
}, [selectConversationSmoothly]);

const retryConversationMessages =
  useCallback(() => {
    const conversationId =
      desiredConversationIdRef
        .current ??
      resolvedActiveConversationId;

    if (!conversationId) {
      return;
    }

    delete conversationMessageCacheRef
      .current[conversationId];

    conversationMessageAbortRef
      .current[conversationId]
      ?.abort();
    delete conversationMessageAbortRef
      .current[conversationId];
    delete conversationMessageRequestRef
      .current[conversationId];

    setConversationMessagesError(
      null,
    );
    setLoadingConversationMessages(
      true,
    );

    void loadConversationMessagePage(
      conversationId,
    )
      .then((page) => {
        if (
          desiredConversationIdRef
            .current !==
          conversationId
        ) {
          return;
        }

        setLiveMessages(
          page.messages,
        );
        setHasMoreOlderMessages(
          page.hasMore,
        );
      })
      .catch((error) => {
        if (
          desiredConversationIdRef
            .current !==
          conversationId
        ) {
          return;
        }

        setConversationMessagesError(
          error instanceof Error
            ? error.message
            : "Unable to load conversation messages.",
        );
      })
      .finally(() => {
        if (
          desiredConversationIdRef
            .current ===
          conversationId
        ) {
          setLoadingConversationMessages(
            false,
          );
        }
      });
  }, [
    loadConversationMessagePage,
    resolvedActiveConversationId,
  ]);

/*
 * Keep cache aligned with realtime/optimistic changes for the active thread.
 */
useEffect(() => {
  if (
    !resolvedActiveConversationId ||
    loadingConversationMessages
  ) {
    return;
  }

  const scopedMessages =
    liveMessages.filter(
      (message) =>
        message.conversation_id ===
        resolvedActiveConversationId,
    );

  if (
    scopedMessages.length !==
      liveMessages.length
  ) {
    return;
  }

  const existing =
    getCachedConversationPage(
      resolvedActiveConversationId,
    );

  setCachedConversationPage(
    resolvedActiveConversationId,
    {
      messages:
        scopedMessages,
      hasMore:
        hasMoreOlderMessages,
      fetchedAt:
        existing?.fetchedAt ??
        Date.now(),
    },
  );
}, [
  getCachedConversationPage,
  hasMoreOlderMessages,
  liveMessages,
  loadingConversationMessages,
  resolvedActiveConversationId,
  setCachedConversationPage,
]);

/*
 * Active-thread live safety net.
 *
 * Supabase Realtime remains the fast path. In production, a publication/RLS
 * delay or a transient websocket disconnect can occasionally cause a message
 * INSERT event to be missed. Previously the open chat then stayed stale until
 * the user refreshed the browser. Quietly fetch only the newest message page
 * while a thread is open and merge it into local state. Older loaded pages and
 * optimistic outgoing messages are preserved.
 */
useEffect(() => {
  if (!resolvedActiveConversationId) {
    return;
  }

  const conversationId: string =
    resolvedActiveConversationId;

  let cancelled = false;
  let timer: number | null = null;
  let inFlight = false;
  let controller: AbortController | null = null;
  let requestTimeout: number | null = null;
  let resyncTimer: number | null = null;
  let failures = 0;

  /*
   * Seed the fallback with messages already loaded for this thread. If the
   * thread has not loaded yet, the first successful fetch becomes the baseline
   * so old history never triggers a burst of alert sounds.
   */
  const fallbackKnownMessageIds = new Set(
    liveMessagesRef.current
      .filter(
        (message) =>
          message.conversation_id === conversationId,
      )
      .map((message) => message.id),
  );
  let fallbackBaselineReady =
    fallbackKnownMessageIds.size > 0;

  const mergeNewestPage = (
    current: InboxMessage[],
    serverMessages: InboxMessage[],
  ) => {
    /*
     * The polling fallback can discover the real outgoing row before the
     * Supabase INSERT event reaches this browser. Reconcile that row with the
     * optimistic bubble exactly like the Realtime path does; otherwise the
     * temporary bubble and the real row are both rendered.
     */
    const merged = [...current];
    let needsSort = false;

    for (const serverMessage of serverMessages) {
      const existingIndex = merged.findIndex(
        (message) =>
          message.id === serverMessage.id,
      );

      if (existingIndex >= 0) {
        const existing = merged[existingIndex];
        const localAttachmentUrl =
          existing.attachment_url?.startsWith("blob:")
            ? existing.attachment_url
            : null;

        merged[existingIndex] = {
          ...existing,
          ...serverMessage,
          attachment_url:
            serverMessage.attachment_url ??
            localAttachmentUrl,
        } as InboxMessage;

        continue;
      }

      let optimisticIndex = -1;

      if (serverMessage.direction === "outgoing") {
        optimisticIndex = merged.findIndex(candidate => {
          const optimistic = candidate as OptimisticInboxMessage;
          return Boolean(optimistic.__optimistic_status) && matchesOptimisticMessage(candidate, serverMessage);
        });
      }

      if (optimisticIndex >= 0) {
        const optimisticMessage =
          merged[optimisticIndex];
        const optimisticId =
          optimisticMessage.id;
        const localAttachmentUrl =
          optimisticMessage.attachment_url?.startsWith("blob:")
            ? optimisticMessage.attachment_url
            : null;

        delete pendingSendsRef.current[
          optimisticId
        ];
        delete pendingAttachmentSendsRef.current[
          optimisticId
        ];

        merged[optimisticIndex] = retainLocalImagePreview(withOptimisticRenderKey({
          ...serverMessage,
          attachment_url:
            serverMessage.attachment_url ??
            localAttachmentUrl,
        } as InboxMessage, optimisticMessage), optimisticMessage);

        continue;
      }

      merged.push(serverMessage);
      needsSort = true;
    }

    return needsSort ? merged.sort(
      (first, second) => {
        const timeDifference =
          messageOrderMs(first) -
      messageOrderMs(second);

        return timeDifference !== 0
          ? timeDifference
          : first.id.localeCompare(second.id);
      },
    ) : merged;
  };

  async function syncNewestMessages() {
    if (
      cancelled ||
      inFlight ||
      document.visibilityState === "hidden" ||
      !navigator.onLine
    ) {
      return;
    }

    inFlight = true;
    const requestController = new AbortController();
    controller = requestController;
    const timeout = window.setTimeout(() => requestController.abort(), SYNC_TIMEOUT_MS);
    requestTimeout = timeout;

    try {
      const params = new URLSearchParams({
        limit: String(MESSAGE_PAGE_SIZE),
        live: String(Date.now()),
      });
      const response = await fetch(
        `/api/conversations/${conversationId}/messages?${params.toString()}`,
        {
          method: "GET",
          cache: "no-store",
          signal: requestController.signal,
          headers: {
            Accept: "application/json",
          },
        },
      );
      const result = await readMessagePageResponse(response);
      failures = 0;

      const newestMessages = Array.isArray(result.messages)
        ? result.messages.filter(
            (message) =>
              message.conversation_id === conversationId,
          )
        : [];

      if (cancelled) {
        return;
      }

      const newlyDiscoveredIncoming =
        fallbackBaselineReady
          ? newestMessages.filter(
              (message) =>
                message.direction === "incoming" &&
                !fallbackKnownMessageIds.has(message.id) &&
                !handledIncomingMessageIdsRef.current.has(
                  message.id,
                ),
            )
          : [];

      for (const message of newestMessages) {
        fallbackKnownMessageIds.add(message.id);
      }
      fallbackBaselineReady = true;

      for (const message of newlyDiscoveredIncoming) {
        handledIncomingMessageIdsRef.current.add(message.id);
        recentIncomingConversationAtRef.current.set(
          conversationId,
          Date.now(),
        );

        const notificationConversation =
          liveConversationsRef.current.find(
            (conversation) =>
              conversation.id === conversationId,
          );

        const incomingMessageAt =
          message.platform_created_at ??
          message.created_at ??
          null;
        const incomingMessageTime =
          incomingMessageAt
            ? new Date(incomingMessageAt).getTime()
            : 0;
        const lastSoundedIncomingTime =
          lastSoundedIncomingMessageTimeRef.current.get(
            conversationId,
          ) ?? 0;
        const alreadySoundedThisIncoming =
          incomingMessageTime > 0 &&
          lastSoundedIncomingTime > 0 &&
          Math.abs(
            incomingMessageTime - lastSoundedIncomingTime,
          ) <= 100;

        if (!alreadySoundedThisIncoming) {
          notifyIncomingMessage({
            messageId: message.id,
            conversationId,
            customerName:
              notificationConversation?.contact?.full_name?.trim() ||
              "Facebook customer",
            body: getRealtimeMessagePreview(
              message as unknown as Record<string, unknown>,
            ),
          });

          if (incomingMessageTime > 0) {
            lastSoundedIncomingMessageTimeRef.current.set(
              conversationId,
              incomingMessageTime,
            );
          }
        }
      }

      setLiveMessages((current) => {
        const nextMessages = mergeNewestPage(
          current.filter(
            (message) =>
              message.conversation_id ===
              conversationId,
          ),
          newestMessages,
        );

        liveMessagesRef.current = nextMessages;
        return nextMessages;
      });

      /*
       * If Supabase Realtime missed the INSERT, keep the conversation row in
       * sync from the same server-authoritative message page. This prevents the
       * left list preview/time from remaining stale until a browser refresh.
       */
      const latestServerMessage =
        newestMessages[newestMessages.length - 1] ?? null;

      if (latestServerMessage) {
        const latestMessageAt =
          latestServerMessage.platform_created_at ??
          latestServerMessage.created_at;
        const latestMessageTime = new Date(
          latestMessageAt,
        ).getTime();
        const latestPreview = getRealtimeMessagePreview(
          latestServerMessage as unknown as Record<string, unknown>,
        );

        setLiveConversations((current) =>
          sortLiveConversations(
            current.map((conversation) => {
              if (conversation.id !== conversationId) {
                return conversation;
              }

              const currentMessageTime = conversation.last_message_at
                ? new Date(conversation.last_message_at).getTime()
                : 0;

              if (
                Number.isFinite(currentMessageTime) &&
                Number.isFinite(latestMessageTime) &&
                currentMessageTime > latestMessageTime + 1000
              ) {
                return conversation;
              }

              return {
                ...conversation,
                last_message_text: latestPreview,
                last_message_at: latestMessageAt,
              };
            }),
          ),
        );
      }
    } catch (error) {
      if (!cancelled) failures += 1;
      if (!cancelled && !isAbortError(error)) {
        console.warn(
          "Unable to run active-thread live message fallback:",
          error,
        );
      }
    } finally {
      window.clearTimeout(timeout);
      requestTimeout = null;
      controller = null;
      inFlight = false;
    }
  }

  function scheduleNext() {
    if (cancelled) {
      return;
    }

    timer = window.setTimeout(async () => {
      await syncNewestMessages();
      scheduleNext();
    }, failures ? Math.min(30_000, 3_000 * 2 ** Math.min(failures, 4)) : realtimeHealthyRef.current ? 60_000 : 3_000);
  }

  function syncWhenVisible() {
    if (document.visibilityState === "visible") {
      void syncNewestMessages();
    }
  }

  /*
   * Do not wait for the first timer tick. If the websocket was disconnected
   * before this thread opened, fetch the latest page immediately and then keep
   * the lightweight safety-net poll running in the background.
   */
  function requestMessageResync(event: Event) {
    const id = (event as CustomEvent<{ conversationId?: string }>).detail?.conversationId;
    if (id && id !== conversationId || resyncTimer !== null) return;
    resyncTimer = window.setTimeout(() => { resyncTimer = null; void syncNewestMessages(); }, 150);
  }
  window.addEventListener(INBOX_SYNC_EVENT, requestMessageResync);
  void syncNewestMessages();
  scheduleNext();
  window.addEventListener("focus", syncWhenVisible);
  window.addEventListener("online", syncWhenVisible);
  document.addEventListener(
    "visibilitychange",
    syncWhenVisible,
  );

  return () => {
    cancelled = true;
    controller?.abort();
    if (requestTimeout !== null) window.clearTimeout(requestTimeout);
    window.removeEventListener(INBOX_SYNC_EVENT, requestMessageResync);
    if (resyncTimer !== null) window.clearTimeout(resyncTimer);

    if (timer !== null) {
      window.clearTimeout(timer);
    }

    window.removeEventListener("focus", syncWhenVisible);
    window.removeEventListener("online", syncWhenVisible);
    document.removeEventListener(
      "visibilitychange",
      syncWhenVisible,
    );
  };
}, [
  notifyIncomingMessage,
  resolvedActiveConversationId,
]);

/*
 * Browser Back/Forward and direct links change ?conversation= without a route
 * reload. Mirror only real URL changes into the same smooth client switch; a
 * stale URL snapshot or our own lagging push must never undo a newer click.
 */
const isConversationAvailable = useCallback(
