async function handleLoadOlderMessages(): Promise<boolean> {
  const conversationId = resolvedActiveConversationId;
  if (!conversationId) return false;
  const pending = olderMessageFlightRef.current.get(conversationId);
  if (pending) { setLoadingOlderMessages(true); return pending.promise; }
  const flight = { promise: loadOlderMessagePage() };
  olderMessageFlightRef.current.set(conversationId, flight);
  try { return await flight.promise; }
  finally { if (olderMessageFlightRef.current.get(conversationId) === flight) olderMessageFlightRef.current.delete(conversationId); }
}

async function loadOlderMessagePage(): Promise<boolean> {
  const conversationId =
    resolvedActiveConversationId;

  if (
    !conversationId ||
    !hasMoreOlderMessages
  ) {
    return false;
  }

  /*
   * The array is kept oldest → newest. Optimistic messages are
   * always recent, but skip them defensively when building the
   * database cursor.
   */
  const oldestPersistedMessage =
    liveMessages.find(
      (message) =>
        message.conversation_id === conversationId &&
        !message.id.startsWith(
          "optimistic:",
        ) &&
        Boolean(
          message.created_at,
        ),
    ) ?? null;

  if (!oldestPersistedMessage) {
    setHasMoreOlderMessages(
      false,
    );
    return false;
  }

  setLoadingOlderMessages(true);
  setOlderMessagesError(null);

  try {
    const searchParams =
      new URLSearchParams({
        beforeCreatedAt:
          oldestPersistedMessage.platform_created_at ?? oldestPersistedMessage.created_at,
        beforeId:
          oldestPersistedMessage.id,
        limit:
          String(
            MESSAGE_PAGE_SIZE,
          ),
      });

    const response =
      await fetch(
        `/api/conversations/${conversationId}/messages?${searchParams.toString()}`,
        {
          method: "GET",
          cache: "no-store",
          headers: { Accept: "application/json" },
        },
      );

    const result = await readMessagePageResponse(response);

    const olderMessages =
      Array.isArray(
        result.messages,
      )
        ? result.messages.filter(message => message.conversation_id === conversationId)
        : [];

    /*
     * The agent may switch threads while this older-page request is in flight.
     * Never prepend Conversation A messages into Conversation B.
     */
    if (
      desiredConversationIdRef
        .current !==
      conversationId
    ) {
      return false;
    }

    setHasMoreOlderMessages(
      Boolean(
        result.hasMore,
      ),
    );

    if (
      olderMessages.length === 0
    ) {
      return false;
    }

    setLiveMessages(
      (current) => {
        if (desiredConversationIdRef.current !== conversationId) return current;
        const merged =
          new Map<
            string,
            InboxMessage
          >();

        for (
          const message of [
            ...olderMessages,
            ...current,
          ]
        ) {
          const existing =
            merged.get(
              message.id,
            );

          const localAttachmentUrl =
            existing
              ?.attachment_url
              ?.startsWith(
                "blob:",
              )
              ? existing
                  .attachment_url
              : message
                  .attachment_url
                    ?.startsWith(
                      "blob:",
                    )
                ? message
                    .attachment_url
                : null;

          merged.set(
            message.id,
            {
              ...existing,
              ...message,
              attachment_url:
                message
                  .attachment_url ??
                existing
                  ?.attachment_url ??
                localAttachmentUrl,
            } as InboxMessage,
          );
        }

        return Array.from(
          merged.values(),
        ).sort(
          (first, second) => {
            const timeDifference =
              messageOrderMs(first) -
              messageOrderMs(second);

            if (
              timeDifference !== 0
            ) {
              return timeDifference;
            }

            return first.id.localeCompare(
              second.id,
            );
          },
        );
      },
    );

    return true;
  } catch (error) {
    if (desiredConversationIdRef.current !== conversationId) return false;
    const message =
      error instanceof Error
        ? error.message
        : "Unable to load older messages.";

    setOlderMessagesError(
      message,
    );

    console.error(
      "Unable to load older messages:",
      error,
    );

    return false;
  } finally {
    if (desiredConversationIdRef.current === conversationId) setLoadingOlderMessages(false);
  }
}

