useEffect(() => {
  if (!resolvedActiveConversationId) {
    return;
  }

  const currentConversation =
    liveConversations.find(
      (conversation) =>
        conversation.id ===
        resolvedActiveConversationId,
    );

  if (
    !currentConversation ||
    (currentConversation.unread_count === 0 &&
      !pendingReadIdsRef.current.has(
        resolvedActiveConversationId,
      )) ||
    manualUnreadConversationIdsRef.current.has(
      resolvedActiveConversationId,
    )
  ) {
    return;
  }

  /*
   * Use the same tracked read request used by realtime handling. This prevents
   * a second untracked /read PATCH from racing with Mark unread.
   */
  void markConversationReadRealtime(
    resolvedActiveConversationId,
  );
}, [
  liveConversations,
  resolvedActiveConversationId,
]);

  const handlePageRows = useCallback((rows: InboxConversation[]) => {
    for (const row of rows) liveDiscoveredIdsRef.current.add(row.id);
    setLiveConversations(current => {
      const merged = mergeConversationPage(current, rows);
      return merged.map(row => {
        const pin = pinOverrideRef.current.get(row.id);
        const status = statusOverrideRef.current.get(row.id);
        const assignment = assignmentOverrideRef.current.get(row.id);
        const tags = row.contact?.id ? contactTagsOverrideRef.current.get(row.contact.id) : null;
        let next = { ...row,
          ...(pin && pin.expiresAt > Date.now() ? { is_pinned: pin.isPinned } : {}),
          ...(status && status.expiresAt > Date.now() ? { status: status.status } : {}),
          ...(assignment && assignment.expiresAt > Date.now() ? { assigned_to: assignment.assignedTo } : {}),
          ...(tags && tags.expiresAt > Date.now() && row.contact ? { contact: { ...row.contact, tags: tags.tags } } : {}),
        };
        const unread = persistedManualUnreadCountsRef.current.get(row.id) ?? 0;
        if (manualUnreadConversationIdsRef.current.has(row.id) || unread > 0) next = { ...next, unread_count: Math.max(1, unread, row.unread_count ?? 0) };
        else {
          const barrier = readBarrierMessageTimeRef.current.get(row.id) ?? 0;
          if (barrier && rowTime(row.last_message_at) <= barrier && (readInFlightRef.current.has(row.id) || rowTime(row.updated_at) <= (readRowVersionRef.current.get(row.id) ?? 0))) next = { ...next, unread_count: 0 };
        }
        return next;
      });
    });
  }, [setLiveConversations]);

  const handleMarkAllRead = useCallback(async (rows: InboxConversation[], completeTargets?: ReadTarget[]): Promise<BulkReadResult> => {
    if (bulkReadInFlightRef.current) return { marked: 0, skipped: 0, failed: 0 };
    const targets = completeTargets ?? snapshotUnread(rows);
    const totals: BulkReadResult = { marked: 0, skipped: 0, failed: 0 };
    if (!targets.length) return totals;
    bulkReadInFlightRef.current = true;
    setMarkingAllRead(true);
    try {
      // Sequential bounded batches, not hundreds of simultaneous PATCH calls.
      for (let offset = 0; offset < targets.length; offset += 100) {
        const batch = targets.slice(offset, offset + 100);
        try {
          const response = await fetch("/api/inbox/mark-all-read", {
            method: "POST", cache: "no-store", signal: AbortSignal.timeout(SYNC_TIMEOUT_MS),
            headers: { "Content-Type": "application/json", Accept: "application/json" },
            body: JSON.stringify({ targets: batch }),
          });
          const result = await response.json() as { success?: boolean; conversations?: ReadReceipt[]; skippedIds?: string[]; failedIds?: string[] };
          if (!response.ok || !result.success || !Array.isArray(result.conversations)) throw new Error("Unable to mark this batch as read.");
          totals.marked += result.conversations.length;
          totals.skipped += result.skippedIds?.length ?? 0;
          totals.failed += result.failedIds?.length ?? 0;
          const targetById = new Map(batch.map(target => [target.id, target]));
          const receiptById = new Map(result.conversations.map(receipt => [receipt.id, receipt]));
          setLiveConversations(current => current.map(conversation => {
            const receipt = receiptById.get(conversation.id);
            const target = targetById.get(conversation.id);
            if (!receipt || !target || !receiptStillApplies(conversation, receipt, target)) return conversation;
            manualUnreadConversationIdsRef.current.delete(conversation.id);
            persistedManualUnreadCountsRef.current.delete(conversation.id);
            readBarrierMessageTimeRef.current.set(conversation.id, rowTime(receipt.last_message_at));
            readRowVersionRef.current.set(conversation.id, rowTime(receipt.updated_at));
            return { ...conversation, unread_count: 0, updated_at: receipt.updated_at };
          }));
        } catch {
          // Do not pretend a failed/unconfirmed batch was marked read.
          totals.failed += targets.length - offset;
          break;
        }
      }
      return totals;
    } finally {
      bulkReadInFlightRef.current = false;
      setMarkingAllRead(false);
      window.dispatchEvent(new Event(INBOX_SYNC_EVENT));
    }
  }, [setLiveConversations]);

  async function handleMarkUnread() {
    if (!activeConversation) {
      return;
    }

    const conversationId =
      activeConversation.id;
    if (!beginAction(conversationId, "unread", "Saving")) {
      return;
    }

    /* Keep it unread for the entire time this exact thread stays open. */
    readBarrierMessageTimeRef.current.delete(
      conversationId,
    );
    /* This deliberately supersedes our own read, so retire its row version. */
    readRowVersionRef.current.delete(
      conversationId,
    );
    manualUnreadConversationIdsRef.current.add(
      conversationId,
    );
    persistedManualUnreadCountsRef.current.set(
      conversationId,
      Math.max(
        1,
        activeConversation.unread_count ?? 0,
      ),
    );

    setMarkingUnread(true);
    unreadWriteInFlightRef.current.add(conversationId);

    /* Optimistic UI: show the unread badge immediately. */
    setLiveConversations((current) =>
      current.map((conversation) =>
        conversation.id === conversationId
          ? {
              ...conversation,
              unread_count: Math.max(
                1,
                conversation.unread_count ?? 0,
              ),
            }
          : conversation,
      ),
    );

    try {
      /*
       * If the automatic read from opening this thread is still in flight,
       * wait for exactly that request, not a polling loop. The read route
       * answers after its write, so the unread PATCH is then the later write
       * and a late read can not undo it. No new automatic read starts while
       * the thread is marked unread (markConversationReadRealtime checks it).
       */
      await readPromisesRef.current.get(conversationId);

      const response = await fetch(
        `/api/conversations/${conversationId}/unread`,
        { method: "PATCH" },
      );

      const responseText =
        await response.text();
      const result: {
        success: boolean;
        error?: string;
        conversation?: {
          id: string;
          unread_count: number;
        };
      } = responseText
        ? (JSON.parse(responseText) as {
            success: boolean;
            error?: string;
            conversation?: {
              id: string;
              unread_count: number;
            };
          })
        : { success: response.ok };

      if (!response.ok || !result.success) {
        manualUnreadConversationIdsRef.current.delete(
          conversationId,
        );
        throw new Error(
          result.error ??
            "Unable to mark conversation unread.",
        );
      }

      const authoritativeUnreadCount =
        Math.max(
          1,
          result.conversation?.unread_count ?? 1,
        );

      persistedManualUnreadCountsRef.current.set(
        conversationId,
        authoritativeUnreadCount,
      );

      if (
        manualUnreadConversationIdsRef.current.has(
          conversationId,
        )
      ) {
        setLiveConversations((current) =>
          current.map((conversation) =>
            conversation.id === conversationId
              ? {
                  ...conversation,
                  unread_count: Math.max(
                    authoritativeUnreadCount,
                    conversation.unread_count ?? 0,
                  ),
                }
              : conversation,
          ),
        );
      }
    } catch (error) {
      manualUnreadConversationIdsRef.current.delete(
        conversationId,
      );
      persistedManualUnreadCountsRef.current.delete(
        conversationId,
      );
      console.error(error);
      /* Re-sync only on failure. */
      router.refresh();
    } finally {
      unreadWriteInFlightRef.current.delete(conversationId);
      setMarkingUnread(false);
      endAction(conversationId, "unread");
    }
  }

async function handleTogglePin() {
  if (!activeConversation) {
    return;
  }

  const conversationId = activeConversation.id;
  if (!beginAction(conversationId, "pin", "Saving")) {
    return;
  }
  const activityToken = expectActivity(
    conversationId,
    [activeConversation.is_pinned ? "unpinned" : "pinned"],
  );
  const previousPinState = {
    is_pinned: Boolean(activeConversation.is_pinned),
    pinned_at: activeConversation.pinned_at ?? null,
    pinned_by: activeConversation.pinned_by ?? null,
  };
  const nextPinned = !previousPinState.is_pinned;

  setPinning(true);
  setPinError(null);

  pinOverrideRef.current.set(conversationId, {
    isPinned: nextPinned,
    expiresAt: Date.now() + 15_000,
  });

  setLiveConversations((current) =>
    sortLiveConversations(
      current.map((conversation) =>
        conversation.id === conversationId
          ? {
              ...conversation,
              is_pinned: nextPinned,
              pinned_at: nextPinned
                ? new Date().toISOString()
                : null,
              pinned_by: nextPinned
                ? conversation.pinned_by
                : null,
            }
          : conversation,
      ),
    ),
  );

  try {
    const response = await fetch(
      `/api/conversations/${conversationId}/pin`,
      {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ isPinned: nextPinned }),
      },
    );

    const responseText = await response.text();
    let result: {
      success: boolean;
      error?: string;
      conversation?: {
        id: string;
        is_pinned: boolean;
        pinned_at: string | null;
        pinned_by: string | null;
      };
    };

    if (responseText.trim()) {
      try {
        result = JSON.parse(responseText);
      } catch {
        throw new Error("Pin API returned invalid JSON.");
      }
    } else {
      result = {
        success: response.ok,
        error: response.ok
          ? undefined
          : `Pin API returned an empty response (${response.status}).`,
      };
    }

    if (!response.ok || !result.success) {
      throw new Error(
        result.error ?? "Unable to update conversation pin.",
      );
    }

    if (result.conversation) {
      pinOverrideRef.current.set(conversationId, {
        isPinned: result.conversation.is_pinned,
        expiresAt: Date.now() + 15_000,
      });

      setLiveConversations((current) =>
        sortLiveConversations(
          current.map((conversation) =>
            conversation.id === result.conversation?.id
              ? { ...conversation, ...result.conversation }
              : conversation,
          ),
        ),
      );
    }
    confirmActionSilently(activityToken);
  } catch (error) {
    const localOverride =
      pinOverrideRef.current.get(conversationId);

    if (localOverride?.isPinned === nextPinned) {
      pinOverrideRef.current.delete(conversationId);
      setLiveConversations((current) =>
        sortLiveConversations(
          current.map((conversation) =>
            // Only undo our own write; a teammate's newer pin wins.
            conversation.id === conversationId &&
            Boolean(conversation.is_pinned) === nextPinned
              ? { ...conversation, ...previousPinState }
              : conversation,
          ),
        ),
      );
    }

    const message =
      error instanceof Error
        ? error.message
        : "Unable to update conversation pin.";

    actionLedgerRef.current.cancel(activityToken);
    setPinError(message);
    console.error("Unable to update conversation pin:", error);
  } finally {
    setPinning(false);
    endAction(conversationId, "pin");
  }
}

