function parseTenhLocationMessage(
  message: string,
) {
  const match =
    message
      .trim()
      .match(
        /^📍\s*Location:\s*https:\/\/www\.google\.com\/maps\?q=(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)$/i,
      );

  if (!match) {
    return null;
  }

  const latitude =
    Number(match[1]);
  const longitude =
    Number(match[2]);

  if (
    !Number.isFinite(
      latitude,
    ) ||
    latitude < -90 ||
    latitude > 90 ||
    !Number.isFinite(
      longitude,
    ) ||
    longitude < -180 ||
    longitude > 180
  ) {
    return null;
  }

  return {
    latitude,
    longitude,
  };
}

function isTelegramGifFile(
  file: File,
) {
  const mime =
    file.type
      ?.split(";")[0]
      ?.trim()
      .toLowerCase() ??
