async function resolveConversationPlatform(
  conversation: InboxConversation,
): Promise<InboxConversationPlatform> {
  const loadedPlatform =
    getLoadedConversationPlatform(
      conversation,
    );

  if (loadedPlatform) {
    conversationPlatformCacheRef
      .current[conversation.id] =
      loadedPlatform;

    return loadedPlatform;
  }

  const cached =
    conversationPlatformCacheRef
      .current[conversation.id];

  if (cached) {
    return cached;
  }

  const response =
    await fetch(
      `/api/inbox/conversations/${encodeURIComponent(
        conversation.id,
      )}/channel`,
      {
        method: "GET",
        cache: "no-store",
      },
    );

  const responseText =
    await response.text();

  let result: {
    success?: boolean;
    error?: string;
    platform?:
      | "facebook"
      | "telegram";
  } = {};

  if (responseText.trim()) {
    try {
      result =
        JSON.parse(
          responseText,
        ) as typeof result;
    } catch {
      result = {
        success: false,
        error:
          "The channel API returned invalid JSON.",
      };
    }
  }

  if (
    !response.ok ||
    !result.success ||
    (result.platform !==
      "facebook" &&
      result.platform !==
        "telegram")
  ) {
    throw new Error(
      result.error ??
        "Unable to resolve this conversation channel.",
    );
  }

  conversationPlatformCacheRef
    .current[conversation.id] =
    result.platform;

  return result.platform;
}

async function performOptimisticSend(
  pending:
    PendingOptimisticSend,
): Promise<boolean> {
  setOptimisticSendStatus(
    pending.tempId,
    "sending",
  );

  setSending(true);
  setSendError(null);

  try {
    const response =
      await fetch(
        pending.endpoint,
        {
          method: "POST",
          headers: {
            "Content-Type":
              "application/json",
          },
          body: JSON.stringify(
            pending.requestBody,
          ),
        },
      );

    const responseText =
      await response.text();

    let result: {
      success: boolean;
      error?: string;
      code?: string;
      messageId?: string;
      replyApplied?: boolean;
      replyFallback?: boolean;
      notice?: string | null;
      warning?: string;
    };

    if (
      responseText.trim()
    ) {
      try {
        result =
          JSON.parse(
            responseText,
          ) as {
            success: boolean;
            error?: string;
            code?: string;
            messageId?: string;
          };
      } catch {
        result = {
          success: false,
          error:
            "The send API returned invalid JSON.",
        };
      }
    } else {
      result = {
        success:
          response.ok,
        error:
          response.ok
            ? undefined
            : `The send API returned an empty response (${response.status}).`,
      };
    }

    if (
      !response.ok ||
      !result.success
    ) {
      if (
        result.code ===
          "WAITING_FOR_CUSTOMER_REPLY" ||
        result.code ===
          "MESSENGER_WINDOW_EXPIRED" ||
        result.code ===
          "MESSENGER_POLICY_UNKNOWN" ||
        result.code ===
          "HUMAN_AGENT_APPROVAL_REQUIRED" ||
        result.code === "FACEBOOK_QUOTED_REPLY_REJECTED" ||
        (pending.endpoint === "/api/facebook/send" && Boolean(pending.requestBody.replyToMessageId) && response.status >= 400 && response.status < 500)
      ) {
        setLiveMessages(
          (current) =>
            current.filter(
              (message) =>
                message.id !==
                pending.tempId,
            ),
        );

        delete pendingSendsRef
          .current[pending.tempId];

        setSendError(
          result.error ??
            "Facebook messaging policy does not allow this reply right now.",
        );

        return false;
      }

      throw new Error(
        result.error ??
          "Unable to send the message.",
      );
    }

    if (["/api/telegram/send", "/api/telegram/send-sticker"].includes(pending.endpoint) && result.replyFallback) {
      // Remove the provisional quote: Telegram delivered an ordinary message.
      setLiveMessages(current => current.map(item => {
        if (item.id !== pending.tempId && (!result.messageId || item.platform_message_id !== result.messageId)) return item;
        const raw = { ...(item.raw_payload || {}) };
        delete raw.tenh_reply;
        raw.tenh_reply_fallback = { reason: "original_unavailable", notice: result.notice };
        return { ...item, raw_payload: raw };
      }));
      if (activeConversationRef.current?.id === pending.conversationId) {
        showTelegramActionNotice(result.notice || "Original message unavailable. Sent normally without a quote.");
      }
    }

    setOptimisticSendStatus(
      pending.tempId,
      "sent",
    );

    /*
     * Give the bubble the id the platform assigned it.
     *
     * Until now a sent bubble kept only its temporary id, so the row arriving
     * over Realtime had to be recognised by comparing message text and
     * timestamps -- a guess that fails quietly, and when it fails the same
     * message is drawn twice until a refresh replaces the list.
     *
     * The send response carries the real id, so the two can be matched on it
     * instead. If Realtime wins, the client request ID carried by the echo is
     * the exact match; distinct messages with identical text are never merged.
     */
    if (result.messageId) {
      const platformId = result.messageId;
      setLiveMessages((current) =>
        confirmOutgoingMessage(current, pending.tempId, platformId),
      );
    }
    if (result.warning && activeConversationRef.current?.id === pending.conversationId) setSendError(result.warning);
    return true;
  } catch (error) {
    // A lost or late response after an exactly correlated stored row already
    // confirmed this send (echo, poll or history won the race): the message
    // was delivered, so neither mark it failed nor report a send error.
    if (isOptimisticConfirmedByServer(liveMessagesRef.current, pending.tempId)) {
      delete pendingSendsRef.current[pending.tempId];
      return true;
    }

    const errorMessage =
      error instanceof Error
        ? error.message
        : "Unable to send the message.";

    if (pending.endpoint === "/api/facebook/send" && pending.requestBody.replyToMessageId) {
      // No explicit refusal was received. Keep the quote/draft, but do not
      // offer an uncertain request as a safe Retry operation.
      pending.requiresDeliveryReview = true;
      setLiveMessages(current => current.map(item => item.id === pending.tempId
        ? { ...item, __optimistic_requires_review: true } : item));
    }

    setOptimisticSendStatus(
      pending.tempId,
      "failed",
    );

    if (
      pending
        .isCommentConversation &&
      pending.commentId &&
      isDeletedCommentError(
        errorMessage,
      )
    ) {
      await markCommentDeletedLocally(
        pending.commentId,
      );

      setSendError(
        "Comment is deleted by commenter.",
      );

      return false;
    }

    setSendError(
      pending.requiresDeliveryReview ? `Delivery of this quoted reply is unconfirmed. Check Messenger before sending again. ${errorMessage}` : errorMessage,
    );
    return false;
  } finally {
    setSending(false);
  }
}

async function performOptimisticAttachmentSend(
  pending:
    PendingOptimisticAttachmentSend,
  caption?: string,
): Promise<boolean> {
  setOptimisticSendStatus(
    pending.tempId,
    "sending",
  );

  setSending(true);
  setSendError(null);

  try {
    const formData =
      new FormData();

    formData.set(
      "conversationId",
      pending.conversationId,
    );
    if (
      pending.endpoint ===
      "/api/facebook/send-attachment"
    ) {
      formData.set(
        "recipientId",
        pending.recipientId,
      );
    }

    formData.set(
      "kind",
      pending.kind,
    );
    formData.set(
      "file",
      pending.file,
      pending.file.name,
    );

    for (const file of pending.albumFiles ?? []) {
      formData.append("additionalFiles", file, file.name);
    }
    if (pending.endpoint === "/api/facebook/send-attachment") {
      formData.set("clientRequestId", pending.tempId);
      if (pending.replyToMessageId) formData.set("replyToMessageId", pending.replyToMessageId);
    } else if (pending.endpoint.startsWith("/api/telegram/")) {
      formData.set("clientRequestId", pending.tempId);
    }

    /*
     * A single photo or video takes the caption too, so one image with a
     * message is still one Telegram message rather than two. Ignored by the
     * routes that have nowhere to put it, which is every Messenger path -- Meta
     * has no caption field at all.
     */
    if (caption?.trim()) {
      formData.set(
        "caption",
        caption.trim(),
      );
    }

    const response =
      await fetch(
        pending.endpoint,
        {
          method: "POST",
          body: formData,
        },
      );

    const responseText =
      await response.text();

    let result: {
      success: boolean;
      error?: string;
      code?: string;
      message?: InboxMessage;
    };

    if (responseText.trim()) {
      try {
        result =
          JSON.parse(
            responseText,
          ) as {
            success: boolean;
            error?: string;
            code?: string;
            message?: InboxMessage;
          };
      } catch {
        result = {
          success: false,
          error:
            "The attachment API returned invalid JSON.",
        };
      }
    } else {
      result = {
        success: response.ok,
        error:
          response.ok
            ? undefined
            : `The attachment API returned an empty response (${response.status}).`,
      };
    }

    if (
      !response.ok ||
      !result.success
    ) {
      if (
        result.code ===
          "WAITING_FOR_CUSTOMER_REPLY" ||
        result.code ===
          "MESSENGER_WINDOW_EXPIRED" ||
        result.code ===
          "MESSENGER_POLICY_UNKNOWN" ||
        result.code ===
          "HUMAN_AGENT_APPROVAL_REQUIRED"
      ) {
        setLiveMessages(
          (current) =>
            current.filter(
              (message) =>
                message.id !==
                pending.tempId,
            ),
        );

        delete pendingAttachmentSendsRef
          .current[pending.tempId];

        setSendError(
          result.error ??
            "Facebook messaging policy does not allow this attachment reply right now.",
        );

        return false;
      }

      throw new Error(
        result.error ??
          "Unable to send the attachment.",
      );
    }

    if (result.message) {
      const savedMessage =
        result.message as InboxMessage;
      setLiveMessages((current) =>
        reconcileOptimisticMessage(
          current,
          pending.tempId,
          savedMessage,
          pending.previewUrl,
        ),
      );
    } else {
      setOptimisticSendStatus(
        pending.tempId,
        "sent",
      );
    }

    delete pendingAttachmentSendsRef
      .current[pending.tempId];

    return true;
  } catch (error) {
    const errorMessage =
      error instanceof Error
        ? error.message
        : "Unable to send the attachment.";

    setOptimisticSendStatus(
      pending.tempId,
      "failed",
    );
    setSendError(errorMessage);

    return false;
  } finally {
    setSending(false);
  }
}

/*
 * Swap an optimistic bubble for the row the server actually stored.
 *
 * Realtime can deliver the INSERT for that row before the send request
 * resolves -- almost guaranteed with an album, where six INSERTs land in one
 * burst. Renaming the temporary bubble to the real id would then leave two
 * rows carrying the same id, which React reports as a duplicate key and
 * renders unpredictably. Merge the stored row at the temporary row's position
 * and retain its render key, carrying the local blob preview across so the
 * photo does not blink while the stored URL loads.
 */
function reconcileOptimisticMessage(
  current: InboxMessage[],
  tempId: string,
  savedMessage: InboxMessage,
  previewUrl: string,
): InboxMessage[] {
  const original = current.find(message =>
    message.id === tempId ||
    (message as OptimisticInboxMessage).__render_key === tempId,
  );
  if (!original) return current;
  const reconciled = retainLocalImagePreview(withOptimisticRenderKey({
    ...savedMessage,
    attachment_url: savedMessage.message_type === "image" ? savedMessage.attachment_url || previewUrl : previewUrl,
    __optimistic_status: "sent",
    __optimistic_created_at: Date.now(),
  } as unknown as InboxMessage, original ?? savedMessage), original ?? savedMessage);

  return current.flatMap(message => message === original
    ? [reconciled]
    : message.id === savedMessage.id ? [] : [message]);
}

/*
 * Send several Telegram photos as one album.
 *
 * Sending them one request at a time is why a customer received six separate
 * photos instead of a group: Telegram groups by call, not by timing. One
 * request carrying every file reaches sendMediaGroup, which delivers them as
 * a single album. Each photo still has its own optimistic bubble and its own
 * stored row; only the delivery is grouped.
 */
async function performOptimisticAlbumSend(
  pendings: PendingOptimisticAttachmentSend[],
  caption?: string,
): Promise<boolean> {
  const albumGroupId = pendings[0].albumGroupId ?? crypto.randomUUID();
  const pendingById = new Map(pendings.map((pending, position) => {
    pending.albumGroupId = albumGroupId;
    pending.albumPosition = position;
    return [pending.tempId, pending] as const;
  }));
  setLiveMessages(current => current.map(message => {
    const pending = pendingById.get(message.id);
    return pending
      ? { ...message, raw_payload: {
          ...message.raw_payload,
          tenh_client_request_id: pending.tempId,
          tenh_media_group: { provider: "telegram", id: albumGroupId, position: pending.albumPosition },
        } }
      : message;
  }));
  for (const pending of pendings) {
    setOptimisticSendStatus(
      pending.tempId,
      "sending",
    );
  }

  setSending(true);
  setSendError(null);

  try {
    const formData = new FormData();

    formData.set("clientMediaGroupId", albumGroupId);

    formData.set(
      "conversationId",
      pendings[0].conversationId,
    );
    formData.set("kind", "image");

    /*
     * Telegram shows this as the album's caption, so the agent's message
     * arrives with the media rather than as a second message after it.
     */
    if (caption?.trim()) {
      formData.set(
        "caption",
        caption.trim(),
      );
    }

    for (const pending of pendings) {
      formData.append(
        "files",
        pending.file,
        pending.file.name,
      );
      formData.append("clientRequestIds", pending.tempId);
    }

    const response = await fetch(
      pendings[0].endpoint,
      { method: "POST", body: formData },
    );

    const responseText = await response.text();

    let result: {
      success?: boolean;
      error?: string;
      messages?: InboxMessage[];
    };

    try {
      result = responseText.trim()
        ? (JSON.parse(responseText) as typeof result)
        : { success: response.ok };
    } catch {
      result = {
        success: false,
        error:
          "The attachment API returned invalid JSON.",
      };
    }

    if (!response.ok || !result.success) {
      const errorMessage =
        result.error ??
        "Unable to send the photos.";

      for (const pending of pendings) {
        setOptimisticSendStatus(
          pending.tempId,
          "failed",
        );
      }

      setSendError(errorMessage);
      return false;
    }

    const saved = result.messages ?? [];
    const correlated = correlateTelegramAlbumMessages(
      pendings.map(pending => pending.tempId),
      saved,
    );

    pendings.forEach((pending, index) => {
      const savedMessage = correlated[index];

      if (savedMessage) {
        setLiveMessages((current) =>
          reconcileOptimisticMessage(
            current,
            pending.tempId,
            savedMessage,
            pending.previewUrl,
          ),
        );
      } else {
        setOptimisticSendStatus(
          pending.tempId,
          "sent",
        );
      }

      delete pendingAttachmentSendsRef.current[
        pending.tempId
      ];
    });

    return true;
  } catch (error) {
    const errorMessage =
      error instanceof Error
        ? error.message
        : "Unable to send the photos.";

    for (const pending of pendings) {
      setOptimisticSendStatus(
        pending.tempId,
        "failed",
      );
    }

    setSendError(errorMessage);
    return false;
  } finally {
    setSending(false);
  }
}

/*
 * Telegram Personal: the same reply box as every channel, sent through the
 * holder-only Personal queue. One request id per message (the bubble id), so a
 * message is never sent twice; an unconfirmed send is shown, never retried.
 */
async function sendPersonalItems(items: Array<{ text: string; file?: File | null; kind?: ReplyAttachment["kind"]; previewUrl?: string | null }>): Promise<boolean> {
  const conversation = activeConversationRef.current;
  if (!conversation?.contact) return false;
  const quoteSelection = replyingToFacebookMessageId;
  const quoteTarget = quoteSelection ? resolvePhotoReplyTarget(liveMessagesRef.current, quoteSelection, conversation.id) : null;
  let allSent = true;
  for (const [index, item] of items.entries()) {
    const requestId = crypto.randomUUID();
    const tempId = `optimistic:${requestId}`;
    const label = item.file ? (item.text || (item.kind === "image" ? "Photo" : item.kind === "video" ? "Video" : item.kind === "audio" ? "Voice message" : item.file.name)) : item.text;
    const optimistic = createOptimisticMessage({ tempId, conversationId: conversation.id, message: label,
      recipientPlatformId: conversation.contact.platform_user_id, commentReplyParentId: null });
    if (item.file) {
      optimistic.message_type = item.kind === "image" ? "image" : item.kind === "video" ? "video" : item.kind === "audio" ? "audio" : "file";
      optimistic.attachment_url = item.previewUrl ?? null;
    }
    const quote = index === 0 && quoteTarget ? quoteTarget : null;
    optimistic.raw_payload = { ...(optimistic.raw_payload || {}), tenh_client_request_id: requestId,
      ...(quote ? { tenh_reply: createReplyContext(quote, "telegram") } : {}) };
    setLiveMessages((current) => [...current, optimistic]);
    updateConversationPreviewOptimistically({ conversationId: conversation.id, message: item.file ? `You sent ${label}` : label, createdAt: optimistic.created_at });
    if (index === 0) setReplyingToFacebookMessageId(null);
    setSendError(null);
    const outcome = await sendPersonalMessage({
      conversationId: conversation.id, requestId, text: item.text, file: item.file ?? null,
      replyToMessageId: quote ? quote.id : null,
      isAlive: () => true,
    });
    if (outcome.state === "sent") {
      setOptimisticSendStatus(tempId, "sent");
      continue;
    }
    allSent = false;
    if (outcome.state === "refused") {
      // Nothing was queued: remove the bubble; the caller keeps the text.
      setLiveMessages((current) => current.filter((message) => message.id !== tempId));
    } else {
      setOptimisticSendStatus(tempId, "failed");
    }
    if (activeConversationRef.current?.id === conversation.id) setSendError(outcome.error);
    if (outcome.state === "refused") break;
  }
  return allSent;
}

/* Telegram's caption limit, in the UTF-16 units JavaScript counts. */
const TELEGRAM_CAPTION_LIMIT = 1024;

async function handleSendAttachments(
  attachments: ReplyAttachment[],
  text?: string,
  options?: { onQueued?: () => void },
): Promise<boolean> {
  const submissionOwner = captureComposerSubmissionOwner();
  if (!submissionOwner) return false;
  if (activeConversationRef.current?.social_account?.platform === "telegram_personal") {
    const personalText = text?.trim() ?? "";
    // A caption holds 1024 characters; longer text follows as its own item
    // rather than being cut.
    const personalCaption = personalText.length <= TELEGRAM_CAPTION_LIMIT ? personalText : "";
    return sendPersonalItems([
      ...attachments.map((attachment, index) => ({
        text: index === 0 ? personalCaption : "",
        file: attachment.file,
        kind: attachment.kind,
        previewUrl: attachment.previewUrl,
      })),
      ...(personalText && !personalCaption ? [{ text: personalText }] : []),
    ]);
  }
  if (editingTelegramMessageId) {
    setSendError(
      "Finish or cancel Telegram editing before sending an attachment.",
    );
    return false;
  }

  if (
    replyingToTelegramMessageId &&
    activeConversation
  ) {
    let replyPlatform:
      InboxConversationPlatform;

    try {
      replyPlatform =
        await resolveConversationPlatform(
          activeConversation,
        );
    } catch (error) {
      if (!isComposerSubmissionCurrent(submissionOwner)) return false;
      setSendError(
        error instanceof Error
          ? error.message
          : "Unable to resolve this conversation channel.",
      );
      return false;
    }

    if (!isComposerSubmissionCurrent(submissionOwner)) return false;
    if (replyPlatform === "telegram") {
      setSendError(
        "Telegram Reply supports text only. Cancel Reply before sending media.",
      );
      return false;
    }
  }

  if (
    !activeConversation ||
    !activeConversation.contact
  ) {
    return false;
  }

  if (replyingToCommentId) {
    setSendError(
      "Cancel the Facebook comment Reply target before sending an attachment.",
    );
    return false;
  }

  let conversationPlatform:
    InboxConversationPlatform;

  try {
    conversationPlatform =
      await resolveConversationPlatform(
        activeConversation,
      );
  } catch (error) {
    if (!isComposerSubmissionCurrent(submissionOwner)) return false;
    setSendError(
      error instanceof Error
        ? error.message
        : "Unable to resolve this conversation channel.",
    );
    return false;
  }

  if (!isComposerSubmissionCurrent(submissionOwner)) return false;
  if (
    conversationPlatform ===
    "telegram"
  ) {
    const unsupportedVideo =
      attachments.find(
        (attachment) => {
          if (
            attachment.kind !==
            "video"
          ) {
            return false;
          }

          const fileType =
            attachment.file.type
              ?.split(";")[0]
              ?.trim()
              .toLowerCase() ??
            "";
          const lowerName =
            attachment.file.name
              .toLowerCase();

          return !(
            fileType ===
              "video/mp4" ||
            lowerName.endsWith(
              ".mp4",
            )
          );
        },
      );

    if (unsupportedVideo) {
      setSendError(
        "TENH Telegram video currently supports MP4 video only. Please choose an .mp4 file.",
      );
      return false;
    }

    const tooLarge =
      attachments.find(
        (attachment) =>
          attachment.file.size >
          4 * 1024 * 1024,
      );

    if (tooLarge) {
      setSendError(
        "For reliable Vercel delivery, TENH Telegram media uploads are currently limited to 4 MB each.",
      );
      return false;
    }
  }

  if (conversationPlatform === "facebook") {
    try {
      attachments = await Promise.all(attachments.map(async (attachment) =>
        attachment.kind === "audio"
          ? { ...attachment, file: await prepareFacebookVoice(attachment.file) }
          : attachment,
      ));
    } catch (error) {
      setSendError(error instanceof Error ? error.message : "Unable to prepare voice recording.");
      return false;
    }
  }

  const facebookReplyTarget = conversationPlatform === "facebook" && replyingToFacebookMessageId
    ? resolvePhotoReplyTarget(liveMessagesRef.current, replyingToFacebookMessageId, activeConversation.id) : null;
  if (conversationPlatform === "facebook" && replyingToFacebookMessageId && (!facebookReplyTarget || !getMessageActions(facebookReplyTarget, "facebook").reply)) {
    setSendError("The selected message is no longer available. Cancel Reply and try again."); return false;
  }
  let allSucceeded = true;
  const albumPendings: PendingOptimisticAttachmentSend[] = [];

  /*
   * Where the typed text goes. Telegram carries it as the caption of the first
   * photo or MP4 -- a single photo too, which used to drop it -- when it fits
   * the 1024-character caption limit. Anything else (Messenger, documents,
   * audio, or longer text) follows as its own message after the media, so the
   * text is never lost.
   */
  const trimmedText = text?.trim() ?? "";
  const isTelegramAlbumCandidate = (attachment: ReplyAttachment) =>
    conversationPlatform === "telegram" &&
    ((attachment.kind === "image" && !isTelegramGifFile(attachment.file)) ||
      (attachment.kind === "video" &&
        attachment.file.type.split(";")[0].trim().toLowerCase() === "video/mp4"));
  const telegramCaption =
    trimmedText &&
    trimmedText.length <= TELEGRAM_CAPTION_LIMIT &&
    attachments.some(isTelegramAlbumCandidate)
      ? trimmedText
      : undefined;
  const followUpText = trimmedText && !telegramCaption ? trimmedText : "";
  let captionBubbleAssigned = false;
  const queuedSends: PendingOptimisticAttachmentSend[] = [];

  const groupedPhotoIds = new Set<string>();
  const facebookPhotos = conversationPlatform === "facebook"
    ? attachments.filter((item) => item.kind === "image") : [];

  for (const attachment of attachments) {
    if (groupedPhotoIds.has(attachment.id)) continue;
    const photoIndex = facebookPhotos.indexOf(attachment);
    const photoBatch = photoIndex >= 0 ? facebookPhotos.slice(photoIndex, photoIndex + 30) : [];
    for (const photo of photoBatch.slice(1)) groupedPhotoIds.add(photo.id);

    const randomId =
      typeof crypto !==
        "undefined" &&
      typeof crypto.randomUUID ===
        "function"
        ? crypto.randomUUID()
        : `${Date.now()}-${Math.random()}`;

    const tempId =
      `optimistic:attachment:${randomId}`;

    const previewUrl =
      URL.createObjectURL(
        attachment.file,
      );

    const optimisticKind =
      conversationPlatform === "telegram"
        ? telegramOptimisticAttachmentKind({
            file: attachment.file,
            requestedKind: attachment.kind,
          })
        : attachment.kind;

    const messageText =
      conversationPlatform ===
          "telegram" &&
        isTelegramGifFile(
          attachment.file,
        )
        ? "Sent an animation"
        : getAttachmentMessageText(
            optimisticKind,
            attachment.file.name,
          );

    /*
     * Telegram groups photos and MP4 video into one album, so both go to
     * send-photo, which batches them. A GIF is sent as an animation and a
     * document as a document -- Telegram groups neither with photos, so they
     * keep their own path.
     */
    const isAlbumCandidate =
      isTelegramAlbumCandidate(attachment);

    /* The bubble that will carry the caption shows it from the start. */
    const carriesCaption =
      isAlbumCandidate &&
      Boolean(telegramCaption) &&
      !captionBubbleAssigned;

    if (carriesCaption) captionBubbleAssigned = true;

    const attachmentEndpoint =
      conversationPlatform ===
        "telegram"
        ? isAlbumCandidate
          ? "/api/telegram/send-photo"
          : "/api/telegram/send-media"
        : "/api/facebook/send-attachment";

    const pending:
      PendingOptimisticAttachmentSend = {
        tempId,
        conversationId:
          activeConversation.id,
        recipientId:
          activeConversation.contact
            .platform_user_id,
        file: attachment.file,
        kind: optimisticKind,
        previewUrl,
        messageText,
        endpoint:
          attachmentEndpoint,
        ...(facebookReplyTarget ? { replyToMessageId: facebookReplyTarget.id } : {}),
      };

    if (photoBatch.length > 1) {
      pending.albumFiles = photoBatch.slice(1).map((item) => item.file);
      pending.albumPreviewUrls = [previewUrl, ...pending.albumFiles.map((file) => URL.createObjectURL(file))];
    }

    pendingAttachmentSendsRef
      .current[tempId] =
      pending;

    const optimisticMessage =
      createOptimisticAttachmentMessage({
        tempId,
        conversationId:
          activeConversation.id,
        recipientPlatformId:
          activeConversation.contact
            .platform_user_id,
        kind: optimisticKind,
        file: attachment.file,
        previewUrl,
        messageText:
          carriesCaption && telegramCaption
            ? telegramCaption
            : messageText,
      });

    if (facebookReplyTarget) {
      optimisticMessage.raw_payload = { ...(optimisticMessage.raw_payload || {}),
        reply_to: { mid: facebookReplyTarget.platform_message_id }, tenh_reply: createReplyContext(facebookReplyTarget, "facebook") };
    }
    if (pending.albumPreviewUrls) {
      optimisticMessage.raw_payload = {
        ...(optimisticMessage.raw_payload as Record<string, unknown>),
        message: { attachments: pending.albumPreviewUrls.map((url) => ({ type: "image", payload: { url } })) },
      };
    }

    setLiveMessages(
      (current) => [
        ...current,
        optimisticMessage,
      ],
    );

    updateConversationPreviewOptimistically({
      conversationId:
        activeConversation.id,
      message:
        messageText,
      createdAt:
        optimisticMessage.created_at,
    });

    /*
     * Telegram photos are held back and sent together below, so they reach
     * sendMediaGroup as one album. Everything else goes immediately.
     */
    if (
      pending.endpoint ===
      "/api/telegram/send-photo"
    ) {
      albumPendings.push(pending);
      continue;
    }

    queuedSends.push(pending);
  }

  /*
   * Every outgoing item is on screen as "Sending" before anything uploads.
   * From here each bubble owns its own success, failure and Retry, so the
   * composer must not be refilled with them -- that was a second copy.
   */
  options?.onQueued?.();

  const attachmentsDone = (async () => {
  for (const pending of queuedSends) {
    if (!(await performOptimisticAttachmentSend(pending))) {
      allSucceeded = false;
    }
  }

  if (albumPendings.length === 1) {
    /* A single photo needs no album; sendPhoto is the simpler path. */
    const succeeded =
      await performOptimisticAttachmentSend(
        albumPendings[0],
        telegramCaption,
      );

    if (!succeeded) {
      allSucceeded = false;
    }
  } else if (albumPendings.length > 1) {
    /* Telegram albums hold ten items, so send in chunks of ten. */
    for (
      let index = 0;
      index < albumPendings.length;
      index += 10
    ) {
      const chunk = albumPendings.slice(
        index,
        index + 10,
      );

      /*
       * The caption rides on the first batch only. Repeating it under every
       * chunk of a very large album would read as the agent saying the same
       * thing several times.
       */
      const succeeded =
        chunk.length === 1
          ? await performOptimisticAttachmentSend(
              chunk[0],
              index === 0
                ? telegramCaption
                : undefined,
            )
          : await performOptimisticAlbumSend(
              chunk,
              index === 0
                ? telegramCaption
                : undefined,
            );

      if (!succeeded) {
        allSucceeded = false;
      }
    }
  }

  })();

  /*
   * The text's bubble appears now, after the media bubbles; its request waits
   * for the media so the customer receives them in the same order. It is sent
   * whether or not the media succeeded -- each item stands on its own. A Reply
   * quote is carried by the media, as before, not repeated on the text.
   */
  const textDone = followUpText
    ? handleSendMessage(
        { preventDefault() {} } as unknown as FormEvent,
        followUpText,
        { startAfter: attachmentsDone, withoutReply: true },
      )
    : Promise.resolve();

  await attachmentsDone;
  await textDone;

  if (allSucceeded && facebookReplyTarget && isComposerSubmissionCurrent(submissionOwner)) {
    setReplyingToFacebookMessageId(current => current === facebookReplyTarget.id ? null : current);
  }
  return allSucceeded;
}

async function handleRetryOptimisticMessage(
  tempId: string,
) {
  const attachmentPending =
    pendingAttachmentSendsRef
      .current[tempId];

  if (attachmentPending) {
    await performOptimisticAttachmentSend(
      attachmentPending,
    );
    return;
  }

  const pending =
    pendingSendsRef
      .current[
        tempId
      ];

  if (!pending) {
    return;
  }

  if (pending.requiresDeliveryReview) {
    setSendError("Delivery of this quoted reply is unconfirmed. Check Messenger before sending again.");
    return;
  }

  await performOptimisticSend(
    pending,
  );
}

async function handleSendMessage(
  event: FormEvent,
  capturedMessage?: string,
  options?: { startAfter?: Promise<unknown>; withoutReply?: boolean },
) {
  event.preventDefault();

  const submissionOwner = captureComposerSubmissionOwner();
  if (!submissionOwner) return;

  const message =
    (capturedMessage ?? reply).trim();

  /* Text sent after attachments leaves the Reply quote to the attachments. */
  const facebookReplyId = options?.withoutReply ? null : replyingToFacebookMessageId;
  const telegramReplyId = options?.withoutReply ? null : replyingToTelegramMessageId;

  if (
    !message ||
    !activeConversation ||
    !activeConversation.contact
  ) {
    return;
  }

  if (activeConversation.social_account?.platform === "telegram_personal" && !editingTelegramMessageId) {
    if (capturedMessage === undefined) setReply(current => current === reply ? "" : current);
    const sent = await sendPersonalItems([{ text: message }]);
    if (!sent && capturedMessage === undefined && isComposerSubmissionCurrent(submissionOwner) && !composerDraftRef.current.reply) {
      setReply(message);
    }
    return;
  }

  /*
   * V3.11.30.1 — a conversation can contain both normal Messenger DMs and
   * Facebook comments. Only an explicitly selected comment Reply target uses
   * the public comment reply endpoint. Otherwise the composer sends a normal
   * channel message.
   */
  const isCommentReply =
    Boolean(replyingToCommentId);

  if (replyingToCommentId && isCommentReplyBlocked(replyingToCommentId, liveMessages)) {
    setSendError("Unhide this comment and its parent before replying.");
    return;
  }

  const commentId =
    replyingToCommentId;

  let conversationPlatform:
    InboxConversationPlatform =
      "facebook";

  if (!isCommentReply) {
    try {
      conversationPlatform =
        await resolveConversationPlatform(
          activeConversation,
        );
    } catch (error) {
      if (!isComposerSubmissionCurrent(submissionOwner)) return;
      setSendError(
        error instanceof Error
          ? error.message
          : "Unable to resolve this conversation channel.",
      );
      return;
    }
  }

  if (!isComposerSubmissionCurrent(submissionOwner)) return;
  const selectedReplyId = conversationPlatform === "telegram" ? telegramReplyId : facebookReplyId;
  if (selectedReplyId && !isCommentReply) {
    const selectedReply = resolvePhotoReplyTarget(liveMessagesRef.current, selectedReplyId, activeConversation.id);
    if (!selectedReply || !getMessageActions(selectedReply, conversationPlatform).reply) {
      setSendError("The selected message is no longer available. Cancel Reply and try again.");
      return;
    }
  }

  if (
    conversationPlatform ===
      "telegram" &&
    editingTelegramMessageId
  ) {
    setSending(true);
    setSendError(null);

    try {
      const response =
        await fetch(
          `/api/telegram/messages/${encodeURIComponent(
            editingTelegramMessageId,
          )}`,
          {
            method: "PATCH",
            headers: {
              "Content-Type":
                "application/json",
            },
            body: JSON.stringify({
              text: message,
            }),
          },
        );

      const responseText =
        await response.text();

      const result =
        responseText.trim()
          ? (
              JSON.parse(
                responseText,
              ) as {
                success?: boolean;
                error?: string;
                messageText?: string;
                editedAt?: string;
              }
            )
          : {};

      if (
        !response.ok ||
        !result.success
      ) {
        throw new Error(
          result.error ??
            "Unable to edit Telegram message.",
        );
      }

      const editedMessageId =
        editingTelegramMessageId;

      setLiveMessages(
        (current) =>
          current.map(
            (liveMessage) =>
              liveMessage.id ===
              editedMessageId
                ? {
                    ...liveMessage,
                    message_text:
                      result.messageText ??
                      message,
                    raw_payload: {
                      ...(
                        liveMessage.raw_payload ??
                        {}
                      ),
                      tenh_edit: {
                        source: "tenh",
                        edited_at:
                          result.editedAt ??
                          new Date().toISOString(),
                      },
                    },
                  }
                : liveMessage,
          ),
      );

      setLiveConversations(
        (current) =>
          current.map(
            (conversation) =>
              conversation.id ===
              activeConversation.id
                ? {
                    ...conversation,
                    ...(
                      conversation.last_message_text ===
                      liveMessages.find(
                        (liveMessage) =>
                          liveMessage.id ===
                          editedMessageId,
                      )?.message_text
                        ? {
                            last_message_text:
                              result.messageText ??
                              message,
                          }
                        : {}
                    ),
                  }
                : conversation,
          ),
      );

      if (isComposerSubmissionCurrent(submissionOwner)) {
        setReply((current) => current === message ? "" : current);
        setEditingTelegramMessageId((current) => current === editedMessageId ? null : current);
        showTelegramActionNotice("Telegram message edited successfully");
      }
    } catch (error) {
      if (isComposerSubmissionCurrent(submissionOwner)) setSendError(
        error instanceof Error
          ? error.message
          : "Unable to edit Telegram message.",
      );
    } finally {
      setSending(false);
    }

    return;
  }

  const randomId =
    typeof crypto !==
      "undefined" &&
    typeof crypto.randomUUID ===
      "function"
      ? crypto.randomUUID()
      : `${Date.now()}-${Math.random()}`;

  const tempId =
    `optimistic:${randomId}`;

  const telegramLocation =
    !isCommentReply &&
    conversationPlatform ===
      "telegram"
      ? parseTenhLocationMessage(
          message,
        )
      : null;

  if (
    conversationPlatform === "telegram" &&
    telegramReplyId &&
    telegramLocation
  ) {
    setSendError(
      "Telegram Reply supports text only. Cancel Reply before sending a location.",
    );
    return;
  }

  const endpoint =
    isCommentReply
      ? "/api/facebook/comments/reply"
      : conversationPlatform ===
          "telegram"
        ? telegramLocation
          ? "/api/telegram/send-location"
          : "/api/telegram/send"
        : "/api/facebook/send";

  const requestBody:
    Record<string, unknown> =
    isCommentReply
      ? {
          conversationId:
            activeConversation.id,
          commentId,
          message,
        }
      : conversationPlatform ===
          "telegram"
        ? telegramLocation
          ? {
              conversationId:
                activeConversation.id,
              latitude:
                telegramLocation.latitude,
              longitude:
                telegramLocation.longitude,
              message,
            }
          : {
              conversationId:
                activeConversation.id,
              message,
              ...(telegramReplyId
                ? {
                    replyToMessageId:
                      telegramReplyId,
                  }
                : {}),
            }
        : {
            conversationId:
              activeConversation.id,
            recipientId:
              activeConversation
                .contact
                .platform_user_id,
            message,
            clientRequestId: tempId,
            ...(facebookReplyId ? { replyToMessageId: facebookReplyId } : {}),
          };

  const pending:
    PendingOptimisticSend = {
      tempId,
      conversationId:
        activeConversation.id,
      message,
      endpoint,
      requestBody,
      isCommentConversation:
        isCommentReply,
      commentId,
    };

  const submissionKey = JSON.stringify([pending.conversationId, endpoint, message, commentId, selectedReplyId]);
  if (textSubmissionsRef.current.has(submissionKey)) return;
  textSubmissionsRef.current.add(submissionKey);
  const submission = ++latestTextSubmissionRef.current;

  pendingSendsRef.current[
    tempId
  ] = pending;

  const optimisticMessage =
    createOptimisticMessage({
      tempId,
      conversationId:
        activeConversation.id,
      message,
      recipientPlatformId:
        activeConversation
          .contact
          .platform_user_id,
      commentReplyParentId:
        isCommentReply
          ? commentId
          : null,
    });

  const replyTarget = resolvePhotoReplyTarget(liveMessagesRef.current,
    conversationPlatform === "telegram" ? telegramReplyId : facebookReplyId, activeConversation.id);
  if (replyTarget && !isCommentReply) {
    optimisticMessage.raw_payload = { ...(optimisticMessage.raw_payload ?? {}),
      ...(conversationPlatform === "facebook" ? { reply_to: { mid: replyTarget.platform_message_id } } : {}),
      tenh_reply: createReplyContext(replyTarget, conversationPlatform === "telegram" ? "telegram" : "facebook") };
  }

  setLiveMessages(
    (current) => [
      ...current,
      optimisticMessage,
    ],
  );

  updateConversationPreviewOptimistically({
    conversationId:
      activeConversation.id,
    message,
    createdAt:
      optimisticMessage
        .created_at,
  });

  const recoverFacebookQuote = !isCommentReply && conversationPlatform === "facebook" && Boolean(selectedReplyId);
  if (capturedMessage === undefined) setReply(current => current === reply ? "" : current);
  setReplyingToFacebookMessageId(current => current === selectedReplyId ? null : current);
  const clearedRevision = composerDraftRef.current.revision;
  setReplyingToCommentId(
    null,
  );
  setReplyingToTelegramMessageId(
    null,
  );
  setEditingTelegramMessageId(
    null,
  );
  setSendError(null);

  let sent: boolean;
  // Shown as "Sending" already; wait for the items queued before it.
  if (options?.startAfter) await options.startAfter.catch(() => undefined);
  try { sent = await performOptimisticSend(pending); }
  finally { textSubmissionsRef.current.delete(submissionKey); }
  if (!sent && recoverFacebookQuote) {
    const current = composerDraftRef.current;
    const canRestore = capturedMessage === undefined && isComposerSubmissionCurrent(submissionOwner) &&
      submission === latestTextSubmissionRef.current && current.revision === clearedRevision && !current.reply && !current.quote;
    if (canRestore) {
      setReply(reply);
      setReplyingToFacebookMessageId(selectedReplyId);
    } else if (!pendingSendsRef.current[pending.tempId]) {
      // Explicit rejection removed the optimistic copy. If recovery would
      // replace newer work, keep the rejected request in its original thread.
      pendingSendsRef.current[pending.tempId] = pending;
      if (desiredConversationIdRef.current === activeConversation.id) setLiveMessages(current =>
        current.some(item => item.id === pending.tempId) ? current : [...current, { ...optimisticMessage, __optimistic_status: "failed" }]);
    }
    if (desiredConversationIdRef.current !== activeConversation.id) {
      const cached = conversationMessageCacheRef.current[activeConversation.id];
      if (cached) {
        const failed = { ...optimisticMessage, __optimistic_status: "failed" as const,
          ...(pending.requiresDeliveryReview ? { __optimistic_requires_review: true } : {}) };
        setCachedConversationPage(activeConversation.id, { ...cached,
          messages: cached.messages.some(item => item.id === pending.tempId)
            ? cached.messages.map(item => item.id === pending.tempId ? failed : item) : [...cached.messages, failed] });
      }
    }
  }
}

  async function handleSendSticker(sticker: InboxStickerChoice): Promise<boolean> {
    if (!captureComposerSubmissionOwner()) return false;
    const conversation = activeConversationRef.current;
    if (isMetaSticker(sticker)) {
      if (!conversation?.contact || conversation.social_account?.platform !== "facebook") throw new Error("Open a Facebook conversation before sending this sticker.");
      const target = resolvePhotoReplyTarget(liveMessagesRef.current, replyingToFacebookMessageId, conversation.id);
      if (replyingToFacebookMessageId && (!target || !getMessageActions(target, "facebook").reply)) throw new Error("The selected message is no longer available. Cancel Reply and try again.");
      const requestId = crypto.randomUUID(), tempId = `optimistic:sticker:${requestId}`;
      const pending: PendingOptimisticSend = { tempId, conversationId: conversation.id, message: "Sent a sticker",
        endpoint: "/api/facebook/stickers/send", requestBody: { conversationId: conversation.id, requestId, stickerId: sticker.stickerId, previewUrl: sticker.previewUrl, label: sticker.label, ...(target ? { replyToMessageId: target.id } : {}) },
        isCommentConversation: false, commentId: null };
      const optimistic = createOptimisticMessage({ tempId, conversationId: conversation.id, message: "Sent a sticker",
        recipientPlatformId: conversation.contact.platform_user_id, commentReplyParentId: null });
      optimistic.message_type = "sticker"; optimistic.attachment_url = sticker.previewUrl;
      optimistic.raw_payload = { ...(optimistic.raw_payload || {}), tenh_client_request_id: tempId,
        tenh_meta_sticker: { sticker_id: sticker.stickerId, native: true, pack_id: sticker.packId } };
      if (target) optimistic.raw_payload = { ...optimistic.raw_payload, reply_to: { mid: target.platform_message_id }, tenh_reply: createReplyContext(target, "facebook") };
      pendingSendsRef.current[tempId] = pending;
      setLiveMessages(current => [...current, optimistic]);
      updateConversationPreviewOptimistically({ conversationId: conversation.id, message: "You sent a sticker", createdAt: optimistic.created_at });
      setSendError(null);
      const ok = await performOptimisticSend(pending);
      if (ok && target && activeConversationRef.current?.id === conversation.id) setReplyingToFacebookMessageId(current => current === target.id ? null : current);
      return ok;
    }
    if (!conversation?.contact || conversation.social_account?.platform !== "telegram" || editingTelegramMessageId) {
      setSendError("Open a Telegram conversation and finish editing before sending a sticker."); throw new Error("Sticker sending unavailable.");
    }
    const tempId = `optimistic:${crypto.randomUUID()}`;
    const message = `Sticker ${sticker.emoji || ""}`.trim();
    const pending: PendingOptimisticSend = {
      tempId, conversationId: conversation.id, message, endpoint: "/api/telegram/send-sticker",
      requestBody: { conversationId: conversation.id, setName: sticker.setName, stickerId: sticker.stickerId,
        ...(replyingToTelegramMessageId ? { replyToMessageId: replyingToTelegramMessageId } : {}) },
      isCommentConversation: false, commentId: null,
    };
    const optimistic = createOptimisticMessage({ tempId, conversationId: conversation.id, message,
      recipientPlatformId: conversation.contact.platform_user_id, commentReplyParentId: null });
    optimistic.message_type = "sticker"; optimistic.attachment_url = sticker.previewUrl;
    optimistic.raw_payload = { ...(optimistic.raw_payload || {}), tenh_sticker: {
      format: sticker.format, preview_kind: sticker.previewUrl ? "image" : "file", emoji: sticker.emoji, set_name: sticker.setName,
    }};
    const target = liveMessagesRef.current.find(item => item.conversation_id === conversation.id && item.id === replyingToTelegramMessageId);
    if (target) optimistic.raw_payload.tenh_reply = createReplyContext(target, "telegram");
    pendingSendsRef.current[tempId] = pending;
    setLiveMessages(current => [...current, optimistic]);
    updateConversationPreviewOptimistically({ conversationId: conversation.id, message: "You sent a sticker", createdAt: optimistic.created_at });
    setReplyingToTelegramMessageId(null); setSendError(null);
    return performOptimisticSend(pending);
  }

  async function handleStatusChange(
    nextStatus: ConversationStatus,
  ) {
    if (
      !activeConversation ||
      nextStatus === activeConversation.status
    ) {
      return false;
    }

    const conversationId = activeConversation.id;
    const previousStatus = activeConversation.status;
    if (!beginAction(conversationId, "status", "Saving")) {
      return false;
    }
    const activityToken = expectActivity(conversationId, ["status_changed"]);

    statusOverrideRef.current.set(conversationId, {
      status: nextStatus,
      expiresAt: Date.now() + 8_000,
    });

    setUpdatingStatus(true);
    setStatusError(null);

    setLiveConversations((current) =>
      sortLiveConversations(
        current.map((conversation) =>
          conversation.id === conversationId
            ? {
                ...conversation,
                status: nextStatus,
              }
            : conversation,
        ),
      ),
    );

    try {
      const response = await fetch(
        `/api/conversations/${conversationId}/status`,
        {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            status: nextStatus,
          }),
        },
      );

      const result =
        (await response.json()) as {
          success?: boolean;
          error?: string;
          conversation?: {
            id: string;
            status: ConversationStatus;
          };
          activityRecorded?: boolean;
        };

      if (!response.ok || !result.success || !result.conversation) {
        throw new Error(
          result.error ??
            "Unable to update status.",
        );
      }

      const authoritativeStatus =
        result.conversation.status;

      statusOverrideRef.current.set(conversationId, {
        status: authoritativeStatus,
        expiresAt: Date.now() + 3_000,
      });

      setLiveConversations((current) =>
        sortLiveConversations(
          current.map((conversation) =>
            conversation.id === conversationId
              ? {
                  ...conversation,
                  status: authoritativeStatus,
                }
              : conversation,
          ),
        ),
      );
      // Status had no local confirmation; it relied on the Realtime echo.
      confirmActionSilently(activityToken);
      return true;
    } catch (error) {
      actionLedgerRef.current.cancel(activityToken);
      const currentOverride =
        statusOverrideRef.current.get(conversationId);

      if (currentOverride?.status === nextStatus) {
        statusOverrideRef.current.delete(conversationId);

        setLiveConversations((current) =>
          sortLiveConversations(
            current.map((conversation) =>
              conversation.id === conversationId &&
              conversation.status === nextStatus
                ? {
                    ...conversation,
                    status: previousStatus,
                  }
                : conversation,
            ),
          ),
        );
      }

      setStatusError(
        error instanceof Error
          ? error.message
          : "Unable to update status.",
      );
      return false;
    } finally {
      setUpdatingStatus(false);
      endAction(conversationId, "status");
    }
  }

async function handleAssignmentChange(
  assignedTo: string,
) {
  if (!activeConversation) {
    return;
  }

  const conversationId = activeConversation.id;
  const nextAssignedTo =
    assignedTo === "unassigned"
      ? null
      : assignedTo;

  if (
    nextAssignedTo ===
    activeConversation.assigned_to
  ) {
    return;
  }

  const previousAssignment = {
    assigned_to: activeConversation.assigned_to,
    assigned_at: activeConversation.assigned_at,
    assigned_member: activeConversation.assigned_member,
  };

  const optimisticMember = nextAssignedTo
    ? teamMembers.find((member) => member.id === nextAssignedTo) ?? null
    : null;

  // One assignment write per conversation at a time; Assign to me shares it.
  if (!beginAction(conversationId, "assign", "Assigning")) {
    return;
  }
  const activityToken = expectActivity(conversationId, [nextAssignedTo ? "assigned" : "unassigned"]);

  assignmentOverrideRef.current.set(conversationId, {
    assignedTo: nextAssignedTo,
    expiresAt: Date.now() + 8_000,
  });

  setAssigning(true);
  setAssignmentError(null);

  setLiveConversations((current) =>
    sortLiveConversations(
      current.map((conversation) =>
        conversation.id === conversationId
          ? {
              ...conversation,
              assigned_to: nextAssignedTo,
              assigned_at: nextAssignedTo
                ? new Date().toISOString()
                : null,
              assigned_member: optimisticMember,
            }
          : conversation,
      ),
    ),
  );

  try {
    const response = await fetch(
      `/api/conversations/${conversationId}/assignment`,
      {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          assignedTo: nextAssignedTo,
        }),
      },
    );

    const result =
      (await response.json()) as {
        success?: boolean;
        error?: string;
        conversation?: {
          id: string;
          assigned_to: string | null;
          assigned_at: string | null;
        };
      };

    if (!response.ok || !result.success) {
      throw new Error(
        result.error ??
          "Unable to assign the conversation.",
      );
    }

    if (result.conversation) {
      const authoritativeMember =
        result.conversation.assigned_to
          ? teamMembers.find(
              (member) =>
                member.id === result.conversation?.assigned_to,
            ) ?? null
          : null;

      assignmentOverrideRef.current.set(conversationId, {
        assignedTo: result.conversation.assigned_to,
        expiresAt: Date.now() + 3_000,
      });

      setLiveConversations((current) =>
        sortLiveConversations(
          current.map((conversation) =>
            conversation.id === result.conversation?.id
              ? {
                  ...conversation,
                  ...result.conversation,
                  assigned_member: authoritativeMember,
                }
              : conversation,
          ),
        ),
      );
    }
    confirmActionSilently(activityToken);
  } catch (error) {
    actionLedgerRef.current.cancel(activityToken);
    assignmentOverrideRef.current.delete(conversationId);

    setLiveConversations((current) =>
      sortLiveConversations(
        current.map((conversation) =>
          // Only undo our own write; a teammate's newer assignment wins.
          conversation.id === conversationId &&
          (conversation.assigned_to ?? null) === nextAssignedTo
            ? {
                ...conversation,
                ...previousAssignment,
              }
            : conversation,
        ),
      ),
    );

    setAssignmentError(
      error instanceof Error
        ? error.message
        : "Unable to assign the conversation.",
    );
  } finally {
    setAssigning(false);
    endAction(conversationId, "assign");
  }
}

async function handleAssignToMe() {
  if (!activeConversation) {
    return;
  }

  if (activeConversation.assigned_to) {
    return;
  }

  const conversationId = activeConversation.id;

  /*
   * Pending shows at once ("Assigning to you"), but the assignee does not:
   * the claim is atomic on the server and may lose to a teammate, so the
   * name appears only once the server says it is ours.
   */
  if (!beginAction(conversationId, "assign", "Assigning to you")) {
    return;
  }
  const activityToken = expectActivity(conversationId, ["assigned"]);

  setAssigning(true);
  setAssignmentError(null);

  try {
    const response = await fetch(
      `/api/conversations/${conversationId}/claim`,
      { method: "PATCH" },
    );

    const text = await response.text();
    const result = text.trim()
      ? (JSON.parse(text) as {
          success?: boolean;
          error?: string;
          conversation?: {
            id: string;
            assigned_to: string | null;
            assigned_at: string | null;
          };
        })
      : null;

    if (!response.ok || !result?.success || !result.conversation) {
      throw new Error(
        result?.error ??
          "Unable to assign this conversation to you.",
      );
    }

    const assignedMember =
      result.conversation.assigned_to
        ? teamMembers.find(
            (member) =>
              member.id === result.conversation?.assigned_to,
          ) ?? null
        : null;

    assignmentOverrideRef.current.set(conversationId, {
      assignedTo: result.conversation.assigned_to,
      expiresAt: Date.now() + 3_000,
    });

    setLiveConversations((current) =>
      sortLiveConversations(
        current.map((conversation) =>
          conversation.id === result.conversation?.id
            ? {
                ...conversation,
                ...result.conversation,
                assigned_member: assignedMember,
              }
            : conversation,
        ),
      ),
    );
    confirmActionSilently(activityToken);
  } catch (error) {
    actionLedgerRef.current.cancel(activityToken);
    assignmentOverrideRef.current.delete(conversationId);
    setAssignmentError(
      error instanceof Error
        ? error.message
        : "Unable to assign this conversation to you.",
    );
  } finally {
    setAssigning(false);
    endAction(conversationId, "assign");
  }
}

