  replyingToFacebookMessageId: string | null;
  onReplyToFacebookMessage: (messageId: string) => void;
  onCancelFacebookReply: () => void;
  onMessagePatched: (message: InboxMessage) => void;

  replyingToTelegramMessageId:
    | string
