type TelegramReplyPreview = {
  text: string;
  kind: string;
};

function telegramReplyPreviewFromMessage(
  source:
    | Record<string, unknown>
    | null
    | undefined,
): TelegramReplyPreview | null {
  if (!source) return null;

  const caption =
    typeof source.caption === "string"
      ? source.caption.trim()
      : "";
  if (Array.isArray(source.photo))
    return { text: caption || "Photo", kind: "Photo" };
  if (source.video)
    return { text: caption || "Video", kind: "Video" };
  if (source.animation)
    return { text: caption || "Animation", kind: "GIF" };

  const text =
    typeof source.text === "string"
      ? source.text.trim()
      : "";
  if (text) return { text, kind: "Text" };

  if (caption) return { text: caption, kind: "Caption" };
  if (source.voice)
    return { text: "Voice message", kind: "Voice" };
  if (source.audio)
    return { text: "Audio", kind: "Audio" };

  if (source.document) {
    const doc =
      source.document as Record<string, unknown>;
    return {
      text:
        typeof doc.file_name === "string"
          ? doc.file_name
          : "File",
      kind: "File",
    };
  }

  if (source.sticker) {
    const sticker =
      source.sticker as Record<string, unknown>;
    const emoji =
      typeof sticker.emoji === "string"
        ? sticker.emoji
        : "";
    return {
      text:
        emoji
          ? `Sticker ${emoji}`
          : "Sticker",
      kind: "Sticker",
    };
  }

  if (source.location)
    return {
      text: "Shared location",
      kind: "Location",
    };

  return {
    text: "Telegram message",
    kind: "Message",
  };
}


