    </>
  );
}

export function MessagePanel({
  compactWeb = false,
  onBack,
  searchJump,
  storageBusinessId,
  storageMemberId,
  activeConversation,
  messages: incomingMessages,
  loadingConversationMessages,
  conversationMessagesError,
  onRetryConversationMessages,
  teamMembers,
  hasMoreOlderMessages,
  loadingOlderMessages,
  olderMessagesError,
  onLoadOlderMessages,
  viewingAgents,
  typingAgents,
  teamPresence,
  agentPresenceStatus,
  reply,
  composerReady = true,
  sending,
  sendError,
  updatingStatus,
  statusError,
  assigning,
  assignmentError,
  markingUnread,
  pinning = false,
  pendingLabels,
  customerPanelVisible,

  onMarkUnread,
  onOpenHistory,
  onToggleCustomerPanel,
  onTogglePin,

  onReplyChange,
  onContactTagsChange,
  onSendMessage,
  onSendSticker,
  onSendAttachments,
  onStatusChange,
  onAssignmentChange,

  onLikeComment,
  onHideComment,
  onReplyToComment,
  replyingToCommentId,
  replyingToTelegramMessageId,
  replyingToFacebookMessageId,
  onReplyToFacebookMessage,
  onCancelFacebookReply,
  onMessagePatched,
  editingTelegramMessageId,
  telegramActionNotice,
  onReplyToTelegramMessage,
  onEditTelegramMessage,
  onDeleteTelegramMessage,
  onCancelTelegramEdit,
  onCancelTelegramReply,
  onCancelCommentReply,
  onDeleteComment,
  onRetryMessage,
}: MessagePanelProps) {
  const facebookCustomerBlock = useFacebookBlock(activeConversation);
  /*
   * A message id must appear once. Send reconciliation and Realtime can race
   * and briefly hand this panel the same row twice, which React reports as a
   * duplicate key and then renders unpredictably. Collapsing here keeps the
   * render honest no matter what upstream does; the later copy wins because it
   * carries the fresher server fields.
   */
  const messages = useMemo(() => {
    const byId = new Map<string, InboxMessage>();

    for (const message of withoutEchoedAttachmentDrafts(incomingMessages)) {
      const existing = byId.get(message.id);

      byId.set(
        message.id,
        existing
          ? ({ ...existing, ...message } as InboxMessage)
          : message,
      );
    }

    return byId.size === incomingMessages.length
      ? incomingMessages
      : Array.from(byId.values());
  }, [incomingMessages]);

  useEffect(() => {
    const businessId = activeConversation?.contact?.business_id;
    if (businessId && activeConversation?.social_account?.platform === "facebook") rememberMetaStickerMessages(businessId, activeConversation.id, messages);
