        window.clearTimeout(
          programmaticScrollTimerRef.current,
        );
      }
    },
    [],
  );

  /*
   * V2.7 — preserve the visible viewport while older messages
   * are prepended above the current scroll position.
   */
  const prependScrollSnapshotRef =
    useRef<{
      scrollHeight: number;
      scrollTop: number;
    } | null>(null);

  const olderLoadRequestedRef =
    useRef(false);

  const photoGroups = useMemo(() => buildPhotoGroups(messages), [messages]);
  const [activeAlbumPhoto, setActiveAlbumPhoto] = useState<AlbumPhotoSelection | null>(null);
  function activateAlbumPhoto(photo: InboxMessage) {
    setActiveAlbumPhoto(current => current?.conversationId === photo.conversation_id && current.photoId === photo.id
      ? current : { conversationId: photo.conversation_id, photoId: photo.id });
  }

  const scrollToNewest =
    useCallback(
      (
        behavior: ScrollBehavior =
          "smooth",
      ) => {
        const container =
          messagesContainerRef.current;

        if (!container) {
          return;
        }

        programmaticScrollRef.current = true;

        if (programmaticScrollTimerRef.current !== null) {
          window.clearTimeout(
            programmaticScrollTimerRef.current,
          );
        }

        programmaticScrollTimerRef.current =
          window.setTimeout(
            () => {
              programmaticScrollRef.current = false;
              programmaticScrollTimerRef.current = null;
            },
            behavior === "smooth" ? 700 : 90,
          );

        container.scrollTo({
          top: container.scrollHeight,
          behavior,
        });

        userNearBottomRef.current =
          true;

        setShowScrollToLatest(
          false,
        );

        setNewMessageCount(0);

      },
      [activeConversation?.id],
    );

  async function loadOlderMessages() {
    if (
      !hasMoreOlderMessages ||
      loadingOlderMessages ||
      olderLoadRequestedRef.current
    ) {
      return;
    }

    const container =
      messagesContainerRef.current;

    if (!container) {
      return;
    }

    olderLoadRequestedRef.current =
      true;

    prependScrollSnapshotRef.current = {
      scrollHeight:
        container.scrollHeight,
      scrollTop:
        container.scrollTop,
    };

    try {
      const loaded =
        await onLoadOlderMessages();

      if (!loaded) {
        prependScrollSnapshotRef.current =
          null;
      }
    } finally {
      olderLoadRequestedRef.current =
        false;
    }
  }

  const viewportAnchorRef = useRef<ScrollAnchor | null>(null);
  const anchorElementFor = useCallback((id: string) => deferredMessageRefs.current.get(photoGroups.get(id)?.lastId ?? id), [photoGroups]);
  const captureViewportAnchor = useCallback(() => {
    const container = messagesContainerRef.current;
    if (container) viewportAnchorRef.current = captureScrollAnchor(messages, anchorElementFor, container);
  }, [messages, anchorElementFor]);

  function handleMessagesScroll() {
    captureViewportAnchor();
    const container =
      messagesContainerRef.current;

    if (!container) {
      return;
    }

    /* Our own animation, not the agent moving the thread. */
    if (programmaticScrollRef.current) {
      return;
    }

    const distanceFromBottom =
      container.scrollHeight -
      container.scrollTop -
      container.clientHeight;

    const isNearBottom =
      distanceFromBottom <= 120;

    userNearBottomRef.current =
      isNearBottom;

    setShowScrollToLatest(
      !isNearBottom,
    );

    if (
      isNearBottom &&
      newMessageCount > 0
    ) {
      setNewMessageCount(0);
    }

    /*
     * V2.7 — when the agent reaches the top area, request the
     * next older page. The parent prevents duplicate network calls.
     */
    if (
      container.scrollTop <= 140 &&
      hasMoreOlderMessages &&
      !loadingOlderMessages
    ) {
      void loadOlderMessages();
    }
  }

  function showActionNotice(message: string) {
