  async function confirmCommentAction() {
    if (
      !commentConfirmTarget ||
      commentConfirmLoading
    ) {
      return;
    }

    const target = commentConfirmTarget;
    if (pendingCommentActionsRef.current.has(target.messageId)) return;
    const previous = target.previous;
    showActionNotice(target.kind === "delete" ? "Deleting comment…" : target.kind === "hide" ? "Hiding comment…" : "Unhiding comment…");

    setCommentConfirmLoading(true);
    setCommentConfirmTarget(null);

    try {
      if (target.kind === "delete") {
        setOptimisticCommentState(
          (current) => ({
            ...current,
            [target.messageId]: {
              ...previous,
              deleted: true,
              deletedBy: "page",
            },
          }),
        );

        const result =
          await runCommentAction(target.messageId, () => onDeleteComment(
            target.platformMessageId,
          ));

        if (result.deleted) {
          setOptimisticCommentState(
            (current) => ({
              ...current,
              [target.messageId]: {
                ...previous,
                liked: false,
                hidden: false,
                deleted: true,
                deletedBy: "customer",
              },
            }),
          );

          showActionNotice(
            "Message deleted by commenter or Page",
          );
          return;
        }

        // Uncertain: leave it as the agent set it; never roll back or resend.
        if (result.uncertain) return;

        if (!result.success) {
          setOptimisticCommentState(
            (current) => ({
              ...current,
              [target.messageId]: previous,
            }),
          );
          return;
        }

        showCommentSuccess(result, "Comment deleted");
        return;
      }

      const nextHidden =
        target.kind === "hide";

      setOptimisticCommentState(
        (current) => ({
          ...current,
          [target.messageId]: {
            ...previous,
            hidden: nextHidden,
          },
        }),
      );

      const result =
        await runCommentAction(target.messageId, () => onHideComment(
          target.platformMessageId,
          nextHidden,
        ));

      if (result.deleted) {
        setOptimisticCommentState(
          (current) => ({
            ...current,
            [target.messageId]: {
              ...previous,
              liked: false,
              hidden: false,
              deleted: true,
              deletedBy: "customer",
            },
          }),
        );

        showActionNotice(
          "Message deleted by commenter or Page",
        );
        return;
      }

      if (result.uncertain) return;

      if (!result.success) {
        setOptimisticCommentState(
          (current) => ({
            ...current,
            [target.messageId]: previous,
          }),
        );
        return;
      }

      showCommentSuccess(result, nextHidden ? "Comment hidden" : "Comment unhidden");
    } finally {
      setCommentConfirmLoading(false);
    }
  }

  useEffect(() => {
    /*
     * Every explicit conversation open starts at the newest message. Do not
     * restore a previous scroll position and do not jump to the first unread
     * marker. This also makes reopening a thread after switching conversations
     * deterministic on the first click.
     */
    initialScrollDoneRef.current = false;
    lastMessageIdRef.current = null;
    previousMessageCountRef.current = 0;
    userNearBottomRef.current = true;
    setShowScrollToLatest(false);
    prependScrollSnapshotRef.current = null;
    olderLoadRequestedRef.current = false;
    setNewMessageCount(0);
  }, [activeConversation?.id]);

  /*
   * V3.11.33 — selecting/opening a conversation must land on the newest
   * rendered message on the first try. Wait until the newest page has finished
   * loading, then scroll after paint. The short follow-up covers image/media
   * layout that can finish a moment after the message DOM is committed.
   */
  useEffect(() => {
    if (
      !activeConversation ||
      loadingConversationMessages
    ) {
      return;
    }

    let cancelled = false;
    const followUpTimers: number[] = [];

    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        if (cancelled) {
          return;
        }

        /*
         * Opening lands instantly. A thread opens scrolled to the top, so
         * animating to the newest message drags the whole history past the
         * agent — hundreds or thousands of pixels of images and bubbles the
         * browser has to paint mid-flight, which is what made it stutter.
         * The agent has not seen the top anyway, so there is nothing to
         * animate away from. Animation belongs to the short hops below and
         * to the Latest button.
         */
        scrollToNewest("auto");

        /*
         * The thread's height keeps changing after the message DOM is
         * committed — images and video posters decode, web fonts swap,
         * reply cards reflow — so a scroll fired once at commit time
         * lands short of the bottom whenever any of that resolves late.
         * That is why opening a conversation sometimes reached the newest
         * message and sometimes did not: it depended on whether the media
         * happened to be cached already.
         *
         * These corrections start only after the opening animation has
         * finished. Firing them during it replaced the animation with a
         * jump and made the whole thing look broken. Each one animates
         * too, and only runs when the thread is genuinely short of the
         * bottom, so a settled thread never scrolls twice.
         */
        for (const delay of [820, 1300, 1900]) {
          followUpTimers.push(
            window.setTimeout(() => {
              const container =
                messagesContainerRef.current;

              if (
                cancelled ||
                !container ||
                !userNearBottomRef.current
              ) {
                return;
              }

              const distanceFromBottom =
                container.scrollHeight -
                container.scrollTop -
                container.clientHeight;

              if (distanceFromBottom > 8) {
                /*
                 * Animate only short corrections. A long one has the same
                 * stutter problem as animating the open, so past roughly a
                 * screen and a half it simply snaps.
                 */
                scrollToNewest(
                  distanceFromBottom < 900
                    ? "smooth"
                    : "auto",
                );
              }
            }, delay),
          );
        }
      });
    });

    return () => {
      cancelled = true;

      for (const timer of followUpTimers) {
        window.clearTimeout(timer);
      }
    };
  }, [
    activeConversation?.id,
    loadingConversationMessages,
    scrollToNewest,
  ]);

  /*
   * Older pages are inserted before the currently visible messages.
   * Restore the viewport by adding the new content height so the
   * agent does not jump to a different message.
   */
  const loadOlderForJumpRef = useRef(onLoadOlderMessages);
  useEffect(() => { loadOlderForJumpRef.current = onLoadOlderMessages; });
  const jumpToTelegramReplyTarget =
    useCallback(
      async ({
        localMessageId,
        platformMessageId,
        search = false,
        signal,
      }: {
        search?: boolean;
        signal?: AbortSignal;
        localMessageId:
          | string
          | null;
        platformMessageId:
          | string
          | null;
      }) => {
        const scopedConversationId = jumpConversationRef.current;
        const findTarget = () => {
          if (jumpConversationRef.current !== scopedConversationId) return null;
          const currentMessages =
            latestMessagesRef.current;

          if (localMessageId) {
            const byLocalId = resolvePhotoReplyTarget(currentMessages, localMessageId, scopedConversationId);

            if (byLocalId) {
              return byLocalId;
            }
          }

          if (platformMessageId) {
            return (
              currentMessages.find(
                (item) =>
                  item.platform_message_id ===
                  platformMessageId,
              ) ?? null
            );
          }

          return null;
        };

        let targetMessage =
          findTarget();

        /*
         * A reply can point to a message older than the newest page.
         * Load older pages progressively before giving up.
         */
        let attempts = 0;

        while (
          !targetMessage &&
          hasMoreOlderMessagesRef.current &&
          (search || attempts < 12) &&
          !signal?.aborted &&
          jumpConversationRef.current === scopedConversationId
        ) {
          attempts += 1;

          let onAbort: (() => void) | undefined;
          const loaded = await Promise.race([
            loadOlderForJumpRef.current(),
            ...(signal ? [new Promise<boolean>(resolve => {
              onAbort = () => resolve(false);
              if (signal.aborted) onAbort();
              else signal.addEventListener("abort", onAbort, { once: true });
            })] : []),
          ]).finally(() => { if (signal && onAbort) signal.removeEventListener("abort", onAbort); });

          if (!loaded) {
            break;
          }

          await new Promise<void>(
            (resolve) => {
              window.requestAnimationFrame(
                () => {
                  window.requestAnimationFrame(
                    () =>
                      resolve(),
                  );
                },
              );
            },
          );

          targetMessage =
            findTarget();
        }

        if (signal?.aborted) return;
        if (!targetMessage || jumpConversationRef.current !== scopedConversationId) {
          if (jumpConversationRef.current === scopedConversationId) showActionNotice("Original message is older than the loaded history. Scroll up and try again.");
          return;
        }

        const targetElement = photoElementRefs.current.get(targetMessage.id) ??
          messageElementRefs.current.get(targetMessage.id) ??
          deferredMessageRefs.current.get(photoGroups.get(targetMessage.id)?.lastId ?? targetMessage.id);

        if (!targetElement) {
          return;
        }

        userNearBottomRef.current = false;
        setShowScrollToLatest(true);
        targetElement.scrollIntoView({
          behavior: "smooth",
          block: "center",
        });

        setJumpHighlightedMessageId(
          targetMessage.id,
        );

        window.setTimeout(() => {
          setJumpHighlightedMessageId(
            (current) =>
              current ===
              targetMessage?.id
                ? null
                : current,
          );
        }, 1800);
      },
      [photoGroups],
    );

  useLayoutEffect(() => {
    const snapshot = prependScrollSnapshotRef.current;
    const container = messagesContainerRef.current;
    if (!container) return;
    if (snapshot) {
      container.scrollTop = snapshot.scrollTop + Math.max(0, container.scrollHeight - snapshot.scrollHeight);
      prependScrollSnapshotRef.current = null;
    } else if (messages.length > 100 && typeof IntersectionObserver !== "undefined" && !userNearBottomRef.current) {
      // Recovery can insert older messages above a reader without a Load Older request.
      restoreScrollAnchor(viewportAnchorRef.current, anchorElementFor, container);
    }
    captureViewportAnchor();
  }, [messages, anchorElementFor, captureViewportAnchor]);

  useEffect(() => {
    const nextState: Record<
      string,
      {
        liked: boolean;
        hidden: boolean;
        deleted: boolean;
        deletedBy:
          | "customer"
          | "page"
          | null;
      }
    > = {};

    for (const message of messages) {
      nextState[message.id] = {
        liked:
          message.comment_is_liked ??
          false,

        hidden:
          message.comment_is_hidden ??
          false,

        deleted:
          message.comment_is_deleted ??
          false,

        deletedBy:
          message.comment_deleted_by ??
          null,
      };
    }

    const pending = new Set(pendingCommentActionsRef.current);
    setOptimisticCommentState(
      (current) => mergeCommentActionState(nextState, current, pending),
    );
  }, [messages]);

  useEffect(() => {
    if (
      loadingConversationMessages &&
      messages.length === 0
    ) {
      return;
    }

    const latestMessage =
      messages[
        messages.length - 1
      ] ?? null;

    const latestMessageId =
      latestMessage ? messageRenderKey(latestMessage) : null;

    /*
     * First committed message page for this conversation always opens at the
     * true newest message, regardless of unread markers or who sent it. Run on
     * two animation frames so the message DOM is fully painted before reading
     * scrollHeight; this removes the old first-click / second-click behavior.
     */
    if (!initialScrollDoneRef.current) {
      initialScrollDoneRef.current = true;
      lastMessageIdRef.current = latestMessageId;
      previousMessageCountRef.current = messages.length;

      window.requestAnimationFrame(() => {
        window.requestAnimationFrame(() => {
          scrollToNewest("auto");
        });
      });

      return;
    }

    const previousMessageId =
      lastMessageIdRef.current;

    lastMessageIdRef.current =
      latestMessageId;

    previousMessageCountRef.current =
      messages.length;

    /*
     * Delivery/Seen updates can replace message objects without
     * adding a new message. Do not show the indicator for those.
     */
    if (
      !latestMessage ||
      !latestMessageId ||
      latestMessageId ===
        previousMessageId
    ) {
      return;
    }

    // Opening still lands at latest, but subsequent arrivals must not pull
    // an agent away from history. Offer the existing Latest indicator instead.
    if (!userNearBottomRef.current) {
      setNewMessageCount(current => current + 1);
      setShowScrollToLatest(true);
      return;
    }
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        scrollToNewest("smooth");
      });
    });
  }, [
    loadingConversationMessages,
    messages,
    scrollToNewest,
  ]);

  useEffect(() => {
    setJumpHighlightedMessageId(
      null,
    );
    messageElementRefs.current.clear();
  }, [activeConversation?.id]);

  const searchJumpHandlerRef = useRef(jumpToTelegramReplyTarget);
  useEffect(() => { searchJumpHandlerRef.current = jumpToTelegramReplyTarget; });
  useEffect(() => {
    if (!searchJump || loadingConversationMessages || activeConversation?.id !== searchJump.conversationId) return;
    const controller = new AbortController();
    void searchJumpHandlerRef.current({ localMessageId: searchJump.messageId, platformMessageId: null, search: true, signal: controller.signal });
    return () => controller.abort();
  }, [searchJump, loadingConversationMessages, activeConversation?.id]);

  if (!activeConversation) return <InboxEmptyState />;

  const replyingToMessage =
    replyingToCommentId
      ? messages.find(
          (message) =>
            message.platform_message_id ===
            replyingToCommentId,
        ) ?? null
      : null;

  const replyingToName =
    activeConversation.contact
      ?.full_name?.trim() ||
    "Facebook commenter";

  const extendedConversation =
    activeConversation as InboxConversation & {
      platform?: string | null;
      social_account?:
        | (InboxConversation["social_account"] & {
            platform?: string | null;
          })
        | null;
    };

  const explicitPlatform =
    extendedConversation.platform
      ?.trim()
      .toLowerCase() ||
    extendedConversation.social_account
      ?.platform
      ?.trim()
      .toLowerCase() ||
    "";

  const hasTelegramMessage =
    messages.some((message) =>
      message.platform_message_id
        ?.toLowerCase()
        .startsWith("telegram:"),
    );

  // A Telegram Personal chat: the holder's own Telegram account, shared into TENH.
  const isTelegramPersonal =
    explicitPlatform === "telegram_personal";

  const headerChannelPlatform:
    | "messenger"
    | "telegram" =
    explicitPlatform === "telegram" ||
    isTelegramPersonal ||
    hasTelegramMessage
      ? "telegram"
      : "messenger";

  const headerChannelAccountName =
    isTelegramPersonal
      ? `${activeConversation.social_account?.account_name?.trim() || "Telegram"} · Telegram Personal`
      : activeConversation.social_account
          ?.account_name
          ?.trim() ||
        (headerChannelPlatform === "telegram"
          ? "Telegram Bot"
          : "Facebook Page");

  /*
   * Use the connected Facebook Page's public profile picture for Page-authored
   * comment replies. This is UI-only and keeps the current Inbox data model,
   * webhook processing, and nested-comment behavior unchanged.
   */
  const facebookPageProfilePictureUrl =
    headerChannelPlatform === "messenger" &&
    activeConversation.social_account
      ?.platform_account_id
      ?.trim()
      ? `https://graph.facebook.com/${encodeURIComponent(
          activeConversation.social_account.platform_account_id.trim(),
        )}/picture?type=large&width=96&height=96`
      : null;

  return (
    <section data-inbox-message-panel className="relative flex h-full min-h-0 min-w-0 flex-col overflow-hidden">

      {telegramActionNotice ||
      actionNotice ? (
        <div role="status" aria-live="polite" className="pointer-events-none absolute left-1/2 top-24 z-[100] flex max-w-[calc(100%-2rem)] -translate-x-1/2 items-center gap-2.5 rounded-2xl border border-slate-200 bg-white/95 px-4 py-3 text-sm font-semibold text-slate-800 shadow-[0_8px_30px_rgba(15,23,42,0.12)] backdrop-blur-sm">
          <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full ${actionNotice?.includes("failed") ? "bg-red-50 text-red-600" : "bg-emerald-50 text-emerald-600"}`}>
            {actionNotice?.endsWith("…") ? <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-slate-200 border-t-blue-500" /> : actionNotice?.includes("failed") ? "!" : "✓"}
          </span>
          {telegramActionNotice ??
            actionNotice}
        </div>
      ) : null}

      {commentConfirmTarget ? (
        <div
          className="fixed inset-0 z-[240] flex items-center justify-center bg-slate-950/30 p-4 backdrop-blur-[1px]"
          onMouseDown={(event) => {
            if (
              event.target ===
                event.currentTarget &&
              !commentConfirmLoading
            ) {
              setCommentConfirmTarget(null);
            }
          }}
          role="presentation"
        >
          <section
            role="alertdialog"
            aria-modal="true"
            aria-labelledby="facebook-comment-confirm-title"
            aria-describedby="facebook-comment-confirm-description"
            className="w-full max-w-[470px] overflow-hidden rounded-[20px] border border-slate-200 bg-white shadow-2xl"
            onMouseDown={(event) =>
              event.stopPropagation()
            }
          >
            <div className="flex items-center gap-3 border-b border-slate-200 px-5 py-4">
              <span
                className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full ${
                  commentConfirmTarget.kind ===
                  "delete"
                    ? "bg-red-50 text-red-500"
                    : "bg-amber-50 text-amber-600"
                }`}
              >
                {commentConfirmTarget.kind ===
                "delete" ? (
                  <svg
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.9"
                    className="h-5 w-5"
                    aria-hidden="true"
                  >
                    <path
                      d="M4 7h16"
                      strokeLinecap="round"
                    />
                    <path
                      d="M9 7V4h6v3"
                      strokeLinecap="round"
                    />
                    <path
                      d="M6 7l1 13h10l1-13"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                ) : (
                  <HideIcon />
                )}
              </span>

              <h2
                id="facebook-comment-confirm-title"
                className="min-w-0 flex-1 text-[17px] font-extrabold text-slate-950"
              >
                {commentConfirmTarget.kind ===
                "delete"
                  ? "Delete comment?"
                  : commentConfirmTarget.kind ===
                      "hide"
                    ? "Hide comment?"
                    : "Unhide comment?"}
              </h2>

              <button
                type="button"
                onClick={() =>
                  setCommentConfirmTarget(null)
                }
                disabled={commentConfirmLoading}
                className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700 disabled:cursor-not-allowed disabled:opacity-50"
                aria-label="Close confirmation"
              >
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.8"
                  className="h-5 w-5"
                  aria-hidden="true"
                >
                  <path
                    d="M6 6l12 12M18 6 6 18"
                    strokeLinecap="round"
                  />
                </svg>
              </button>
            </div>

            <div className="px-5 py-6">
              <p
                id="facebook-comment-confirm-description"
                className="text-[15px] leading-6 text-slate-600"
              >
                {commentConfirmTarget.kind ===
                "delete"
                  ? "This Facebook comment will be permanently deleted. This action cannot be undone."
                  : commentConfirmTarget.kind ===
                      "hide"
                    ? "This Facebook comment will be hidden on Facebook. You can unhide it later."
                    : "This Facebook comment will be visible on Facebook again."}
              </p>
            </div>

            <div className="flex items-center justify-end gap-2 border-t border-slate-200 bg-slate-50/80 px-5 py-4">
              <button
                type="button"
                onClick={() =>
                  setCommentConfirmTarget(null)
                }
                disabled={commentConfirmLoading}
                className="inline-flex h-10 items-center justify-center rounded-[10px] border border-slate-300 bg-white px-4 text-sm font-bold text-slate-600 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
              >
                Cancel
              </button>

              <button
                type="button"
                onClick={() =>
                  void confirmCommentAction()
                }
                disabled={commentConfirmLoading}
                className={`inline-flex h-10 min-w-[82px] items-center justify-center rounded-[10px] px-4 text-sm font-bold text-white transition disabled:cursor-not-allowed disabled:opacity-60 ${
                  commentConfirmTarget.kind ===
                  "delete"
                    ? "bg-red-500 hover:bg-red-600"
                    : "bg-amber-500 hover:bg-amber-600"
                }`}
              >
                {commentConfirmLoading
                  ? "Please wait..."
                  : commentConfirmTarget.kind ===
                      "delete"
                    ? "Delete"
                    : commentConfirmTarget.kind ===
                        "hide"
                      ? "Hide"
                      : "Unhide"}
              </button>
            </div>
          </section>
        </div>
      ) : null}

      <DeleteConfirmDialog
        open={Boolean(telegramDeleteTarget)}
        title={
          (telegramDeleteTarget?.length ?? 0) > 1
            ? `Delete ${telegramDeleteTarget?.length} photos?`
            : "Delete message?"
        }
        description={
          (telegramDeleteTarget?.length ?? 0) > 1
            ? "Every photo in this album will be permanently deleted from the chat. This action cannot be undone."
            : "This message will be permanently deleted from the chat. This action cannot be undone."
        }
        loading={deletingTelegramMessage}
        onCancel={() => {
          if (deletingTelegramMessage) {
            return;
          }

          setTelegramDeleteTarget(null);
        }}
        onConfirm={async () => {
          if (!telegramDeleteTarget) {
            return;
          }

          setDeletingTelegramMessage(true);

          /*
           * Keep the existing per-photo route and stop on the first failure.
           * Successfully deleted photos remain tombstoned when an album retry
           * is needed; a rejected delete must not be shown as a success.
           */
          try {
            for (const messageId of telegramDeleteTarget) {
              const deleted = await onDeleteTelegramMessage(messageId);
              if (!deleted) return;
            }

            setTelegramDeleteTarget(null);
          } finally {
            setDeletingTelegramMessage(false);
          }
        }}
      />

      <ConversationHeader
        compactWeb={compactWeb}
        onBack={onBack}
        conversation={
          activeConversation
        }
        teamMembers={
          teamMembers
        }
        viewingAgents={
          viewingAgents
        }
        typingAgents={
          typingAgents
        }
        teamPresence={
          teamPresence
        }
        agentPresenceStatus={
          agentPresenceStatus
        }
        updatingStatus={
          updatingStatus
        }
        assigning={
          assigning
        }
        markingUnread={
          markingUnread
        }
        pinning={pinning}
        pendingLabels={pendingLabels}
        customerPanelVisible={
          customerPanelVisible
        }
        channelPlatform={
          headerChannelPlatform
        }
        channelAccountName={
          headerChannelAccountName
        }
        onStatusChange={
          onStatusChange
        }
        onAssignmentChange={
          onAssignmentChange
        }
        onMarkUnread={
          onMarkUnread
        }
        onOpenHistory={
          onOpenHistory
        }
        onToggleCustomerPanel={
          onToggleCustomerPanel
        }
        onTogglePin={
          onTogglePin
        }
      />


      <PinnedMessageHeader
        messages={pinnedMessages.pins}
        pendingIds={pinnedMessages.pendingIds}
        onUnpin={(message) => void toggleMessagePin(message, false)}
        onJump={(message) => void jumpToTelegramReplyTarget({ localMessageId: message.id, platformMessageId: message.platform_message_id })}
      />
      {pinnedMessages.error ? (
        <div role="status" className="flex items-center gap-2 border-b border-amber-100 bg-amber-50 px-4 py-2 text-xs text-amber-800">
          <span className="flex-1">{pinnedMessages.error}</span>
          <button type="button" className="font-semibold underline" onClick={() => void pinnedMessages.refresh()}>Retry</button>
          <button type="button" aria-label="Dismiss pin notice" onClick={pinnedMessages.dismissError}>×</button>
        </div>
      ) : null}

      {statusError ? (
        <div className="border-b border-red-200 bg-red-50 px-4 py-2 text-sm text-red-600">
          {statusError}
        </div>
      ) : null}

      {assignmentError ? (
        <div className="border-b border-red-200 bg-red-50 px-4 py-2 text-sm text-red-600">
          {assignmentError}
        </div>
      ) : null}

      {/* Messages */}
      <MessageViewportFrame>
        {loadingConversationMessages ? (
          <div className="pointer-events-none absolute inset-0 z-20 overflow-hidden bg-slate-100 px-6 py-5">
            <div className="mx-auto flex h-full max-w-4xl flex-col justify-end gap-4">
              {[
                { side: "left", width: "w-56" },
                { side: "right", width: "w-72" },
                { side: "left", width: "w-80" },
                { side: "right", width: "w-52" },
                { side: "left", width: "w-64" },
              ].map((item, index) => (
                <div
                  key={index}
                  className={`flex ${item.side === "right" ? "justify-end" : "justify-start"}`}
                >
                  <div
                    className={`${item.width} animate-pulse rounded-2xl border border-white bg-white/85 p-3 shadow-sm`}
                  >
                    <div className="h-3 w-3/4 rounded bg-slate-200" />
                    <div className="mt-2 h-3 w-1/2 rounded bg-slate-100" />
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : conversationMessagesError ? (
          <div className="absolute inset-0 z-20 flex items-center justify-center bg-slate-100/75 backdrop-blur-[1px]">
            <div className="max-w-sm rounded-2xl border border-red-100 bg-white/95 p-4 text-center shadow-sm">
              <p className="text-sm font-semibold text-slate-800">
                Couldn&apos;t load this conversation
              </p>
              <p className="mt-1 text-xs text-slate-500">
                {conversationMessagesError}
              </p>
              <button
                type="button"
                onClick={onRetryConversationMessages}
                className="mt-3 rounded-full bg-blue-600 px-4 py-2 text-xs font-semibold text-white transition hover:bg-blue-700"
              >
                Retry
              </button>
            </div>
          </div>
        ) : null}

        <MessageScrollSurface
          ref={messagesContainerRef}
          onScroll={
            handleMessagesScroll
          }
          data-tenh-chat-surface="true"
          style={{
            overflowAnchor: messages.length > 100 && typeof IntersectionObserver !== "undefined" ? "none" : "auto",
            backgroundColor: "#EEF2F6",
            backgroundImage: `url("${chatBackgroundSrc}")`,
            /*
             * Every background is a full-bleed theme image, so all five are
             * drawn the same way. This used to branch on the default and tile
             * it at 320px, which was correct only for the old small pattern
             * (chat-bg.png). Once Theme 1 became the default that branch made
             * a full-size gradient repeat as a visible grid.
             */
            backgroundRepeat: "no-repeat",
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        >
          <div className="mb-3 flex min-h-8 items-center justify-center">
            {loadingOlderMessages ? (
              <div className="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-white/95 px-3 py-1.5 text-xs font-medium text-slate-500 shadow-sm">
                <span className="h-3 w-3 animate-spin rounded-full border-2 border-slate-300 border-t-blue-600" />
                Loading older messages...
              </div>
            ) : olderMessagesError ? (
              <button
                type="button"
                onClick={() =>
                  void loadOlderMessages()
                }
                className="rounded-full border border-red-200 bg-white/95 px-3 py-1.5 text-xs font-medium text-red-600 shadow-sm transition hover:bg-red-50"
              >
                Couldn&apos;t load older messages. Retry
              </button>
            ) : hasMoreOlderMessages ? (
              <span className="rounded-full bg-white/75 px-3 py-1 text-[11px] font-medium text-slate-400">
                Scroll up for earlier messages
              </span>
            ) : messages.length > 0 ? (
              <span className="rounded-full bg-white/75 px-3 py-1 text-[11px] font-medium text-slate-400">
                Beginning of conversation
              </span>
            ) : null}
          </div>

          <div className="space-y-4">
          {messages.map((message, messageIndex) => {
            const album = photoGroups.get(message.id);
            if (album && album.lastId !== message.id && !(messengerSources.before.get(message.id)?.length)) return null;
            return <DeferredInboxItem key={messageRenderKey(message)} enabled={messages.length > 100}
              initiallyVisible={messageIndex >= messages.length - 40}
              forceVisible={jumpHighlightedMessageId === message.id}
              containerRef={messagesContainerRef}
              onElement={element => { if (element) deferredMessageRefs.current.set(message.id, element); else deferredMessageRefs.current.delete(message.id); }}>
              {() => {
              const sourceCards = (messengerSources.before.get(message.id) ?? []).map((source) => (
                <MessengerSourceCard key={source.key} source={source} conversationId={activeConversation?.id} messageId={message.id} onOpenImage={setImagePreview} />
              ));
              /*
               * Earlier photos of an album render nothing: the whole grid is
               * drawn once, on the run's last message.
               */
              const photoGroup = photoGroups.get(
                message.id,
              );

              if (
                photoGroup &&
                photoGroup.lastId !== message.id
              ) {
                return sourceCards.length ? <Fragment key={message.id}>{sourceCards}</Fragment> : null;
              }

              const isOutgoing =
                message.direction ===
                "outgoing";

              const messageTimestamp =
                message.platform_created_at ??
                message.created_at;

              const previousMessage =
                messageIndex > 0
                  ? messages[messageIndex - 1]
                  : null;

              const previousMessageTimestamp =
                previousMessage
                  ? previousMessage.platform_created_at ??
                    previousMessage.created_at
                  : null;

              const showMessageDay =
                messageIndex === 0 ||
                !isSameLocalMessageDay(
                  messageTimestamp,
                  previousMessageTimestamp,
                );

              const messageStatus =
                message as InboxMessage & {
                  __optimistic_status?:
                    | "sending"
                    | "sent"
                    | "failed";
                  __optimistic_requires_review?: boolean;

                  delivery_status?:
                    | "sent"
                    | "delivered"
                    | "seen"
                    | null;

                  delivered_at?:
                    | string
                    | null;

                  seen_at?:
                    | string
                    | null;
                };

              const optimisticStatus =
                messageStatus
                  .__optimistic_status ??
                null;

              const persistedDeliveryStatus =
                messageStatus
                  .delivery_status ??
                "sent";

              const rawPayload =
                message.raw_payload as {
                  post_id?: string;
                  post?: {
                    id?: string;
                  } | null;
                  comment_id?: string;
                  parent_id?: string;
                  item?: string;
                  source?: string;
                  tenh_source?: string;
                  parent_comment_id?: string;
                  reply_comment_id?: string;
                  commenter_profile_picture_url?:
                    | string
                    | null;

                  tenh_attachment?: {
                    type?:
                      | "image"
                      | "video"
                      | "file"
                      | "audio"
                      | "voice"
                      | "sticker";
                    name?: string | null;
                    mime_type?: string | null;
                    size?: number | null;
                    attachment_id?: string | null;
                  } | null;

                  tenh_sticker?: {
                    format?:
                      | "static"
                      | "animated"
                      | "video";
                    preview_kind?:
                      | "image"
                      | "video"
                      | "file";
                    emoji?:
                      | string
                      | null;
                    set_name?:
                      | string
                      | null;
                  } | null;

                  tenh_animation?: {
                    format?:
                      | "gif"
                      | "mp4";
                    source?:
                      | string
                      | null;
                  } | null;

                  tenh_location?: {
                    latitude?: number;
                    longitude?: number;
                    horizontal_accuracy?:
                      | number
                      | null;
                    live_period?:
                      | number
                      | null;
                    source?:
                      | string
                      | null;
                  } | null;

                  message?: {
                    reply_to_message?:
                      | Record<string, unknown>
                      | null;
                    attachments?: Array<{
                      type?: string | null;
                      payload?: {
                        url?: string | null;
                        sticker_id?:
                          | number
                          | string
                          | null;
                      } | null;
                    }> | null;
                  } | null;

                  reply_to_message?:
                    | Record<string, unknown>
                    | null;

                  tenh_reply_fallback?: { reason?: string; notice?: string | null } | null;

                  tenh_reply?: {
                    scope?: "tenh" | "telegram" | "facebook";
                    reply_to_local_message_id?:
                      | string
                      | null;
                    reply_to_platform_message_id?:
                      | string
                      | null;
                    preview_text?: string | null;
                    preview_type?: string | null;
                  } | null;

                  tenh_edit?: {
                    source?: string | null;
                    edited_at?: string | null;
                  } | null;

                  tenh_deleted?: {
                    source?: string | null;
                    deleted_at?: string | null;
                  } | null;

                  tenh_delivery?: {
                    status?: string | null;
                    accepted_at?: string | null;
                  } | null;

                  post_preview?: {
                    id?: string;
                    message?: string | null;
                    full_picture?: string | null;
                    permalink_url?: string | null;
                    created_time?: string | null;
                  } | null;
                } | null;

              const savedPostPreview =
                rawPayload?.post_preview ??
                null;

              const isCurrentConversationRootComment =
                Boolean(
                  activeConversation.facebook_comment_id &&
                    (message.platform_message_id ===
                      activeConversation.facebook_comment_id ||
                      rawPayload?.comment_id ===
                        activeConversation.facebook_comment_id),
                );

              const postId =
                rawPayload?.post_id
                  ?.trim() ||
                rawPayload?.post?.id
                  ?.trim() ||
                savedPostPreview?.id
                  ?.trim() ||
                (isCurrentConversationRootComment
                  ? activeConversation.facebook_post_id?.trim() || null
                  : null);

              /*
               * Even if Meta's optional post-detail lookup temporarily fails,
               * a real Facebook comment still has a post ID. Keep the content
               * card visible with its ID + View Post link instead of collapsing
               * to the small standalone comment card. New webhook rows normally
               * include the richer saved preview from process-comment.ts.
               */
              const postPreview =
                savedPostPreview ??
                (postId
                  ? {
                      id: postId,
                      message: null,
                      full_picture: null,
                      permalink_url: null,
                      created_time: null,
                    }
                  : null);

              const attachmentMeta =
                rawPayload?.tenh_attachment ??
                null;

              const stickerMeta =
                rawPayload?.tenh_sticker ??
                null;

              /*
               * Facebook Messenger stickers arrive as image attachments with
               * payload.sticker_id. They do not include Telegram's
               * tenh_sticker metadata, so detect them from the original
               * Messenger webhook payload instead of rendering the Telegram
               * sticker fallback card.
               */
              const facebookStickerAttachment =
                rawPayload?.message
                  ?.attachments?.find(
                    (attachment) =>
                      attachment?.type === "sticker" ||
                      (attachment?.type === "image" &&
                        attachment?.payload?.sticker_id != null),
                  ) ?? null;

              const isFacebookSticker =
                Boolean(
                  facebookStickerAttachment,
                ) || (message.message_type === "sticker" && activeConversation.social_account?.platform === "facebook");

              const facebookStickerUrl =
                facebookStickerAttachment
                  ?.payload?.url ??
                message.attachment_url ??
                null;

              const animationMeta =
                rawPayload?.tenh_animation ??
                null;

              const locationMeta =
                rawPayload?.tenh_location ??
                null;

              const telegramNativeReply =
                rawPayload?.message
                  ?.reply_to_message ??
                rawPayload?.reply_to_message ??
                null;

              const replyImageReference = getReplyImageReference(message, messages);
              const replyVideoReference = getReplyVideoReference(message, messages);
              const nativeFacebookQuote = facebookNativeReply(message, messages);
              const telegramReplyPreview =
                (nativeFacebookQuote ? { text: nativeFacebookQuote.text, kind: nativeFacebookQuote.kind } : null) ??
                telegramReplyPreviewFromMessage(
                  telegramNativeReply,
                ) ??
                (
                  rawPayload?.tenh_reply
                    ?.preview_text
                    ? {
                        text:
                          rawPayload.tenh_reply
                            .preview_text,
                        kind:
                          rawPayload.tenh_reply
                            .preview_type ??
                          "Message",
                      }
                    : null
                );


              const telegramReplyLocalMessageId = nativeFacebookQuote?.localMessageId ?? (
                typeof rawPayload
                  ?.tenh_reply
                  ?.reply_to_local_message_id ===
                  "string"
                  ? rawPayload.tenh_reply
                      .reply_to_local_message_id
                  : null);

              const savedReplyPlatformMessageId =
                typeof rawPayload
                  ?.tenh_reply
                  ?.reply_to_platform_message_id ===
                  "string"
                  ? rawPayload.tenh_reply
                      .reply_to_platform_message_id
                  : null;

              const nativeReplyMessageId =
                telegramNativeReply &&
                typeof telegramNativeReply[
                  "message_id"
                ] === "number"
                  ? telegramNativeReply[
                      "message_id"
                    ]
                  : null;

              const currentTelegramMatch =
                message.platform_message_id
                  ?.match(
                    /^telegram:([^:]+):\d+$/,
                  ) ?? null;

              const nativeReplyPlatformMessageId =
                nativeReplyMessageId !==
                  null &&
                currentTelegramMatch
                  ? `telegram:${currentTelegramMatch[1]}:${nativeReplyMessageId}`
                  : null;

              const telegramReplyTargetPlatformMessageId =
                nativeFacebookQuote?.platformMessageId ?? savedReplyPlatformMessageId ??
                nativeReplyPlatformMessageId;

              const canJumpToTelegramReply =
                Boolean(
                  telegramReplyPreview &&
                    (
                      telegramReplyLocalMessageId ||
                      telegramReplyTargetPlatformMessageId
                    ),
                );

              const telegramEdited =
                Boolean(
                  rawPayload
                    ?.tenh_edit,
                );

              const telegramDeleted =
                Boolean(
                  rawPayload
                    ?.tenh_deleted,
                );

              /*
               * A message that is gone, however it went.
               *
               * Three things end a message and they were reported three ways:
               * Telegram writes tenh_deleted into the payload, a deleted
               * Facebook comment flips comment_is_deleted, and a Page
               * unsending a Messenger message leaves the row with its text
               * replaced. Only the first was drawn as deleted -- the other two
               * kept the ordinary bubble, so "Message deleted by Page" arrived
               * in the same blue as a real reply and read like something the
               * Page had just said.
               */
              const isDeletedMessage = isMessageDeleted(message);

              const attachmentUrl =
                isDeletedMessage ? null : message.attachment_url;

              const isImageMessage =
                message.message_type ===
                "image";

              const isVideoMessage =
                message.message_type ===
                "video";

              const isAnimationMessage =
                isVideoMessage &&
                Boolean(
                  animationMeta,
                );

              const isFileMessage =
                message.message_type ===
                "file";

              const isAudioMessage =
                message.message_type ===
                "audio";

              const isVoiceMessage =
                message.message_type ===
                "voice";

              const isStickerMessage =
                message.message_type ===
                "sticker";

              /*
               * A sticker is the artwork, not text inside a card.
               *
               * Every chat app people already use -- Telegram, Messenger,
               * WhatsApp -- draws stickers straight onto the conversation with
               * no bubble, because a sticker is usually a transparent PNG or
               * WebM cut to its own silhouette. Wrapping one in a coloured
               * bubble re-adds the rectangle the artist removed, and on our own
               * blue outgoing bubble the sticker's soft edge reads as a badly
               * cut-out photo.
               *
               * The bubble still earns its place when the content needs a
               * surface: a deleted sticker becomes a line of italic text, and a
               * reply preview is a card that has to sit on something.
               */
              const isBareSticker =
                isStickerMessage &&
                !isDeletedMessage &&
                !telegramReplyPreview;

              /*
               * White meta text only works on the coloured bubble. Once the
               * bubble is gone the timestamp sits on the page, so it has to
               * switch back to slate or it disappears.
               */
              const onColoredBubble =
                isOutgoing && !isBareSticker && !isDeletedMessage;

              const locationLatitude =
                typeof locationMeta
                  ?.latitude ===
                  "number"
                  ? locationMeta.latitude
                  : null;

              const locationLongitude =
                typeof locationMeta
                  ?.longitude ===
                  "number"
                  ? locationMeta.longitude
                  : null;

              const isLocationMessage =
                !isDeletedMessage &&
                locationLatitude !==
                  null &&
                locationLongitude !==
                  null;

              const locationUrl =
                isLocationMessage
                  ? `https://www.google.com/maps?q=${locationLatitude},${locationLongitude}`
                  : null;

              const attachmentName =
                attachmentMeta?.name?.trim() ||
                message.message_text ||
                (isImageMessage
                  ? "Photo"
                  : isAnimationMessage
                    ? "Animation"
                    : isVideoMessage
                      ? "Video"
                    : isStickerMessage
                      ? stickerMeta?.emoji
                        ? `Sticker ${stickerMeta.emoji}`
                        : "Sticker"
                      : isVoiceMessage
                        ? "Voice message"
                        : isAudioMessage
                          ? "Audio"
                          : "File");

              const postUrl =
                safePostLink(postPreview?.permalink_url);

              const serverState = {
                liked:
                  message.comment_is_liked ??
                  false,

                hidden:
                  message.comment_is_hidden ??
                  false,

                deleted:
                  message.comment_is_deleted ??
                  false,

                deletedBy:
                  message.comment_deleted_by ??
                  null,
              };

              const commentState =
                optimisticCommentState[
                  message.id
                ] ??
                serverState;

              const isTelegramMessage =
                message.platform_message_id
                  ?.startsWith(
                    "telegram:",
                  ) === true;

              const messageActions = getMessageActions(message,
                activeConversation.social_account?.platform ??
                (isTelegramMessage ? "telegram" : "facebook"));

              const isTelegramReplyTarget =
                replyingToTelegramMessageId === message.id ||
                replyingToFacebookMessageId === message.id;
              const albumActionTarget = isImageMessage && photoGroup && photoGroup.members.length > 1
                ? getAlbumActionTarget(photoGroup.members, messages, message, activeAlbumPhoto, replyingToFacebookMessageId ?? replyingToTelegramMessageId)
                : null;
              const replyActionId = albumActionTarget?.photo.id ?? message.id;

              /*
               * V3.11.30.1 — comment actions belong to the individual
               * Facebook comment message, not to the whole conversation.
               * A TENH thread can contain both Messenger DMs and Page comments.
               */
              const isFacebookCommentMessage =
                Boolean(
                  rawPayload?.comment_id ||
                  rawPayload?.post_id ||
                  rawPayload?.item === "comment" ||
                  rawPayload?.source ===
                    "facebook_comment_reply" ||
                  rawPayload?.tenh_source ===
                    "facebook_page_reply" ||
                  rawPayload?.parent_comment_id ||
                  rawPayload?.reply_comment_id,
                );

              /*
               * Keep the current nested-comment UI compatible with both:
               * - TENH-native replies: source + parent_comment_id
               * - older Business Suite rows: tenh_source + Meta parent_id
               *
               * This is UI-only and lets replies already saved before the
               * metadata normalization render inside their parent card too.
               */
              const facebookReplyParentId = facebookCommentIdentity(message).parentId;

              const safeFacebookGroupInfo =
                getSafeFacebookCommentGroupInfo(message);

              const previousFacebookRootGroupKey =
                findNeighborFacebookRootGroupKey(
                  messages,
                  messageIndex - 1,
                  -1,
                );

              const nextFacebookRootGroupKey =
                findNeighborFacebookRootGroupKey(
                  messages,
                  messageIndex + 1,
                  1,
                );

              const isFacebookPostGroupContinuation =
                Boolean(
                  safeFacebookGroupInfo.groupKey &&
                    previousFacebookRootGroupKey ===
                      safeFacebookGroupInfo.groupKey,
                );

              const hasNextFacebookRootInSamePostGroup =
                Boolean(
                  safeFacebookGroupInfo.groupKey &&
                    nextFacebookRootGroupKey ===
                      safeFacebookGroupInfo.groupKey,
                );

              // UI only: replies to Facebook comments are rendered as a
              // compact nested card directly beneath the parent comment.
              // This does not change reply IDs, actions, API calls, or data.
              const isNestedFacebookCommentReply = Boolean(
                facebookReplyParentId && facebookCommentRenderRoot(message, messages, optimisticCommentState).id !== message.id,
              );

              // UI only: collect the full Facebook reply tree beneath this
              // root comment. This includes customer replies, Page/TENH
              // replies, and replies-to-replies. Exact Meta parent IDs drive
              // the tree; no customer/post guessing is used here.
              const facebookChildReplies =
                !isNestedFacebookCommentReply &&
                message.platform_message_id
                  ? collectFacebookCommentDescendants(
                      messages,
                      message.platform_message_id,
                      optimisticCommentState,
                    )
                  : [];

              const facebookParentPreview = facebookCommentParentPreview(message, messages, headerChannelAccountName, optimisticCommentState);

              const showCommentActions =
                isFacebookCommentMessage &&
                Boolean(
                  message.platform_message_id,
                ) &&
                !message.id.startsWith(
                  "optimistic:",
                );

              const isJumpHighlighted =
                jumpHighlightedMessageId ===
                message.id;

              const isReplyTarget =
                replyingToCommentId ===
                message.platform_message_id;

              async function toggleLike() {
                if (pendingCommentActionsRef.current.has(message.id)) return;
                const previous =
                  commentState.liked;

                const next =
                  !previous;
                showActionNotice(next ? "Liking comment…" : "Unliking comment…");

                setOptimisticCommentState(
                  (current) => ({
                    ...current,

                    [message.id]: {
                      ...commentState,
                      liked: next,
                    },
                  }),
                );

                const result =
                  await runCommentAction(message.id, () => onLikeComment(
                    message.platform_message_id,
                    next,
                  ));

                if (result.deleted) {
                  setOptimisticCommentState(
                    (current) => ({
                      ...current,

                      [message.id]: {
                        ...commentState,
                        liked: false,
                        hidden: false,
                        deleted: true,
                        deletedBy:
                          "customer",
                      },
                    }),
                  );

                  showActionNotice(
                    "Message deleted by commenter or Page",
                  );

                  return;
                }

                if (result.uncertain) return;

                if (!result.success) {
                  setOptimisticCommentState(
                    (current) => ({
                      ...current,

                      [message.id]: {
                        ...commentState,
                        liked:
                          previous,
                      },
                    }),
                  );

                  return;
                }

                showCommentSuccess(result, next ? "Comment liked" : "Comment unliked");
              }

              /*
               * Locked Facebook Comment UI rule:
               * every top-level Facebook comment gets its own post context
               * card. Nested customer/Page replies never render another post
               * card. Do not suppress a card just because the same post was
               * shown earlier in this customer conversation.
               */
              const showFacebookPostPreview =
                Boolean(
                  isFacebookCommentMessage &&
                    !isNestedFacebookCommentReply &&
                    !isFacebookPostGroupContinuation &&
                    !commentState.deleted,
                );

              const facebookCommentActorName =
                isOutgoing
                  ? headerChannelAccountName
                  : replyingToName;

              const savedCommenterProfilePictureUrl =
                rawPayload
                  ?.commenter_profile_picture_url
                  ?.trim() ||
                null;

              const facebookCommentActorPhoto =
                isOutgoing
                  ? facebookPageProfilePictureUrl
                  : savedCommenterProfilePictureUrl ??
                    activeConversation.contact
                      ?.profile_picture_url ??
                    null;

              const facebookCommentActorInitial =
                facebookCommentActorName
                  .trim()
                  .charAt(0)
                  .toUpperCase() || "?";

              /*
               * UI only: Facebook comment replies use a compact nested
               * thread layout. IDs, actions, API calls, and reply behavior
               * stay unchanged.
               */

              if (isFacebookCommentMessage) {
                // A reply that has a local parent is rendered inside that
                // parent below. Skip the old standalone reply card.
                if (isNestedFacebookCommentReply) {
                  return null;
                }

                // Deleted Facebook comments collapse to one safe status row:
                // no avatar, name, post preview, actions, or child replies.
                if (commentState.deleted) {
                  const deletedByPage =
                    commentState.deletedBy === "page" ||
                    (commentState.deletedBy === null && isOutgoing);

                  return (
                    <Fragment key={message.id}>
                      {sourceCards}
                      {showMessageDay && !isFacebookPostGroupContinuation ? (
                        <div className="flex items-center gap-3 py-1">
                          <div className="h-px flex-1 bg-blue-200/70" />
                          <span className="rounded-full border border-blue-200 bg-white/90 px-3 py-1 text-[11px] font-semibold text-blue-700 shadow-sm">
                            <HydrationSafeMessageDay
                              value={messageTimestamp}
                            />
                          </span>
                          <div className="h-px flex-1 bg-blue-200/70" />
                        </div>
                      ) : null}

                      {/*
                        A deleted comment keeps the shape of a comment.

                        It used to collapse to a grey chip pushed in by a bare
                        left margin, which only lines up with the comment body
                        when the row above happens to be a comment too -- next
                        to anything else it reads as floating in the middle of
                        the thread, attached to nothing. Keeping the avatar
                        column, the eyebrow and the time means it sits in the
                        same grid as every row around it, and the reader can
                        still tell what was removed and when.

                        Everything identifying stays gone: no name, no photo,
                        no post card, no actions. The circle is an empty dashed
                        outline holding the same trash icon the other two
                        deleted states use, so all three read as one thing.
                      */}
                      <div data-message-row tabIndex={compactWeb ? 0 : undefined}
                        ref={(node) => {
                          if (node) {
                            messageElementRefs.current.set(
                              message.id,
                              node,
                            );
                          } else {
                            messageElementRefs.current.delete(
                              message.id,
                            );
                          }
                        }}
                        className="flex gap-2.5 px-1 py-2 sm:gap-3 sm:px-2"
                      >
                        <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-dashed border-slate-300 text-slate-400 sm:h-11 sm:w-11">
                          <svg
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="1.8"
                            className="h-4 w-4 sm:h-[18px] sm:w-[18px] shrink-0"
                            aria-hidden="true"
                          >
                            <path
                              d="M4 7h16"
                              strokeLinecap="round"
                            />
                            <path
                              d="M9 7V4h6v3"
                              strokeLinecap="round"
                            />
                            <path
                              d="M6 7l1 13h10l1-13"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                          </svg>
                        </div>

                        <div className="min-w-0 flex-1">
                          <div className="mb-1 text-[11px] font-extrabold uppercase tracking-[0.04em] text-slate-400">
                            Facebook Comment
                          </div>

                          <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
                            <span className="text-[15px] italic leading-5 text-slate-500 sm:text-base">
                              {deletedByPage
                                ? isKhmer
                                  ? "សារត្រូវបានលុបដោយទំព័រ"
                                  : "Message deleted by Page"
                                : isKhmer
                                  ? "សារត្រូវបានលុបដោយអ្នកបញ្ចេញមតិ"
                                  : "Message deleted by commenter"}
                            </span>

                            <span className="text-sm text-slate-400">
                              <HydrationSafeMessageTime
                                value={messageTimestamp}
                              />
                            </span>
                          </div>
                        </div>
                      </div>
                    </Fragment>
                  );
                }

                return (
                  <Fragment key={message.id}>
                      {sourceCards}
                    {showMessageDay && !isFacebookPostGroupContinuation ? (
                      <div className="flex items-center gap-3 py-1">
                        <div className="h-px flex-1 bg-blue-200/70" />
                        <span className="rounded-full border border-blue-200 bg-white/90 px-3 py-1 text-[11px] font-semibold text-blue-700 shadow-sm">
                          <HydrationSafeMessageDay
                            value={messageTimestamp}
                          />
                        </span>
                        <div className="h-px flex-1 bg-blue-200/70" />
                      </div>
                    ) : null}

                    <div data-message-row tabIndex={compactWeb ? 0 : undefined}
                      ref={(node) => {
                        if (node) {
                          messageElementRefs.current.set(
                            message.id,
                            node,
                          );
                        } else {
                          messageElementRefs.current.delete(
                            message.id,
                          );
                        }
                      }}
                      style={
                        isFacebookPostGroupContinuation ||
                        hasNextFacebookRootInSamePostGroup
                          ? {
                              // Tailwind 4 `space-y-4` adds logical block-end
                              // margin to the PREVIOUS direct child. Remove that
                              // spacing on every member of the same safe Facebook
                              // post/customer group so it renders as one card.
                              ...(isFacebookPostGroupContinuation
                                ? {
                                    marginBlockStart: 0,
                                    marginTop: 0,
                                  }
                                : {}),
                              ...(hasNextFacebookRootInSamePostGroup
                                ? {
                                    marginBlockEnd: 0,
                                    marginBottom: 0,
                                  }
                                : {}),
                            }
                          : undefined
                      }
                      className={`${
                        isNestedFacebookCommentReply
                          ? "!mt-0 ml-[52px] w-fit max-w-[680px] rounded-[16px] bg-white px-2 py-1 shadow-none sm:ml-[64px]"
                          : isFacebookPostGroupContinuation
                            ? `!mt-0 w-full max-w-[860px] rounded-t-none ${
                                hasNextFacebookRootInSamePostGroup
                                  ? "rounded-b-none border-b-0"
                                  : "rounded-b-[20px]"
                              } border-x border-b border-slate-200 bg-white p-2 shadow-[0_4px_16px_rgba(15,23,42,0.05)]`
                            : `${
                                hasNextFacebookRootInSamePostGroup
                                  ? "w-full rounded-t-[20px] rounded-b-none border-b-0"
                                  : "w-fit rounded-[20px]"
                              } max-w-[860px] border border-slate-200 bg-white p-2 shadow-[0_4px_16px_rgba(15,23,42,0.05)]`
                      } transition ${
                        isJumpHighlighted
                          ? "rounded-[18px] ring-2 ring-amber-300/70 ring-offset-2"
                          : isReplyTarget
                            ? "rounded-[18px] ring-2 ring-blue-300/70 ring-offset-2"
                            : ""
                      }`}
                    >
                      {showFacebookPostPreview ? (
                        <FacebookPostCard key={`${activeConversation.id}:${message.id}`}
                          conversationId={activeConversation.id} messageId={message.id}
                          postId={postId} savedPreview={postPreview}
                          parentId={facebookReplyParentId} savedParent={facebookParentPreview}
                          showParentContext={!isOutgoing}
                          accountName={headerChannelAccountName} isKhmer={isKhmer}
                          onOpenImage={setImagePreview} />
                      ) : null}

                      <div
                        className={`relative flex gap-2.5 ${
                          isNestedFacebookCommentReply
                            ? "px-0 py-1.5 sm:gap-3"
                            : isFacebookPostGroupContinuation
                              ? "px-1 py-3 sm:px-2"
                              : showFacebookPostPreview
                                ? "mt-3 px-1 py-2 sm:px-2"
                                : "px-1 py-2 sm:px-2"
                        }`}
                      >
                        <div className="shrink-0">
                          {facebookCommentActorPhoto ? (
                            <img
                              src={facebookCommentActorPhoto}
                              alt={facebookCommentActorName}
                              // One per comment in the thread, and the thread
                              // pages at 50. The other avatars here already
                              // load this way.
                              loading="lazy"
                              decoding="async"
                              className={`${
                                isNestedFacebookCommentReply
                                  ? "h-8 w-8"
                                  : "h-10 w-10 sm:h-11 sm:w-11"
                              } rounded-full object-cover ring-1 ring-slate-200`}
                            />
                          ) : (
                            <div
                              className={`flex items-center justify-center rounded-full font-bold ${
                                isNestedFacebookCommentReply
                                  ? "h-8 w-8 text-xs"
                                  : "h-10 w-10 text-sm sm:h-11 sm:w-11 sm:text-base"
                              } ${
                                isOutgoing
                                  ? "bg-blue-600 text-white shadow-[0_6px_18px_rgba(37,99,235,0.22)]"
                                  : "bg-blue-50 text-blue-700"
                              }`}
                            >
                              {facebookCommentActorInitial}
                            </div>
                          )}
                        </div>

                        <div className="min-w-0 flex-1">
                          <div className="mb-1 text-[11px] font-extrabold uppercase tracking-[0.04em] text-blue-600">
                            Facebook Comment
                          </div>

                          <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
                            <span className="text-[15px] font-bold text-slate-950 sm:text-base">
                              {facebookCommentActorName}
                            </span>

                            {isOutgoing ? (
                              <span className="rounded-full bg-blue-50 px-2 py-0.5 text-[11px] font-bold text-blue-600">
                                {isKhmer ? "អ្នក" : "You"}
                              </span>
                            ) : null}

                            <span className="text-sm text-slate-400">
                              <HydrationSafeMessageTime
                                value={messageTimestamp}
                              />
                            </span>

                            {isOutgoing &&
                            !commentState.deleted ? (
                              <span className="text-[11px] font-normal text-slate-400">
                                {optimisticStatus ===
                                "sending"
                                  ? "Sending..."
                                  : optimisticStatus ===
                                      "failed"
                                    ? "Failed to send"
                                    : persistedDeliveryStatus ===
                                        "seen"
                                      ? "✓✓ Seen"
                                      : persistedDeliveryStatus ===
                                          "delivered"
                                        ? "✓✓ Delivered"
                                        : "✓ Sent"}
                              </span>
                            ) : null}
                          </div>

                          {isOutgoing && rawPayload?.tenh_reply_fallback?.reason === "original_unavailable" ? (
                          <div className="mb-2 text-[11px] text-white/80" title="The original Telegram message was unavailable; this message was sent normally.">Sent without quote · original unavailable</div>
                        ) : null}

                          {commentState.deleted ? (
                            <div className="mt-3 inline-flex items-center gap-2 rounded-[14px] bg-slate-50 px-3.5 py-2.5 text-sm italic text-slate-400">
                              <svg
                                viewBox="0 0 24 24"
                                fill="none"
                                stroke="currentColor"
                                strokeWidth="1.8"
                                className="h-4 w-4 shrink-0"
                                aria-hidden="true"
                              >
                                <path d="M4 7h16" strokeLinecap="round" />
                                <path d="M9 7V4h6v3" strokeLinecap="round" />
                                <path
                                  d="M6 7l1 13h10l1-13"
                                  strokeLinecap="round"
                                  strokeLinejoin="round"
                                />
                              </svg>
                              <span>
                                Message deleted by commenter or Page
                              </span>
                            </div>
                          ) : (
                            <div
                              className={`mt-0.5 max-w-[680px] whitespace-pre-wrap text-[15px] leading-5 sm:text-base ${
                                isOutgoing
                                  ? "text-slate-900"
                                  : "text-slate-900"
                              }`}
                            >
                              {message.message_text ??
                                "Facebook comment"}
                            </div>
                          )}

                          {showCommentActions ? (
                            <div data-comment-actions className="mt-2 flex flex-wrap items-center gap-x-4 gap-y-1 text-[13px] font-medium">
                              {!isOutgoing ? (
                                <>
