                          <div className="flex items-center gap-2 py-1 text-sm italic text-slate-400">
                            <svg
                              viewBox="0 0 24 24"
                              fill="none"
                              stroke="currentColor"
                              strokeWidth="1.8"
                              className="h-4 w-4 shrink-0"
                              aria-hidden="true"
                            >
                              <path
                                d="M4 7h16"
                                strokeLinecap="round"
                              />
                              <path
                                d="M9 7V4h6v3"
                                strokeLinecap="round"
                              />
                              <path
                                d="M6 7l1 13h10l1-13"
                                strokeLinecap="round"
                                strokeLinejoin="round"
                              />
                            </svg>

                            <span>
                              Message deleted by commenter or Page
                            </span>
                          </div>
                        ) : postId ? (
                          <div className="overflow-hidden rounded-xl border border-slate-200 bg-white">
                            <FacebookPostCard key={`${activeConversation.id}:${message.id}:legacy`}
                              conversationId={activeConversation.id} messageId={message.id} postId={postId}
                              savedPreview={postPreview} accountName={activeConversation.social_account?.account_name ?? "Facebook Page"}
                              isKhmer={isKhmer} onOpenImage={setImagePreview} />

                            {/* Customer comment */}
                            <div className="border-t border-slate-100 px-3 py-2.5">
                              <div className="text-[11px] font-semibold uppercase tracking-wide text-blue-600">
                                {isKhmer ? "Facebook comments" : "Facebook Comment"}
                              </div>

                              <div className="mt-1 whitespace-pre-wrap text-sm font-medium text-slate-900">
                                {message.message_text ??
                                  "Facebook comment"}
                              </div>

                              {postUrl ? (
                                <a
                                  href={
                                    postUrl
                                  }
                                  target="_blank"
                                  rel="noreferrer"
                                  className="mt-2 inline-flex items-center gap-1 text-xs font-medium text-blue-600 hover:underline"
                                >
                                  {isKhmer ? "View Post" : "View Post"}
                                  <span
                                    aria-hidden="true"
                                  >
                                    ↗
                                  </span>
                                </a>
                              ) : null}
                            </div>
                          </div>
                        ) : isLocationMessage &&
                          locationUrl ? (
                          <a
                            href={locationUrl}
                            target="_blank"
                            rel="noreferrer"
                            className="block min-w-[260px] rounded-xl border border-slate-200 bg-white/90 p-3 transition hover:bg-white"
                          >
                            <div className="flex items-start gap-3">
                              <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-blue-50 text-xl">
                                📍
                              </span>

                              <span className="min-w-0 flex-1">
                                <span className="block text-sm font-semibold text-slate-800">
                                  Shared location
                                </span>

                                <span className="mt-1 block text-xs text-slate-500">
                                  {locationLatitude?.toFixed(
                                    6,
                                  )}
                                  {", "}
                                  {locationLongitude?.toFixed(
                                    6,
                                  )}
                                </span>

                                <span className="mt-2 inline-flex text-xs font-medium text-blue-600">
                                  Open in Maps ↗
                                </span>
                              </span>
                            </div>
                          </a>
                        ) : isDeletedMessage ? (
                          <p className="flex items-center gap-1.5 whitespace-pre-wrap italic text-slate-500">
                            <span aria-hidden>🗑</span>
                            {getDeletedMessageText(message, {
                              customerName: activeConversation.contact?.full_name,
                              teamMembers,
                            })}
                          </p>
                        ) : isStickerMessage ? (
                          /*
                           * Sized at 160px, up from 128. A sticker carries its
                           * expression in the face, and at 128 an animated one
                           * is too small to read -- which is the whole reason
                           * the customer sent it instead of typing.
                           *
                           * No rounding on the artwork: these are transparent
                           * cut-outs, so a corner radius can only clip a paw or
                           * an ear that the artist drew right to the edge.
                           */
                          <div className="w-fit">
                            {isFacebookSticker &&
                            facebookStickerUrl ? (
                              <ResilientStickerImage
                                directSrc={facebookStickerUrl}
                                conversationId={message.conversation_id}
                                messageId={message.id}
                                alt="Facebook sticker"
                                emoji={stickerMeta?.emoji}
                              />
                            ) : attachmentUrl &&
                              stickerMeta
                                ?.preview_kind ===
                                "video" ? (
                              <video
                                src={attachmentUrl}
                                autoPlay
                                loop
                                muted
                                playsInline
                                className="max-h-40 max-w-[160px] bg-transparent object-contain"
                              />
                            ) : attachmentUrl &&
                              stickerMeta
                                ?.preview_kind ===
                                "image" ? (
                              <ResilientStickerImage
                                directSrc={attachmentUrl}
                                conversationId={message.conversation_id}
                                messageId={message.id}
                                alt={
                                  stickerMeta?.emoji
                                    ? `Telegram sticker ${stickerMeta.emoji}`
                                    : "Telegram sticker"
                                }
                                emoji={stickerMeta?.emoji}
                              />
                            ) : (
                              /*
                               * Nothing downloaded yet. This one keeps a
                               * surface, because an emoji and a label floating
                               * on the page would not read as a message at all.
                               */
                              <div className="flex min-h-20 w-fit min-w-[104px] flex-col items-center justify-center rounded-2xl border border-slate-200 bg-white/80 px-3 py-2.5">
                                <span className="text-3xl leading-none">
                                  {stickerMeta?.emoji ??
                                    "✨"}
                                </span>
                                <span className="mt-1.5 text-[10.5px] font-medium text-slate-500">
                                  {isFacebookSticker
                                    ? "Facebook sticker"
                                    : stickerMeta?.format ===
                                        "animated"
                                      ? "Animated sticker"
                                      : "Telegram sticker"}
                                </span>
                              </div>
                            )}
                          </div>
                        ) : isImageMessage &&
                          photoGroup &&
                          photoGroup.members.length > 1 ? (
                          /*
                           * Two photos stack, the way Telegram shows them.
                           * Side by side forced each into a square and cut the
                           * subject out of both -- with only two there is room
                           * to show them wide instead. Three or four go 2x2,
                           * more go three across so six reads as 3x2, and
                           * those stay square to keep the rows aligned.
                           *
                           * Held to the same 300px column as a single photo.
                           * `-mx-4` makes the grid span the bubble, and the
                           * bubble runs to 62% of the panel, so on a wide
                           * screen a two-photo album was drawing two 400px-tall
                           * images and pushing the rest of the conversation off
                           * the screen. Bounding the width bounds the height
                           * too, since every cell is on a fixed aspect ratio.
                           */
                          <PhotoAlbumFrame count={photoGroup.members.length} hasReplyPreview={Boolean(telegramReplyPreview)}>
                            {photoGroup.members.map((photo: InboxMessage, photoIndex: number) => {
                              const photoUrl = photo.attachment_url;
                              const photoSelected = (replyingToFacebookMessageId ?? replyingToTelegramMessageId) === photo.id;
                              const canReplyToPhoto = getMessageActions(photo, activeConversation.social_account?.platform).reply;
                              const photoReference = { conversationId: photo.conversation_id, messageId: photo.id };

                              if (!photoUrl) {
                                return (
                                  <div
                                    key={`album-${photo.id}`}
                                    className={`flex w-full items-center justify-center bg-slate-100 text-[10px] font-medium text-slate-400 ${
                                      photoGroup.members
                                        .length === 2
                                        ? "aspect-[3/2]"
                                        : "aspect-square"
                                    }`}
                                  >
                                    Unavailable
                                  </div>
                                );
                              }

                              return (
                                <div key={`album-${photo.id}`} ref={node => {
                                  if (node) photoElementRefs.current.set(photo.id, node);
                                  else photoElementRefs.current.delete(photo.id);
                                }} data-album-photo-id={photo.id}
                                  onContextMenuCapture={() => activateAlbumPhoto(photo)}
                                  data-album-action-target={albumActionTarget?.photo.id === photo.id || undefined}
                                  className={`group/photo relative ${photoSelected || jumpHighlightedMessageId === photo.id ? "z-10 ring-2 ring-inset ring-blue-500" : albumActionTarget?.photo.id === photo.id ? "ring-1 ring-inset ring-blue-400" : ""}`}>
                                <div
                                  className={`group/media block w-full cursor-zoom-in overflow-hidden bg-slate-100 ${
                                    photoGroup.members
                                      .length === 2
                                      ? "aspect-[3/2]"
                                      : "aspect-square"
                                  }`}
                                >
                                  <InboxPhotoImage
                                    reference={photoReference}
                                    src={photoUrl}
                                    previewSrc={localImagePreview(photo)}
                                    onOpen={() => {
                                      activateAlbumPhoto(photo);
                                      setImagePreview({ src: localImagePreview(photo) || photoUrl,
                                        alt: getMessageSummary(photo), reference: photoReference });
                                    }}
                                    alt={
                                      photo.message_text ||
                                      "Photo"
                                    }
                                    className="h-full w-full object-cover transition duration-200 group-hover/media:scale-[1.02]"
                                  />
                                </div>
                                <div className="absolute inset-x-1 top-1 flex items-center justify-between gap-1 opacity-0 transition-opacity group-hover/photo:opacity-100 focus-within:opacity-100 [@media(hover:none)]:opacity-100">
                                  <div onClickCapture={() => activateAlbumPhoto(photo)}>
                                    <ImageCopyButton src={photoUrl} reference={photoReference} iconOnly label={`Copy photo ${photoIndex + 1}`} />
                                  </div>
                                  {canReplyToPhoto ? <button type="button"
                                    aria-label={`${photoSelected ? "Cancel reply to" : "Reply to"} photo ${photoIndex + 1}`}
                                    title={photoSelected ? "Cancel reply" : "Reply to this photo"}
                                    onClick={event => {
                                      event.stopPropagation();
                                      activateAlbumPhoto(photo);
                                      if (isTelegramMessage) {
                                        if (photoSelected) onCancelTelegramReply(); else onReplyToTelegramMessage(photo.id);
                                      } else {
                                        if (photoSelected) onCancelFacebookReply(); else onReplyToFacebookMessage(photo.id);
                                      }
                                    }}
                                    className="touch-manipulation flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-slate-200 bg-white/95 text-slate-600 shadow-sm hover:bg-white hover:text-blue-600 focus-visible:outline-2 focus-visible:outline-blue-500">
                                    <ReplyIcon />
                                  </button> : null}
                                </div>
                                </div>
                              );
                            })}

                            {/*
                              The album's caption, which Telegram keeps on the
                              first photo and shows under the whole group.

                              This branch draws the grid in place of the usual
                              text, so without it the agent's own message was
                              invisible in TENH while the customer could read it
                              perfectly well in Telegram. The placeholder labels
                              the other photos carry are skipped -- they are
                              filing, not something anyone wrote.
                            */}
                            {(() => {
                              const albumCaption = photoGroupCaption(photoGroup.members);

                              if (
                                !albumCaption ||
                                /^\[(image|photo|video)\]$/i.test(albumCaption) ||
                                albumCaption ===
                                  "Sent a photo" ||
                                albumCaption ===
                                  "Sent a video" ||
                                albumCaption ===
                                  "Message deleted"
                              ) {
                                return null;
                              }

                              return (
                                <p
                                  className={`col-span-full whitespace-pre-wrap break-words px-4 pt-2 text-sm leading-6 ${
                                    isOutgoing
                                      ? "text-white"
                                      : "text-slate-700"
                                  }`}
                                >
                                  {albumCaption}
                                </p>
                              );
                            })()}
                          </PhotoAlbumFrame>
                        ) : isImageMessage ? (
                          <div className="group/photo relative w-[300px] max-w-full overflow-hidden rounded-[22px] bg-slate-100 ring-1 ring-slate-200/70">
                            {attachmentUrl ? (
                              <div
                                className="group/media block w-full cursor-zoom-in text-left"
                              >
                                <InboxPhotoImage
                                  reference={{conversationId:message.conversation_id,messageId:message.id}}
                                  src={attachmentUrl}
                                  layout="single" previewSrc={localImagePreview(message)}
                                  onOpen={() => setImagePreview({ src: localImagePreview(message) || attachmentUrl,
                                    alt: attachmentName, reference: { conversationId: message.conversation_id, messageId: message.id } })}
                                  alt={attachmentName}
                                  className="max-h-[360px] w-full object-cover transition duration-200 group-hover/media:scale-[1.01]"
                                />
                              </div>
                            ) : (
                              <div className="flex h-40 w-full items-center justify-center rounded-[22px] border border-dashed border-slate-300 bg-slate-50 text-sm font-medium text-slate-500">
                                Photo unavailable
                              </div>
                            )}
                            {attachmentUrl ? <ImageCopyButton src={attachmentUrl} reference={{ conversationId: message.conversation_id, messageId: message.id }}
                              className="absolute right-2 top-2 opacity-0 transition-opacity group-hover/photo:opacity-100 focus-within:opacity-100 [@media(hover:none)]:opacity-100" /> : null}
                          </div>
                        ) : isAnimationMessage ? (
                          <div className="min-w-[220px]">
                            {attachmentUrl ? (
                              animationMeta?.format ===
                              "gif" ? (
                                <img decoding="async"
                                  src={attachmentUrl}
                                  alt={attachmentName}
                                  className="max-h-80 max-w-full rounded-xl object-contain"
                                  loading="lazy"
                                />
                              ) : (
                                <video
                                  src={attachmentUrl}
                                  autoPlay
                                  loop
                                  muted
                                  playsInline
                                  className="max-h-80 w-full rounded-xl bg-black object-contain"
                                />
                              )
                            ) : (
                              <div className="flex h-40 min-w-[240px] items-center justify-center rounded-xl border border-slate-200 bg-slate-50 text-sm font-medium text-slate-500">
                                Animation sent
                              </div>
                            )}

                            <p className="mt-2 truncate text-xs text-slate-500">
                              {attachmentName}
                            </p>
                          </div>
                        ) : isVideoMessage ? (
                          /*
                           * The video spans the bubble instead of sitting in a
                           * framed card inside it. Negative margins cancel the
                           * bubble's own padding, which was drawing a thick
                           * band of bubble colour on all four sides; the
                           * bubble clips the corners itself. The top offset is
                           * skipped when a reply preview sits above, or the
                           * video would ride over it.
                           */
                          <div
                            className={`-mx-4 mb-1 overflow-hidden bg-black ${
                              telegramReplyPreview
                                ? "mt-1"
                                : "-mt-3"
                            }`}
                          >
                            {attachmentUrl ? (
                              <video
                                src={attachmentUrl}
                                controls
                                preload="metadata"
                                playsInline
                                className="aspect-video w-full bg-black object-contain"
                              />
                            ) : (
                              <div className="flex aspect-video w-full items-center justify-center bg-slate-900 text-sm font-medium text-slate-300">
                                Video unavailable
                              </div>
                            )}
                          </div>
                        ) : isAudioMessage ||
                          isVoiceMessage ? (
                          attachmentUrl ? (
                            <CompactAudioPlayer
                              key={attachmentUrl}
                              src={attachmentUrl}
                              recoverySrc={`/api/inbox/message-audio?conversationId=${encodeURIComponent(message.conversation_id)}&messageId=${encodeURIComponent(message.id)}`}
                              label={attachmentName}
                              isVoice={isVoiceMessage || (isAudioMessage && isOutgoing)}
                              isOutgoing={isOutgoing}
                            />
                          ) : (
                            <div className="flex w-[246.5px] max-w-full items-center gap-[10.2px] rounded-[13.6px] border border-slate-200 bg-white/90 p-[10.2px]">
                              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-sky-50 text-sky-600">
                                <VoiceIcon />
                              </span>
                              <div className="min-w-0">
                                <p className="truncate text-sm font-semibold text-slate-700">
                                  {isVoiceMessage
                                    ? "Voice message"
                                    : attachmentName}
                                </p>
                                <p className="mt-0.5 text-xs text-slate-400">
                                  Audio unavailable
                                </p>
                              </div>
                            </div>
                          )
                        ) : isFileMessage ? (
                          /*
                           * No card of its own. The bubble is already a
                           * container; a bordered white panel inside it
                           * doubled the padding and, on an outgoing message,
                           * dropped a white box onto the blue.
                           */
                          attachmentUrl ? (
                            <a
                              href={attachmentUrl}
                              target="_blank"
                              rel="noreferrer"
                              className={`flex w-[228px] max-w-full items-center gap-2.5 rounded-lg px-1 py-0.5 transition ${
                                isOutgoing
                                  ? "hover:bg-white/10"
                                  : "hover:bg-slate-100"
                              }`}
                            >
                              <span
                                className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                                  isOutgoing
                                    ? "bg-white/20 text-white"
                                    : "bg-sky-50 text-sky-600"
                                }`}
                              >
                                <FileIcon />
                              </span>

                              <span className="min-w-0 flex-1">
                                <span
                                  className={`block truncate text-[13px] font-semibold ${
                                    isOutgoing
                                      ? "text-white"
                                      : "text-slate-800"
                                  }`}
                                >
                                  {attachmentName}
                                </span>
                                <span
                                  className={`block truncate text-[11px] ${
                                    isOutgoing
                                      ? "text-white/70"
                                      : "text-slate-400"
                                  }`}
                                >
                                  {[
                                    attachmentMeta?.mime_type?.split("/").pop()?.toUpperCase(),
                                    formatAttachmentSize(attachmentMeta?.size),
                                  ]
                                    .filter(Boolean)
                                    .join(" · ") || "Telegram file"}
                                </span>
                              </span>
                            </a>
                          ) : (
                            <div className="flex w-[228px] max-w-full items-center gap-2.5 px-1 py-0.5">
                              <span
                                className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                                  isOutgoing
                                    ? "bg-white/20 text-white"
                                    : "bg-slate-100 text-slate-400"
                                }`}
                              >
                                <FileIcon />
                              </span>

                              <span className="min-w-0 flex-1">
                                <span
                                  className={`block truncate text-[13px] font-semibold ${
                                    isOutgoing
                                      ? "text-white"
                                      : "text-slate-800"
                                  }`}
                                >
                                  {attachmentName}
                                </span>
                                <span
                                  className={`block truncate text-[11px] ${
                                    isOutgoing
                                      ? "text-white/70"
                                      : "text-slate-400"
                                  }`}
                                >
                                  Unavailable
                                </span>
                              </span>
                            </div>
                          )
                        ) : (
                          /*
                           * Important:
                           * outgoing Facebook comment replies do not
                           * necessarily have post_id in raw_payload.
                           * Always render their message text here.
                           */
                          <p className="whitespace-pre-wrap">
                            {message.message_text ??
                              "Unsupported message"}
                          </p>
                        )}

                        <div
                          className={`flex items-center gap-2 text-xs ${
                            isBareSticker
                              ? "mt-1 px-1"
                              : "mt-1"
                          } ${
                            isOutgoing
                              ? "justify-end"
                              : "justify-start"
                          }`}
                        >
                          <span
                            className={
                              onColoredBubble
                                ? "text-white/75"
                                : "text-slate-500"
                            }
                          >
                            <HydrationSafeMessageTime
                              value={messageTimestamp}
                            />
                          </span>

                          {telegramEdited &&
                          !telegramDeleted ? (
                            <span
                              className={
                                onColoredBubble
                                  ? "text-white/70"
                                  : "text-slate-400"
                              }
                            >
                              Edited
                            </span>
                          ) : null}

                          {isOutgoing &&
                          !telegramDeleted ? (
                            optimisticStatus ===
                            "sending" ? (
                              <span
                                className={`inline-flex items-center gap-1 ${
                                  onColoredBubble
                                    ? "text-white/80"
                                    : "text-slate-500"
                                }`}
                              >
                                <span className="h-2.5 w-2.5 animate-spin rounded-full border border-white/60 border-t-transparent" />
                                Sending...
                              </span>
                            ) : optimisticStatus ===
                              "failed" ? (
                              <>
                                <span
                                  className={`font-medium ${
                                    onColoredBubble
                                      ? "text-white"
                                      : "text-red-600"
                                  }`}
                                >
                                  {messageStatus.__optimistic_requires_review ? "Delivery unconfirmed" : "Failed to send"}
                                </span>

                                {onRetryMessage && !messageStatus.__optimistic_requires_review ? (
                                  <button
                                    type="button"
                                    onClick={() =>
                                      onRetryMessage(
                                        message.id,
                                      )
                                    }
                                    className={`font-semibold underline underline-offset-2 hover:opacity-90 ${
                                      onColoredBubble
                                        ? "text-white"
                                        : "text-red-600"
                                    }`}
                                  >
                                    Retry
                                  </button>
                                ) : null}
                              </>
                            ) : isTelegramMessage ? (
                              <span
                                className={`font-medium ${
                                  onColoredBubble
                                    ? "text-white/85"
                                    : "text-slate-500"
                                }`}
                                title="Accepted by Telegram Bot API. Telegram does not provide delivery/read receipts for this private bot chat."
                              >
                                ✓ Sent
                              </span>
                            ) : persistedDeliveryStatus ===
                              "seen" ? (
                              <span
                                className={`font-normal ${
                                  onColoredBubble
                                    ? "text-white"
                                    : "text-slate-600"
                                }`}
                                title="Seen"
                              >
                                ✓✓ Seen
                              </span>
                            ) : persistedDeliveryStatus ===
                              "delivered" ? (
                              <span
                                className={`font-medium ${
                                  onColoredBubble
                                    ? "text-white/85"
                                    : "text-slate-500"
                                }`}
                                title="Delivered"
                              >
                                ✓✓ Delivered
                              </span>
                            ) : (
                              <span
                                className={`font-medium ${
                                  onColoredBubble
                                    ? "text-white/85"
                                    : "text-slate-500"
                                }`}
                              >
                                ✓ Sent
                              </span>
                            )
                          ) : null}
                        </div>
                      </div>

                      {/* Facebook Comment Actions */}
                    </div>

                    {albumActionTarget && photoGroup ? <p className={`mt-1 px-1 text-[10px] font-medium text-slate-500 ${isOutgoing ? "text-right" : ""}`}>
                      Photo {photoGroup.members.findIndex(photo => photo.id === albumActionTarget.photo.id) + 1}
                    </p> : null}
                    <MessengerMessageActions
                      key={albumActionTarget?.message.id ?? message.id}
                      message={albumActionTarget?.message ?? message}
                      copyControl={albumActionTarget?.photo.attachment_url ? <ImageCopyButton
                        key={albumActionTarget.photo.id}
                        src={albumActionTarget.photo.attachment_url}
                        reference={{ conversationId: albumActionTarget.photo.conversation_id, messageId: albumActionTarget.photo.id }}
                        className="max-w-full"
                      /> : undefined}
                      platform={activeConversation.social_account?.platform}
                      onMessagePatched={onMessagePatched}
                      outgoing={isOutgoing}
                      keepVisible={Boolean(albumActionTarget)}
                      reserveActions={albumActionTarget && isOutgoing && !isDeletedMessage && !isFacebookCommentMessage && ["facebook", "messenger", "telegram"].includes(activeConversation.social_account?.platform ?? "") ? {
                        reply: true, pin: true, edit: false,
                        delete: activeConversation.social_account?.platform === "telegram" || isTelegramMessage,
                      } : undefined}
                      reserveReaction={Boolean(albumActionTarget && isOutgoing && !isDeletedMessage && !isFacebookCommentMessage && ["facebook", "messenger"].includes(activeConversation.social_account?.platform ?? ""))}
                      actions={albumActionTarget ? { ...messageActions, reply: getMessageActions(albumActionTarget.photo, activeConversation.social_account?.platform).reply } : messageActions}
                      replying={albumActionTarget ? (replyingToFacebookMessageId ?? replyingToTelegramMessageId) === replyActionId : isTelegramReplyTarget}
                      pinned={pinnedMessages.pins.some((item) => item.id === message.id) || isMessagePinned(message)}
                      pinPending={pinnedMessages.pendingIds.has(message.id)}
                      onReply={() => {
                        if (isTelegramMessage) {
                          if (replyingToTelegramMessageId === replyActionId) onCancelTelegramReply();
                          else onReplyToTelegramMessage(replyActionId);
                        } else {
                          if (replyingToFacebookMessageId === replyActionId) onCancelFacebookReply();
                          else onReplyToFacebookMessage(replyActionId);
                        }
                      }}
                      onPin={() => void toggleMessagePin(message, !(pinnedMessages.pins.some((item) => item.id === message.id) || isMessagePinned(message)))}
                      onEdit={() => void onEditTelegramMessage(message.id, message.message_text ?? "")}
                      onDelete={() => {
                        const album = photoGroups.get(message.id);
                        setTelegramDeleteTarget(album ? album.members.map((photo) => photo.id) : [message.id]);
                      }}
                    />

                    <div>

                      {showCommentActions ? (
                        <div data-comment-actions className="flex items-center gap-1 border-t border-slate-100 px-2 py-1.5">

                          {!isOutgoing ? (
                            <>
                          {/* Like / Unlike */}
                          <div className="group/action relative">
                          <button
                            type="button"
                            disabled={
                              commentState.deleted
                            }
                            onClick={() =>
                              void toggleLike()
                            }
                            className={`flex h-7 w-7 items-center justify-center rounded-md transition active:scale-90 ${
                              commentState.liked
                                ? "bg-blue-50 text-blue-600"
                                : "text-slate-400 hover:bg-blue-50 hover:text-blue-600"
                            } disabled:cursor-not-allowed disabled:opacity-30`}
                            title={
                              commentState.liked
                                ? "Unlike comment"
                                : "Like comment"
                            }
                            aria-label={
                              commentState.liked
                                ? "Unlike comment"
                                : "Like comment"
                            }
                          >
                            <LikeIcon />
                          </button>
                          <ActionTooltip
                            label={
                              commentState.liked
                                ? isKhmer ? "ដកការចូលចិត្ត" : "Unlike"
                                : isKhmer ? "ចូលចិត្ត" : "Like"
                            }
                          />
                          </div>

                          {/* Reply */}
                          <div className="group/action relative">
                          <button
                            type="button"
                            disabled={
                              isCommentReplyBlocked(message.platform_message_id, messages, optimisticCommentState)
                            }
                            onClick={() => {
                              onReplyToComment(
                                message.platform_message_id,
                              );
                            }}
                            className={`flex h-7 w-7 items-center justify-center rounded-md transition active:scale-90 disabled:cursor-not-allowed disabled:opacity-30 ${
                              isReplyTarget
                                ? "bg-blue-50 text-blue-600"
                                : "text-slate-400 hover:bg-blue-50 hover:text-blue-600"
                            }`}
                            title={
                              isReplyTarget
                                ? "Reply target selected"
                                : "Reply to comment"
                            }
                            aria-label={
                              isReplyTarget
                                ? "Reply target selected"
                                : "Reply to comment"
                            }
                          >
                            <ReplyIcon />
                          </button>
                          <ActionTooltip
                            label={
                              isReplyTarget
                                ? isKhmer ? "បានជ្រើស" : "Selected"
                                : isKhmer ? "ឆ្លើយតប" : "Reply"
                            }
                          />
                          </div>

                          {/* Hide / Unhide */}
                          <div className="group/action relative">
                          <button
                            type="button"
                            disabled={
                              commentState.deleted
                            }
                            onClick={() =>
                              setCommentConfirmTarget({
                                kind: commentState.hidden
                                  ? "unhide"
                                  : "hide",
                                messageId: message.id,
                                platformMessageId:
                                  message.platform_message_id,
                                previous: {
                                  ...commentState,
                                },
                              })
                            }
                            className={`flex h-7 w-7 items-center justify-center rounded-md transition active:scale-90 ${
                              commentState.hidden
                                ? "bg-amber-50 text-amber-600"
                                : "text-slate-400 hover:bg-amber-50 hover:text-amber-600"
                            } disabled:cursor-not-allowed disabled:opacity-30`}
                            title={
                              commentState.hidden
                                ? "Unhide comment"
                                : "Hide comment"
                            }
                            aria-label={
                              commentState.hidden
                                ? "Unhide comment"
                                : "Hide comment"
                            }
                          >
                            <HideIcon />
                          </button>
                          <ActionTooltip
                            label={
                              commentState.hidden
                                ? isKhmer ? "បង្ហាញវិញ" : "Unhide"
                                : isKhmer ? "លាក់" : "Hide"
                            }
                          />
                          </div>
                          </>
                          ) : null}

                          {/* Delete */}
                          <div className="group/action relative">
                          <button
                            type="button"
                            disabled={
                              commentState.deleted
                            }
                            onClick={() =>
                              setCommentConfirmTarget({
                                kind: "delete",
                                messageId: message.id,
                                platformMessageId:
                                  message.platform_message_id,
                                previous: {
                                  ...commentState,
                                },
                              })
                            }
                            className="flex h-7 w-7 items-center justify-center rounded-md text-slate-400 transition hover:bg-red-50 hover:text-red-600 active:scale-90 disabled:cursor-not-allowed disabled:opacity-30"
                            title={
                              isOutgoing
                                ? "Delete reply"
                                : "Delete comment"
                            }
                            aria-label={
                              isOutgoing
                                ? "Delete reply"
                                : "Delete comment"
                            }
                          >
                            <svg
                              viewBox="0 0 24 24"
                              fill="none"
                              stroke="currentColor"
                              strokeWidth="1.8"
                              className="h-4 w-4"
                              aria-hidden="true"
                            >
                              <path
                                d="M4 7h16"
                                strokeLinecap="round"
                              />
                              <path
                                d="M9 7V4h6v3"
                                strokeLinecap="round"
                              />
                              <path
                                d="M6 7l1 13h10l1-13"
                                strokeLinecap="round"
                                strokeLinejoin="round"
                              />
                            </svg>
                          </button>
                          <ActionTooltip
                            label={
                              isOutgoing
                                ? isKhmer ? "លុបការឆ្លើយតប" : "Delete reply"
                                : isKhmer ? "លុប" : "Delete"
                            }
                          />
                          </div>
                        </div>
                      ) : null}
                    </div>
                  </div>
                </div>
                </Fragment>
              );
            }}
            </DeferredInboxItem>;
          })}
          {messengerSources.after.map((source) => (
            <MessengerSourceCard key={source.key} source={source} onOpenImage={setImagePreview} />
          ))}
          </div>
        </MessageScrollSurface>

        {newMessageCount > 0 ? (
          <div className="pointer-events-none absolute bottom-4 left-1/2 z-40 -translate-x-1/2">
            <button
              type="button"
              onClick={() =>
                scrollToNewest(
                  "smooth",
                )
              }
              className="pointer-events-auto inline-flex items-center gap-2 rounded-full border border-blue-200 bg-white px-4 py-2 text-sm font-semibold text-blue-700 shadow-lg transition hover:bg-blue-50 active:scale-[0.98]"
              aria-label="Scroll to newest messages"
            >
              <span className="flex h-5 min-w-5 items-center justify-center rounded-full bg-blue-600 px-1.5 text-[11px] font-bold text-white">
                {newMessageCount}
              </span>

              <span>
                {newMessageCount === 1
                  ? isKhmer ? "សារថ្មី" : "New message"
                  : isKhmer ? "សារថ្មី" : "New messages"}
              </span>

              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                className="h-4 w-4"
                aria-hidden="true"
              >
                <path
                  d="m6 9 6 6 6-6"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          </div>
        ) : showScrollToLatest ? (
          <div className="pointer-events-none absolute bottom-4 right-4 z-40">
            <button
              type="button"
              onClick={() =>
                scrollToNewest(
                  "smooth",
                )
              }
              className="pointer-events-auto inline-flex h-10 items-center gap-2 rounded-full border border-slate-200 bg-white px-3.5 text-xs font-semibold text-slate-700 shadow-[0_8px_24px_rgba(15,23,42,0.14)] transition hover:border-sky-200 hover:bg-sky-50 hover:text-sky-700 active:scale-[0.97]"
              aria-label="Scroll to latest message"
              title="Latest message"
            >
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                className="h-4 w-4"
                aria-hidden="true"
              >
                <path
                  d="m6 9 6 6 6-6"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>

              <span>Latest</span>
            </button>
          </div>
        ) : null}
      </MessageViewportFrame>

      {quotedReplyTarget && !editingTelegramMessageId ? (
        <div className="flex shrink-0 items-center gap-3 border-t border-sky-100 bg-white px-4 py-2">
          {quotedReplyImage ? <ReplyImageThumbnail key={quotedReplyTarget.id} reference={quotedReplyImage} /> :
            quotedReplyVideo ? <ReplyVideoThumbnail key={quotedReplyTarget.id} reference={quotedReplyVideo} /> : null}
          <div className="min-w-0 flex-1 border-l-2 border-sky-400 pl-3">
            <p className="text-xs font-semibold text-sky-700">Replying to {quotedReplyTarget.direction === "outgoing" ? "your message" : activeConversation.contact?.full_name || "customer"}</p>
            <p className="truncate text-sm text-slate-600">{getMessageSummary(quotedReplyTarget)}</p>
            {replyingToFacebookMessageId && <p className="mt-0.5 text-[11px] text-slate-500">{isTelegramPersonal ? "Reply in Telegram" : "Reply in Messenger"}</p>}
          </div>
          <button type="button" aria-label="Cancel message reply" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100" onClick={replyingToFacebookMessageId ? onCancelFacebookReply : onCancelTelegramReply}>×</button>
        </div>
      ) : null}

      {editingTelegramMessageId ? (
        <div className="shrink-0 border-t border-sky-100 bg-sky-50/60 px-4 py-2">
          <div className="flex items-center gap-3 rounded-xl border border-sky-200/80 bg-white px-3 py-2 shadow-sm">
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-sky-50 text-sky-700">
              <EditIcon />
            </div>

            <div className="min-w-0 flex-1">
              <p className="text-xs font-semibold text-sky-700">
                Editing message
              </p>
              <p className="mt-0.5 truncate text-xs text-slate-500">
                {messages.find(
                  (message) =>
                    message.id ===
                    editingTelegramMessageId,
                )?.message_text ??
                  "Edit the message below"}
              </p>
            </div>

            <span className="hidden text-[11px] font-medium text-slate-400 sm:inline">
              {isKhmer ? "ផ្ញើដើម្បីរក្សាទុក" : "Send to save"}
            </span>

            <button
              type="button"
              onClick={onCancelTelegramEdit}
              className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700"
              title="Cancel edit"
              aria-label="Cancel edit"
            >
              ×
            </button>
          </div>
        </div>
      ) : null}

      {/* Facebook comment reply target — UI only. Keep reply behavior unchanged. */}
      {replyingToCommentId ? (
        <div className="shrink-0 bg-white px-3 py-2">
          <div className="flex items-start gap-3 rounded-xl bg-slate-50 px-3 py-2.5 ring-1 ring-inset ring-slate-200">
            <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-white text-blue-600 shadow-sm" aria-hidden="true">
              <ReplyIcon />
            </div>

            <div className="min-w-0 flex-1">
              <div className="flex min-w-0 flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5">
                <p className="min-w-0 truncate text-sm font-semibold leading-5 text-slate-900">
                  {isKhmer ? "កំពុងឆ្លើយតបទៅ" : "Replying to"} {replyingToName}
                </p>
                <p className="text-xs leading-5 text-slate-500">
                  {isKhmer
                    ? "ការឆ្លើយតបលើមតិយោបល់ Facebook អាចផ្ញើបានតែអក្សរប៉ុណ្ណោះ។"
                    : "Facebook comment replies can only contain text."}
                </p>
              </div>
              <p className="mt-1 truncate border-l-2 border-blue-300 pl-2 text-sm leading-5 text-slate-600">
                {replyingToMessage?.message_text ?? "Selected Facebook comment"}
              </p>
            </div>

            <button
              type="button"
              onClick={onCancelCommentReply}
              className="group/action relative flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-slate-400 transition hover:bg-slate-200/60 hover:text-slate-700 focus-visible:outline-2 focus-visible:outline-blue-500"
              title="Cancel reply"
              aria-label="Cancel reply"
            >
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.9"
                className="h-6 w-6"
                aria-hidden="true"
              >
                <path
                  d="M6 6l12 12M18 6 6 18"
                  strokeLinecap="round"
                />
              </svg>

              <ActionTooltip label="Cancel reply" />
            </button>
          </div>
        </div>
      ) : null}


      {/* Reply composer */}
      {activeConversation.contact ? (
        /*
         * V3.11.30.1 — Messenger DMs and Facebook comments can share one
         * thread. The normal composer stays available. Clicking Reply on a
         * comment switches only that send into a targeted comment reply.
         */
        <ReplyBox
          key={`${activeConversation.business_id}:${activeConversation.id}`}
          composerReady={composerReady}
          storageBusinessId={storageBusinessId}
          storageMemberId={storageMemberId}
          conversationId={
            activeConversation.id
          }
          contactId={
            activeConversation.contact.id
          }
          businessId={
            activeConversation.contact
              .business_id
          }

          initialTags={
            activeConversation.contact
              .tags ?? []
          }
          onTagsChange={(tags) =>
            onContactTagsChange?.(
              activeConversation.contact!.id,
              tags,
            )
          }
          typingAgents={
            typingAgents
          }

          reply={reply}
          sending={sending}
          error={sendError}
          blockedReason={isTelegramPersonal ? personalReply.reason ?? (personalReply.loading ? "Checking reply access…" : null) : facebookCustomerBlock.blocked && !replyingToCommentId ? "This customer is blocked on this Facebook Page. Unblock the user in Customer Details before messaging." : replyingToCommentId && isCommentReplyBlocked(replyingToCommentId, messages, optimisticCommentState)
            ? "Unhide this comment and its parent before replying."
            : facebookMessengerBlockedReason}
          blockedTitle={isTelegramPersonal ? (personalReply.loading ? "Telegram Personal" : "Read only") : facebookCustomerBlock.blocked && !replyingToCommentId ? "Customer blocked" : facebookMessengerBlockedTitle}
          canOpenInFacebook={Boolean(
            facebookMessengerBlockedReason &&
              !facebookCustomerBlock.blocked && !replyingToCommentId &&
              activeConversation?.social_account
                ?.platform === "facebook",
          )}
          facebookPageId={
            activeConversation
              ?.social_account
              ?.platform_account_id ?? null
          }
          facebookThreadId={
            activeConversation
              ?.contact
              ?.platform_user_id ?? null
          }

          onReplyChange={
            onReplyChange
          }
          onSubmit={
            onSendMessage
          }
          canCaptionAttachments={
            activeConversation
              ?.social_account
              ?.platform === "telegram" || isTelegramPersonal
          }
          platform={activeConversation?.social_account?.platform}
          onSendSticker={onSendSticker}
          onSendAttachments={
            onSendAttachments
          }
          /* Only a targeted public comment reply is text-only. */
          allowAttachments={!replyingToCommentId}
          showAttachmentsBlockedNotice={false}
          attachmentsBlockedReason={
            replyingToCommentId
              ? isKhmer
                ? "ការឆ្លើយតបលើមតិយោបល់ Facebook អាចផ្ញើបានតែអក្សរប៉ុណ្ណោះ។"
                : "Facebook comment replies can only contain text."
              : null
          }

        />
      ) : null}

      {imagePreview ? (
        <div
          className="fixed inset-0 z-[120] flex items-center justify-center bg-slate-950/80 p-4 backdrop-blur-[2px] sm:p-8"
          data-media-viewer
          role="dialog"
          aria-modal="true"
          aria-label="Image preview"
          onMouseDown={(event) => {
            if (event.target === event.currentTarget) {
              setImagePreview(null);
            }
          }}
        >
          <div
            className="relative flex max-h-[92vh] max-w-[94vw] items-center justify-center"
            onMouseDown={(event) => event.stopPropagation()}
          >
            <InboxPhotoImage layout="preview" reference={imagePreview.reference}
              src={imagePreview.src}
              alt={imagePreview.alt}
              className="max-h-[92vh] max-w-[94vw] rounded-2xl object-contain shadow-2xl"
            />

            <ImageCopyButton key={imagePreview.src} src={imagePreview.src} reference={imagePreview.reference} shortcut
              className="absolute bottom-3 left-3" />
            <button
              type="button"
              onClick={() => setImagePreview(null)}
              className="absolute right-2 top-2 flex h-10 w-10 items-center justify-center rounded-full bg-black/55 text-2xl leading-none text-white shadow-lg transition hover:bg-black/75"
              aria-label="Close image preview"
              title="Close"
            >
              ×
            </button>
          </div>
        </div>
      ) : null}

    </section>
  );
}

