"use client";

import {
  useEffect,
  useRef,
  useState,
  type ChangeEvent,
  type ClipboardEvent,
  type FormEvent,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react";


import { Database as StorageIcon, Send } from "lucide-react";
import { clipboardImageFiles } from "@/lib/inbox/image-clipboard";
import {
  DIRECT_ATTACHMENT_ACCEPT,
  selectAttachments,
} from "@/lib/inbox/attachment-selection";
import { WorkspaceStorageModal } from "./workspace-storage-modal";
import { createClient } from "@/lib/supabase/client";
import { clearWorkspaceStorageCache, workspaceStorageCacheKey } from "@/lib/storage/workspace-storage-cache";
import { TenhStickerPicker } from "./tenh-sticker-picker";
import type { TelegramStickerChoice } from "@/lib/telegram/sticker-catalog";
import type { InboxStickerChoice } from "@/lib/stickers/catalog";

import { CustomerTagSelector } from "@/components/inbox/customer-tag-selector";
import {
  LocationPickerDialog,
  type PickedLocation,
} from "@/components/inbox/location-picker-dialog";
import { SavedReplySelector } from "@/components/inbox/saved-reply-selector";
import { useOnlineStatus } from "@/lib/inbox/use-online-status";
import {
  useWorkspaceLanguageId,
} from "@/components/display/workspace-language-text";

import type {
  SavedReplyAttachment,
  ConversationStatus,
  CustomerTag,
} from "@/types/inbox";

import type {
  AgentPresence,
} from "@/lib/inbox/use-agent-presence";

export type ReplyAttachmentKind =
  | "image"
  | "video"
  | "audio"
  | "file";

export type ReplyAttachment = {
  id: string;
  file: File;
  previewUrl: string;
  kind: ReplyAttachmentKind;
};

type ReplyBoxProps = {
  storageBusinessId: string;
  storageMemberId: string;
  platform?: string;
  onSendSticker?: (sticker: InboxStickerChoice) => Promise<boolean>;
  reply: string;
  composerReady?: boolean;
  conversationId: string;
  sending: boolean;
  error: string | null;
  blockedReason?: string | null;
  blockedTitle?: string | null;
  advisoryReason?: string | null;
  advisoryTitle?: string | null;

  /*
   * Offered inside the blocked notice, and only when the block is Meta's
   * messaging window on a Facebook conversation. It opens Facebook; it does
   * not lift the window, and TENH's composer stays disabled either way.
   */
  canOpenInFacebook?: boolean;
  facebookPageId?: string | null;
  facebookThreadId?: string | null;

  contactId: string;
  businessId: string;
  initialTags: CustomerTag[];
  typingAgents?: AgentPresence[];

  onTagsChange?: (
    tags: CustomerTag[],
  ) => void;

  allowAttachments?: boolean;

  onReplyChange: (value: string) => void;

  onSubmit: (
    event: FormEvent<HTMLFormElement>,
    capturedMessage?: string,
  ) => void | Promise<void>;

  /*
   * `text` is everything typed; the parent decides whether it travels as a
   * Telegram caption or follows the media as its own message. `onQueued` fires
   * once every outgoing item has its own bubble on screen.
   */
  onSendAttachments?: (
    attachments: ReplyAttachment[],
    text?: string,
    options?: { onQueued?: () => void },
  ) => Promise<boolean>;

  /*
   * Whether this channel can carry the typed message with the media.
   * Telegram can, as an album caption; Messenger cannot, because Meta sends one
   * attachment per message with no caption field at all.
   */
  canCaptionAttachments?: boolean;

  /*
   * Why attachments cannot be sent here, if they cannot. Set for Facebook
   * comment threads, which take replies as text only.
   */
  attachmentsBlockedReason?: string | null;
  showAttachmentsBlockedNotice?: boolean;

  onStatusChange?: (
    status: ConversationStatus,
  ) => void;
};

const TENH_ATTACHMENT_LIMITS = {
  image: 10 * 1024 * 1024,
  video: 50 * 1024 * 1024,
  audio: 25 * 1024 * 1024,
  file: 25 * 1024 * 1024,
} satisfies Record<
  ReplyAttachmentKind,
  number
>;

function createId() {
  if (
    typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
  ) {
    return crypto.randomUUID();
  }

  return `${Date.now()}-${Math.random()}`;
}

function AudioIcon() {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      className="h-5 w-5"
      aria-hidden="true"
    >
      <path
        d="M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3Z"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path
