function formatFileSize(bytes: number) {
  if (bytes < 1024) {
    return `${bytes} B`;
  }

  if (bytes < 1024 * 1024) {
    return `${(bytes / 1024).toFixed(1)} KB`;
  }

  return `${(
    bytes /
    (1024 * 1024)
  ).toFixed(1)} MB`;
}

function formatVoiceDuration(seconds: number) {
  const safeSeconds = Math.max(0, Math.floor(seconds));
  const minutes = Math.floor(safeSeconds / 60);
  const remainingSeconds = safeSeconds % 60;

  return `${minutes}:${String(remainingSeconds).padStart(2, "0")}`;
}

export function ReplyBox({
  storageBusinessId,
  storageMemberId,
  platform, onSendSticker,
  reply,
  sending,
  error,
  blockedReason = null,
  blockedTitle = null,
  advisoryReason = null,
  advisoryTitle = null,
  contactId,
  businessId,
  initialTags,
  typingAgents = [],
  onTagsChange,
  conversationId,
  composerReady = true,
  allowAttachments = true,
  onReplyChange,
  onSubmit,
  onSendAttachments,
  attachmentsBlockedReason = null,
  showAttachmentsBlockedNotice = true,
  onStatusChange,
}: ReplyBoxProps) {
  const isKhmer = useWorkspaceLanguageId() === "km";
  useEffect(() => {
    workspaceStorageCacheKey(storageBusinessId, storageMemberId);
    const { data: { subscription } } = createClient().auth.onAuthStateChange((event) => {
      if (event === "SIGNED_OUT") clearWorkspaceStorageCache();
    });
    return () => subscription.unsubscribe();
  }, [storageBusinessId, storageMemberId]);
  const [nativeSticker, setNativeSticker] = useState<TelegramStickerChoice | null>(null);
  const [stickerSending, setStickerSending] = useState(false);
  const [stickerNotice, setStickerNotice] = useState<string | null>(null);
  const stickerFlight = useRef(false);
  const stickerScope = useRef(0);
  useEffect(() => {
    stickerScope.current++; setNativeSticker(null); setStickerSending(false); setStickerNotice(null); stickerFlight.current = false;
    return () => { stickerScope.current++; };
  }, [conversationId, platform]);

  const [sendingContent, setSendingContent] =
    useState(false);

  const [
    loadingQuickReplyMedia,
    setLoadingQuickReplyMedia,
  ] = useState(false);

  const isSending =
    sending || sendingContent;

  const { online } = useOnlineStatus();

  const isComposerBlocked =
    Boolean(blockedReason);

  /*
   * Sending no longer locks the composer.
   *
   * It used to disable the whole thing until the request came back, so an
   * agent replying quickly had to wait out each message before writing the
   * next -- and a slow channel made the inbox feel stuck. Nothing needs the
   * lock: the box is cleared before the request is sent, so a second send
   * carries new text rather than repeating the last, and each send tracks its
   * own optimistic bubble.
   *
   * Only a genuinely blocked channel disables it now.
   */
  const isComposerDisabled =
    isComposerBlocked || !composerReady;

  /*
   * Only the send is held while a quick reply's media loads -- the agent can
   * still type, and often wants to add a line before sending.
   */
  /*
   * Offline blocks the send, not the writing.
   *
   * A send with no connection fails somewhere in the fetch and leaves the
   * agent guessing whether the customer got it. Refusing up front is honest,
   * and keeping the box editable means the reply they were part-way through is
   * still there -- and still sendable the moment the connection returns.
   */
  const isSendDisabled =
    isComposerDisabled ||
    loadingQuickReplyMedia ||
    stickerSending ||
    !online;

  /*
   * Said before the work, not after it.
   *
   * A comment thread rejects attachments at the API, so an agent could pick
   * files, wait for them to upload and only then be told -- with their message
   * still in the box. Turning the controls off up front costs them nothing and
   * says why.
   */
  const attachmentsBlocked = Boolean(
    attachmentsBlockedReason,
  );

  const [moreOpen, setMoreOpen] =
    useState(false);

  const attachmentInputRef =
    useRef<HTMLInputElement | null>(null);

  const attachmentTriggerRef =
    useRef<HTMLButtonElement | null>(null);

  const attachmentMenuRef =
    useRef<HTMLDivElement | null>(null);

  const replyInputRef =
    useRef<HTMLTextAreaElement | null>(null);

  const [attachments, setAttachments] =
    useState<ReplyAttachment[]>([]);
  const attachmentsRef = useRef(attachments);
  attachmentsRef.current = attachments;
  const composerMountedRef = useRef(true);
  useEffect(() => {
    composerMountedRef.current = true;
    return () => {
      composerMountedRef.current = false;
      for (const attachment of attachmentsRef.current) URL.revokeObjectURL(attachment.previewUrl);
    };
  }, []);

  const [storageConversationId, setStorageConversationId] =
    useState<string | null>(null);
  const storageOpen = storageConversationId === conversationId;

  const attachmentConversationRef =
    useRef(conversationId);

  useEffect(() => {
    if (!moreOpen) return;

    const focusFrame = window.requestAnimationFrame(() => {
      attachmentMenuRef.current
        ?.querySelector<HTMLButtonElement>('[role="menuitem"]')
        ?.focus();
    });
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      setMoreOpen(false);
      setActiveToolbarPanel(null);
      attachmentTriggerRef.current?.focus();
    };

    window.addEventListener("keydown", closeOnEscape);
    return () => {
      window.cancelAnimationFrame(focusFrame);
      window.removeEventListener("keydown", closeOnEscape);
    };
  }, [moreOpen]);

  function navigateAttachmentMenu(event: ReactKeyboardEvent<HTMLDivElement>) {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const items = Array.from(
      attachmentMenuRef.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]') ?? [],
    );
    if (!items.length) return;
    event.preventDefault();
    const current = items.indexOf(document.activeElement as HTMLButtonElement);
    const next = event.key === "Home"
      ? 0
      : event.key === "End"
        ? items.length - 1
        : event.key === "ArrowUp"
          ? (current <= 0 ? items.length - 1 : current - 1)
          : (current + 1) % items.length;
    items[next]?.focus();
  }

  useEffect(() => {
    if (attachmentConversationRef.current === conversationId) return;
    attachmentConversationRef.current = conversationId;
    const reset = window.requestAnimationFrame(() => {
      setStorageConversationId(null);
      setAttachments((current) => {
        for (const attachment of current) {
          URL.revokeObjectURL(attachment.previewUrl);
        }
        return [];
      });
    });
    return () => window.cancelAnimationFrame(reset);
  }, [conversationId]);

  /*
   * Bring a quick reply's media into the composer as ordinary attachments.
   *
   * They become exactly what a hand-picked file becomes, which is the point:
   * the send path already groups two or more images into one album and sends a
   * video on its own, so quick replies inherit that rather than needing a
   * second way to send. The agent can also review or remove them before
   * sending, the same as anything they attached themselves.
   *
   * The bucket is private, so each file is fetched through a signed link and
   * rebuilt as a File. One that cannot be fetched is skipped: the text is
   * already in the box, and losing an image is better than losing the reply.
   */
  async function loadSavedReplyAttachments(
    savedAttachments: SavedReplyAttachment[],
  ) {
    if (!composerReady || !composerMountedRef.current || savedAttachments.length === 0) {
      return;
    }

    /*
     * The reply's text lands in the box at once, but its media has to be
     * fetched -- a signed link per file, then the bytes. Sending during that
     * gap sent the text on its own, and pressing Send again while waiting sent
     * it twice, with the photos arriving afterwards to be sent a third time.
     *
     * Holding the send until the media is here keeps a quick reply what it
     * looks like: one message, whole.
     */
    setLoadingQuickReplyMedia(true);

    /*
     * All at once, and one hop each.
     *
     * These used to be fetched one after another, and each needed two requests
     * -- ask for a signed link, then download. Six photos meant twelve requests
     * in strict sequence, which is why attaching took so long. The list API now
     * signs them in a batch, so the link usually arrives with the reply and
     * only the download is left; running them together turns the wait into
     * roughly the slowest single file rather than the sum of all of them.
     */
    const results = await Promise.all(
      savedAttachments.map(async (saved) => {
        try {
          let signedUrl =
            saved.url ?? null;

          if (!signedUrl) {
            const signedResponse =
              await fetch(
                `/api/saved-replies/media?path=${encodeURIComponent(
                  saved.path,
                )}`,
                { cache: "no-store" },
              );

            const signed =
              (await signedResponse.json()) as {
                success?: boolean;
                url?: string;
              };

            if (
              !signed?.success ||
              !signed.url
            ) {
              return null;
            }

            signedUrl = signed.url;
          }

          const fileResponse =
            await fetch(signedUrl);

          if (!fileResponse.ok) {
            return null;
          }

          const blob =
            await fileResponse.blob();

          /*
           * A saved voice clip goes out as a native voice message, not a music
           * file: the "voice-message-" name is the contract the recorder
           * already uses, which Telegram's send path maps to sendVoice. The
           * extension is kept so the format check still sees MP3/M4A/OGG.
           */
          const extension =
            /\.[a-z0-9]{2,5}$/i.exec(saved.name ?? "")?.[0] ?? "";
          const file = new File(
            [blob],
            saved.kind === "audio"
              ? `voice-message-${Date.now()}${extension}`
              : saved.name || "attachment",
            {
              type:
                saved.mimeType || blob.type,
            },
          );

          return {
            id: createId(),
            file,
            previewUrl:
              URL.createObjectURL(blob),
            kind: saved.kind,
          } as ReplyAttachment;
        } catch {
          /* Skip this one; the reply text still went in. */
          return null;
        }
      }),
    );

    const loaded = results.filter(
      (item): item is ReplyAttachment =>
        item !== null,
    );

    if (!composerMountedRef.current) {
      for (const attachment of loaded) URL.revokeObjectURL(attachment.previewUrl);
      return;
    }

    if (loaded.length > 0) {
      setAttachments((current) => [
        ...current,
        ...loaded,
      ]);
    }

    setLoadingQuickReplyMedia(false);

    /*
     * Say when a file did not arrive.
     *
     * A failed fetch -- an expired signed link, a blip, a storage error --
     * returned null, was filtered out here, and that was the end of it. The
     * text was already in the box and the spinner stopped, so a quick reply
     * meant to carry three product photos looked finished carrying two, and
     * the agent sent an incomplete answer without ever being told one was
     * missing. Nothing downstream could catch it either: the send path only
     * ever sees the attachments that made it.
     *
     * Loud on purpose. This is the same alert the composer already uses when
     * it rejects a file the agent picked, and unlike that case the agent did
     * not choose to leave anything out.
     */
    const missing =
      results.length - loaded.length;

    if (missing > 0) {
      window.alert(
        missing === results.length
          ? `None of this quick reply's ${missing} attachment${
              missing === 1 ? "" : "s"
            } could be loaded. The message text is ready — attach the file${
              missing === 1 ? "" : "s"
            } yourself before sending.`
          : `${missing} of this quick reply's ${results.length} attachments could not be loaded. Check what is attached before sending.`,
      );
    }
  }

  const [locationPickerOpen, setLocationPickerOpen] =
    useState(false);

  const [lastPickedLocation, setLastPickedLocation] =
    useState<PickedLocation | null>(null);

  type SendMode =
    | "now"
    | "close"
    | "pending";

  const [sendMode, setSendMode] =
    useState<SendMode>("now");


  type ToolbarPanel =
    | "quick-tag"
    | "quick-reply"
    | "emoji"
    | "attach"
    | null;

  const [activeToolbarPanel, setActiveToolbarPanel] =
    useState<ToolbarPanel>(null);

  const pendingPostSendStatusRef =
    useRef<ConversationStatus | null>(null);

  const previousSendingRef =
    useRef(sending);

  const [
    recordingVoice,
    setRecordingVoice,
  ] = useState(false);

  const [
    recordingPaused,
    setRecordingPaused,
  ] = useState(false);

  const [
    recordingSeconds,
    setRecordingSeconds,
  ] = useState(0);

  const [
    recordingError,
    setRecordingError,
  ] = useState<string | null>(null);

  const [
    voiceReview,
    setVoiceReview,
  ] = useState<{
    attachmentId: string;
    durationSeconds: number;
  } | null>(null);

  const [
    voiceReviewPlaying,
    setVoiceReviewPlaying,
  ] = useState(false);

  const [
    voicePlaybackSeconds,
    setVoicePlaybackSeconds,
  ] = useState(0);

  const voicePreviewAudioRef =
    useRef<HTMLAudioElement | null>(null);

  const recordingSecondsRef =
    useRef(0);

  const mediaRecorderRef =
    useRef<MediaRecorder | null>(null);

  const mediaStreamRef =
    useRef<MediaStream | null>(null);
  const recordingStartPendingRef = useRef(false);

  const recordedChunksRef =
    useRef<BlobPart[]>([]);

  const recordingTimerRef =
    useRef<ReturnType<typeof setInterval> | null>(
      null,
    );

  const discardRecordingRef =
    useRef(false);
  const sendRecordingRef = useRef<((attachment: ReplyAttachment) => void) | null>(null);

  function closeExpandedChildSelector(
    ariaLabel: "Quick tags" | "Quick replies",
  ) {
    if (typeof document === "undefined") {
      return;
    }

    const trigger = document.querySelector<HTMLButtonElement>(
      `button[aria-label="${ariaLabel}"][aria-expanded="true"]`,
    );

    trigger?.click();
  }

  function dismissToolbarPanels() {

    setMoreOpen(false);

    closeExpandedChildSelector("Quick tags");
    closeExpandedChildSelector("Quick replies");

    if (typeof window !== "undefined") {
      document.dispatchEvent(
        new KeyboardEvent("keydown", {
          key: "Escape",
          bubbles: true,
        }),
      );

      const activeElement =
        document.activeElement;

      if (activeElement instanceof HTMLElement) {
        activeElement.blur();
      }
    }
  }

  function clearToolbarPanel() {
    setActiveToolbarPanel(null);
  }

  /*
   * Keep the two existing selector components mutually exclusive.
   * They own their own open state, so we mirror aria-expanded and
   * close the opposite selector after React finishes its click cycle.
   */
  useEffect(() => {
    if (typeof document === "undefined") {
      return;
    }

    let frame = 0;

    const syncSelectorState = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const quickTagOpen = Boolean(
          document.querySelector(
            'button[aria-label="Quick tags"][aria-expanded="true"]',
          ),
        );
        const quickReplyOpen = Boolean(
          document.querySelector(
            'button[aria-label="Quick replies"][aria-expanded="true"]',
          ),
        );

        if (quickTagOpen && quickReplyOpen) {
          if (activeToolbarPanel === "quick-reply") {
            closeExpandedChildSelector("Quick tags");
          } else {
            closeExpandedChildSelector("Quick replies");
          }
          return;
        }

        if (quickTagOpen) {
          setActiveToolbarPanel("quick-tag");
          return;
        }

        if (quickReplyOpen) {
          setActiveToolbarPanel("quick-reply");
          return;
        }

        if (!moreOpen) {
          setActiveToolbarPanel(null);
        }
      });
    };

    const observer = new MutationObserver(syncSelectorState);
    observer.observe(document.body, {
      subtree: true,
      attributes: true,
      attributeFilter: ["aria-expanded"],
      childList: true,
    });

    syncSelectorState();

    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, [activeToolbarPanel, moreOpen]);

  function clearRecordingTimer() {
    if (recordingTimerRef.current) {
      clearInterval(
        recordingTimerRef.current,
      );
      recordingTimerRef.current = null;
    }
  }

  function stopRecordingTracks() {
    for (
      const track of
      mediaStreamRef.current?.getTracks() ??
      []
    ) {
      track.stop();
    }

    mediaStreamRef.current = null;
  }

  function supportedRecordingMimeType() {
    if (
      typeof MediaRecorder ===
      "undefined"
    ) {
      return "";
    }

    /*
     * Safari and iOS do not support WebM/Ogg recording. Their MediaRecorder
     * produces audio/mp4 (AAC). Listing it here keeps the recorded blob type,
     * the file extension and the upload validation consistent on iPhone.
     */
    const candidates = [
      "audio/webm;codecs=opus",
      "audio/webm",
      "audio/ogg;codecs=opus",
      "audio/ogg",
      "audio/mp4",
    ];

    return (
      candidates.find(
        (candidate) =>
          MediaRecorder.isTypeSupported(
            candidate,
          ),
      ) ?? ""
    );
  }

  async function startVoiceRecording() {
    if (!composerMountedRef.current || recordingStartPendingRef.current) return;
    if (!allowAttachments) {
      setRecordingError(
        "Voice messages are available for Messenger conversations only.",
      );
      return;
    }

    if (
      typeof navigator ===
        "undefined" ||
      !navigator.mediaDevices
        ?.getUserMedia ||
      typeof MediaRecorder ===
        "undefined"
    ) {
      setRecordingError(
        "Voice recording is not supported by this browser.",
      );
      return;
    }

    if (
      recordingVoice ||
      isComposerDisabled ||
      (mediaRecorderRef.current && mediaRecorderRef.current.state !== "inactive")
    ) {
      return;
    }


    recordingStartPendingRef.current = true;
    setMoreOpen(false);

    clearToolbarPanel();
    setRecordingError(null);
    setVoiceReviewPlaying(false);
    setVoicePlaybackSeconds(0);

    try {
      const stream =
        await navigator.mediaDevices.getUserMedia(
          {
            audio: {
              echoCancellation: true,
              noiseSuppression: true,
              autoGainControl: true,
            },
          },
        );

      // Permission/device acquisition can resolve after this keyed composer
      // retired. Its cleanup ran before these tracks existed, so release them
      // here before constructing a recorder or scheduling a timer.
      if (!composerMountedRef.current) {
        for (const track of stream.getTracks()) track.stop();
        return;
      }
      // Own the stream before recorder construction so initialization failures
      // also release every acquired track through the existing catch cleanup.
      mediaStreamRef.current = stream;

      const mimeType =
        supportedRecordingMimeType();

      const recorder =
        mimeType
          ? new MediaRecorder(
              stream,
              {
                mimeType,
                audioBitsPerSecond:
                  128000,
              },
            )
          : new MediaRecorder(
              stream,
            );

      mediaRecorderRef.current =
        recorder;
      recordedChunksRef.current =
        [];
      discardRecordingRef.current =
        false;

      recorder.ondataavailable = (
        event,
      ) => {
        if (event.data.size > 0) {
          recordedChunksRef.current.push(
            event.data,
          );
        }
      };

      recorder.onstop = () => {
        const sendRecording = sendRecordingRef.current;
        sendRecordingRef.current = null;
        clearRecordingTimer();
        stopRecordingTracks();
        setRecordingVoice(false);
        setRecordingPaused(false);

        if (
          discardRecordingRef.current
        ) {
          recordedChunksRef.current =
            [];
          discardRecordingRef.current =
            false;
          return;
        }

        const actualType =
          recorder.mimeType ||
          mimeType ||
          "audio/webm";

        const blob = new Blob(
          recordedChunksRef.current,
          {
            type: actualType,
          },
        );

        recordedChunksRef.current =
          [];

        if (blob.size <= 0) {
          setRecordingError(
            "No audio was recorded. Please try again.",
          );
          return;
        }

        if (
          blob.size >
          TENH_ATTACHMENT_LIMITS.audio
        ) {
          setRecordingError(
            "Voice message is larger than 25 MB.",
          );
          return;
        }

        const extension =
          actualType.includes("ogg")
            ? "ogg"
            : actualType.includes("mp4") ||
                actualType.includes("aac")
              ? "m4a"
              : "webm";

        const file = new File(
          [blob],
          `voice-message-${Date.now()}.${extension}`,
          {
            type: actualType,
          },
        );

        const attachment:
          ReplyAttachment = {
          id: createId(),
          file,
          previewUrl:
            URL.createObjectURL(blob),
          kind: "audio",
        };

        if (sendRecording) {
          sendRecording(attachment);
          return;
        }

        setAttachments(
          (current) => [
            ...current,
            attachment,
          ],
        );

        setVoiceReview({
          attachmentId: attachment.id,
          durationSeconds: Math.max(1, recordingSecondsRef.current),
        });
        setVoiceReviewPlaying(false);
        setVoicePlaybackSeconds(0);
      };

      recorder.onerror = () => {
        clearRecordingTimer();
        stopRecordingTracks();
        setRecordingVoice(false);
        setRecordingPaused(false);
        setRecordingError(
          "Voice recording stopped because the browser reported an audio error.",
        );
      };

      recorder.start(250);
      recordingSecondsRef.current = 0;
      setRecordingSeconds(0);
      setRecordingPaused(false);
      setRecordingVoice(true);

      recordingTimerRef.current =
        setInterval(() => {
          if (
            mediaRecorderRef.current?.state !==
            "recording"
          ) {
            return;
          }

          setRecordingSeconds(
            (current) => {
              const next = current + 1;
              recordingSecondsRef.current = next;

              /*
               * Prevent accidental extremely long recordings.
               */
              if (
                next >= 300 &&
                mediaRecorderRef.current?.state ===
                  "recording"
              ) {
                mediaRecorderRef.current.stop();
              }

              return next;
            },
          );
        }, 1000);
    } catch (recordError) {
      stopRecordingTracks();
      if (!composerMountedRef.current) return;

      const errorName =
        recordError instanceof
        DOMException
          ? recordError.name
          : "";

      setRecordingError(
        errorName ===
          "NotAllowedError"
          ? "Microphone permission was denied. Allow microphone access in the browser and try again."
          : "Unable to start the microphone.",
      );
    } finally {
      recordingStartPendingRef.current = false;
    }
  }

  function pauseVoiceRecording() {
    const recorder = mediaRecorderRef.current;

    if (!recorder || recorder.state !== "recording") {
      return;
    }

    recorder.pause();
    setRecordingPaused(true);
  }

  function resumeVoiceRecording() {
    const recorder = mediaRecorderRef.current;

    if (!recorder || recorder.state !== "paused") {
      return;
    }

    recorder.resume();
    setRecordingPaused(false);
  }

  function finishVoiceRecording() {
    if (isComposerDisabled || !onSendAttachments) return;
    const recorder =
      mediaRecorderRef.current;

    if (
      !recorder ||
      recorder.state ===
        "inactive"
    ) {
      return;
    }

    discardRecordingRef.current =
      false;
    sendRecordingRef.current = (attachment) => { void sendVoiceReview(attachment); };
    recorder.stop();
  }

  function cancelVoiceRecording() {
    discardRecordingRef.current =
      true;

    const recorder =
      mediaRecorderRef.current;

    if (
      recorder &&
      recorder.state !==
        "inactive"
    ) {
      recorder.stop();
    } else {
      clearRecordingTimer();
      stopRecordingTracks();
      setRecordingVoice(false);
      setRecordingPaused(false);
    }

    recordingSecondsRef.current = 0;
    setRecordingSeconds(0);
    setVoiceReviewPlaying(false);
    setVoicePlaybackSeconds(0);
  }

  function getVoiceReviewAttachment() {
    if (!voiceReview) {
      return null;
    }

    return (
      attachments.find(
        (attachment) => attachment.id === voiceReview.attachmentId,
      ) ?? null
    );
  }

  function discardVoiceReview() {
    if (!voiceReview) {
      return;
    }

    const attachment = getVoiceReviewAttachment();

    if (voicePreviewAudioRef.current) {
      voicePreviewAudioRef.current.pause();
    }

    if (attachment) {
      URL.revokeObjectURL(attachment.previewUrl);
    }

    setAttachments((current) =>
      current.filter((item) => item.id !== voiceReview.attachmentId),
    );
    setVoiceReview(null);
    setVoiceReviewPlaying(false);
    setVoicePlaybackSeconds(0);
    recordingSecondsRef.current = 0;
    setRecordingSeconds(0);
  }

  function reRecordVoice() {
    discardVoiceReview();

    window.setTimeout(() => {
      void startVoiceRecording();
    }, 0);
  }

  async function toggleVoiceReviewPlayback() {
    const audio = voicePreviewAudioRef.current;

    if (!audio) {
      return;
    }

    if (voiceReviewPlaying) {
      audio.pause();
      setVoiceReviewPlaying(false);
      return;
    }

    try {
      await audio.play();
      setVoiceReviewPlaying(true);
    } catch {
      setVoiceReviewPlaying(false);
    }
  }

  async function sendVoiceReview(recordedAttachment?: ReplyAttachment) {
    const attachment = recordedAttachment ?? getVoiceReviewAttachment();

    if (!attachment || !onSendAttachments || isComposerDisabled) {
      return;
    }

    if (voicePreviewAudioRef.current) {
      voicePreviewAudioRef.current.pause();
    }

    const sentReview = recordedAttachment
      ? { attachmentId: recordedAttachment.id, durationSeconds: Math.max(1, recordingSecondsRef.current) }
      : voiceReview;
    setVoiceReview(null);
    setAttachments((current) => current.filter((item) => item.id !== attachment.id));
    const restoreVoice = () => {
      setAttachments((current) => current.some((item) => item.id === attachment.id) ? current : [...current, attachment]);
      setVoiceReview(sentReview);
    };
    setVoiceReviewPlaying(false);
    setSendingContent(true);
    setRecordingError(null);

    try {
      const success = await onSendAttachments([attachment]);

      if (!success) {
        restoreVoice();
        return;
      }

      URL.revokeObjectURL(attachment.previewUrl);
      setAttachments((current) =>
        current.filter((item) => item.id !== attachment.id),
      );
      setVoiceReview(null);
      setVoicePlaybackSeconds(0);
      recordingSecondsRef.current = 0;
      setRecordingSeconds(0);
    } catch (sendError) {
      restoreVoice();
      console.error(
        "Unable to send voice message:",
        sendError,
      );

      setRecordingError(
        "Unable to send voice message. Please try again.",
      );
    } finally {
      setSendingContent(false);
    }
  }

  useEffect(() => {
    return () => {
      if (voicePreviewAudioRef.current) {
        voicePreviewAudioRef.current.pause();
      }

      discardRecordingRef.current =
        true;

      const recorder =
        mediaRecorderRef.current;

      if (
        recorder &&
        recorder.state !==
          "inactive"
      ) {
        recorder.stop();
      }

      clearRecordingTimer();
      stopRecordingTracks();
    };
  }, []);

  /*
   * Safe post-send status action.
   * We only close/mark pending AFTER the parent send cycle finishes
   * without a send error. This reuses the existing status handler.
   */
  useEffect(() => {
    const wasSending =
      previousSendingRef.current;

    previousSendingRef.current =
      sending;

    if (
      !wasSending ||
      sending ||
      !pendingPostSendStatusRef.current
    ) {
      return;
    }

    const nextStatus =
      pendingPostSendStatusRef.current;

    pendingPostSendStatusRef.current =
      null;

    if (!error && onStatusChange) {
      onStatusChange(nextStatus);
      setSendMode("now");
    }
  }, [error, onStatusChange, sending]);

  function addAttachments(
    files: FileList | File[] | null,
    imagesOnly = false,
  ) {
    if (!files?.length) {
      return;
    }

    if (isComposerDisabled || !allowAttachments || attachmentsBlocked) {
      window.alert(blockedReason || attachmentsBlockedReason || "Attachments are unavailable in this conversation.");
      return;
    }

    const { accepted, rejected } = selectAttachments(files, {
      platform,
      imagesOnly,
      existingVideoCount: attachments.filter(
        (attachment) => attachment.kind === "video",
      ).length,
    });

    if (rejected.length > 0) {
      window.alert(
        `Some files could not be attached:\n${rejected
          .map(({ file, reason }) => `- ${file.name}: ${reason}`)
          .join("\n")}`,
      );
    }

    const newAttachments =
      accepted.map(({ file, kind }) => ({
        id: createId(),
        file,
        previewUrl:
          URL.createObjectURL(file),
        kind,
      }));

    setAttachments((current) => [
      ...current,
      ...newAttachments,
    ]);

    setMoreOpen(false);
    clearToolbarPanel();
  }

  async function sendWorkspaceFiles(files: File[]) {
    if (attachments.length > 0) {
      window.alert("Send or remove the current attachments before sending from Storage.");
      return false;
    }
    if (
      !files.length ||
      isSendDisabled ||
      !allowAttachments ||
      attachmentsBlocked ||
      !onSendAttachments
    ) {
      window.alert(blockedReason || attachmentsBlockedReason || "Attachments are unavailable in this conversation.");
      return false;
    }

    const { accepted, rejected } = selectAttachments(files, {
      platform,
      existingVideoCount: 0,
    });
    if (rejected.length || accepted.length !== files.length) {
      window.alert(
        `The selected Storage files cannot be sent together:\n${rejected
          .map(({ file, reason }) => `- ${file.name}: ${reason}`)
          .join("\n")}`,
      );
      return false;
    }

    const outgoing: ReplyAttachment[] = accepted.map(({ file, kind }) => ({
      id: createId(),
      file,
      previewUrl: URL.createObjectURL(file),
      kind,
    }));

    setSendingContent(true);
    try {
      return await onSendAttachments(outgoing);
    } catch {
      window.alert("Unable to send the selected Storage files. Please try again.");
      return false;
    } finally {
      for (const attachment of outgoing) URL.revokeObjectURL(attachment.previewUrl);
      setSendingContent(false);
    }
  }

  async function draftWorkspaceFiles(files: File[]) {
    if (attachmentConversationRef.current !== conversationId) {
      window.alert("The conversation changed while Storage files were loading. Please select them again.");
      return false;
    }
    if (
      !files.length ||
      isComposerDisabled ||
      !allowAttachments ||
      attachmentsBlocked
    ) {
      window.alert(blockedReason || attachmentsBlockedReason || "Attachments are unavailable in this conversation.");
      return false;
    }

    const currentAttachments = attachmentsRef.current;
    const { accepted, rejected } = selectAttachments(files, {
      platform,
      existingVideoCount: currentAttachments.filter(
        (attachment) => attachment.kind === "video",
      ).length,
    });
    if (rejected.length || accepted.length !== files.length) {
      window.alert(
        `The selected Storage files cannot be added to this draft:\n${rejected
          .map(({ file, reason }) => `- ${file.name}: ${reason}`)
          .join("\n")}`,
      );
      return false;
    }

    const staged: ReplyAttachment[] = accepted.map(({ file, kind }) => ({
      id: createId(),
      file,
      previewUrl: URL.createObjectURL(file),
      kind,
    }));
    setAttachments((current) => [...current, ...staged]);
    setMoreOpen(false);
    clearToolbarPanel();
    return true;
  }

  function handleImagePaste(event: ClipboardEvent<HTMLTextAreaElement>) {
    const files = clipboardImageFiles(event.clipboardData);
    if (!files.length) return; // Keep ordinary text/link paste completely native.
    event.preventDefault();
    // Reuse picker validation, size limits, previews and the existing send path.
    // Pasting attaches only; it never sends a message automatically.
    addAttachments(files, true);
  }

  function handleAttachmentChange(
    event: ChangeEvent<HTMLInputElement>,
  ) {
    addAttachments(event.target.files);
    event.target.value = "";
  }

  function removeAttachment(
    attachmentId: string,
  ) {
    setAttachments((current) => {
      const attachment =
        current.find(
          (item) =>
            item.id === attachmentId,
        );

      if (attachment) {
        URL.revokeObjectURL(
          attachment.previewUrl,
        );
      }

      return current.filter(
        (item) =>
          item.id !== attachmentId,
      );
    });
  }

  function clearAttachments() {
    setAttachments((current) => {
      for (const attachment of current) {
        URL.revokeObjectURL(
          attachment.previewUrl,
        );
      }

      return [];
    });
  }

  function insertEmoji(emoji: string) {
    const textarea = replyInputRef.current;

    if (!textarea) {
      onReplyChange(`${reply}${emoji}`);
      return;
    }

    /*
     * Insert at the caret (or replace the current selection) instead of
     * always appending to the end, then restore focus so the agent can keep
     * typing without clicking back into the box.
     */
    const start =
      textarea.selectionStart ?? reply.length;
    const end =
      textarea.selectionEnd ?? reply.length;
    const nextValue =
      `${reply.slice(0, start)}${emoji}${reply.slice(end)}`;
    const nextCaret = start + emoji.length;

    onReplyChange(nextValue);

    requestAnimationFrame(() => {
      const input = replyInputRef.current;

      if (!input) {
        return;
      }

      input.focus();
      input.setSelectionRange(nextCaret, nextCaret);
    });
  }

  function addLocation() {
    setMoreOpen(false);
    clearToolbarPanel();
    setLocationPickerOpen(true);
  }

  function confirmPickedLocation(location: PickedLocation) {
    const latitude = Number(location.latitude.toFixed(6));
    const longitude = Number(location.longitude.toFixed(6));
    const locationMessage =
      `https://www.google.com/maps?q=${latitude},${longitude}`;

    setLastPickedLocation({ latitude, longitude });
    onReplyChange(
      reply.trim()
        ? `${reply}\n${locationMessage}`
        : locationMessage,
    );
    setLocationPickerOpen(false);
  }

  function handleSubmit(
    event: FormEvent<HTMLFormElement>,
  ) {
    if (isComposerDisabled || stickerFlight.current) {
      event.preventDefault();
      return;
    }
    if (nativeSticker) {
      event.preventDefault();
      if (!online || loadingQuickReplyMedia || !onSendSticker) return;
      if (attachments.length) { setStickerNotice("Send or remove the attached files before sending this sticker."); return; }
      const choice = nativeSticker; const generation = stickerScope.current;
      stickerFlight.current = true; setStickerSending(true); setStickerNotice(null);
      void onSendSticker(choice).then(success => {
        if (stickerScope.current !== generation) return;
        // A failed outgoing bubble owns its Retry action. Do not leave another
        // copy in the composer and accidentally send the same sticker twice.
        setNativeSticker(null);
        if (!success) setStickerNotice("Sticker was not confirmed. Check the outgoing message before using Retry.");
        else if (reply.trim()) setStickerNotice("Sticker sent. Your text is still in the draft; press Send separately.");
      }).catch(() => {
        if (stickerScope.current === generation) setStickerNotice("Sticker could not be sent. Your draft is kept.");
      }).finally(() => {
        if (stickerScope.current === generation) { stickerFlight.current = false; setStickerSending(false); }
      });
      return;
    }

    if (
      !reply.trim() &&
      attachments.length === 0
    ) {
      event.preventDefault();
      return;
    }

    /* Its media is still arriving; sending now would send the text alone. */
    if (loadingQuickReplyMedia) {
      event.preventDefault();
      return;
    }

    /* Nothing would leave the browser, and the draft would be cleared for it. */
    if (!online) {
      event.preventDefault();
      return;
    }

    const postSendStatus:
      | ConversationStatus
      | null =
      sendMode === "close"
        ? "closed"
        : sendMode === "pending"
          ? "pending"
          : null;

    pendingPostSendStatusRef.current =
      postSendStatus;


    if (attachments.length > 0) {
      event.preventDefault();
      void sendAttachments(
        postSendStatus,
      );
      return;
    }

    onSubmit(event);
  }

  async function sendAttachments(
    postSendStatus:
      | ConversationStatus
      | null = null,
  ) {
    if (
      isComposerDisabled ||
      !onSendAttachments ||
      attachments.length === 0
    ) {
      return;
    }

    setSendingContent(true);

    /*
     * Empty the composer the moment sending starts.
     *
     * The parent puts a "Sending" bubble on screen for every item -- each
     * photo, the video or voice clip, and the text -- before any upload
     * starts, then reports each one's success or failure on that bubble with
     * its own Retry. Once that has happened (onQueued), the composer must never
     * be refilled: a second copy here plus a failed bubble there was how a
     * partial failure became a duplicate. The composer is only restored when
     * nothing was queued at all, i.e. the send was refused before it began.
     */
    const sentAttachments = attachments;
    const sentReply = reply;
    let queued = false;

    setAttachments([]);
    onReplyChange("");

    try {
      const success =
        await onSendAttachments(
          sentAttachments,
          sentReply.trim() || undefined,
          { onQueued: () => { queued = true; } },
        );

      if (!success && !queued) {
        setAttachments(sentAttachments);
        onReplyChange(sentReply);
        pendingPostSendStatusRef.current = null;
        return;
      }

      for (const attachment of sentAttachments) {
        URL.revokeObjectURL(
          attachment.previewUrl,
        );
      }

      pendingPostSendStatusRef.current = null;

      if (
        postSendStatus &&
        onStatusChange
      ) {
        onStatusChange(postSendStatus);
        setSendMode("now");
      }
    } catch (sendError) {
      if (!queued) {
        /* Give the agent back exactly what they were about to send. */
        setAttachments(sentAttachments);
        onReplyChange(sentReply);
      }

      console.error(
        "Unable to send attachments:",
        sendError,
      );

      window.alert(
        queued
          ? "Some items could not be sent. Use Retry on the failed message."
          : "Unable to send attachments.",
      );
    } finally {
      setSendingContent(false);
    }
  }

  useEffect(() => {
    const textarea = replyInputRef.current;

    if (!textarea) {
      return;
    }

    textarea.style.height = "48px";
    const nextHeight = Math.min(128, Math.max(48, textarea.scrollHeight));
    textarea.style.height = `${nextHeight}px`;
    textarea.style.overflowY = textarea.scrollHeight > 128 ? "auto" : "hidden";
  }, [reply]);


  return (
    <div data-inbox-composer className="shrink-0 w-full border border-slate-200 bg-white">
      {/*
        Say that the media is coming, rather than leaving a disabled Send with
